function loadWorldGenForTest() {
  return new Function(`${worldGenerationContent}\nreturn WorldGen;`)();
}

function loadNarrationSystemForTest(windowOverrides = {}) {
  const window = { setTimeout, clearTimeout, ...windowOverrides };
  const CONTENT = { preferences: { posture: 'sfw', enabledCategories: [], gameplayVariants: {} } };
  const MODULE_SYSTEM = {
    _publicSceneBeatSummary(event) { return JSON.parse(JSON.stringify(event)); },
    _publicNarrativeUnitSummary(unit) { return { id: unit.id, name: unit.name }; },
    _publicQuestSummary() { return null; },
    _publicActivitySummary() { return null; },
    async executePublicHook() {}
  };
  return new Function('window', 'CONTENT', 'MODULE_SYSTEM', `${narrationSystemContent}\nreturn { YAW_NARRATION_SYSTEM, YAW_AI_PROVIDER_MANAGER };`)(window, CONTENT, MODULE_SYSTEM);
}

function createMemoryStorage() {
  const records = new Map();
  return {
    getItem(key) { return records.has(key) ? records.get(key) : null; },
    setItem(key, value) { records.set(key, String(value)); },
    removeItem(key) { records.delete(key); },
    serialized() { return JSON.stringify([...records.entries()]); }
  };
}

function providerResponse(status, payload, type = 'basic') {
  return {
    ok: status >= 200 && status < 300,
    status,
    type,
    async text() { return JSON.stringify(payload); }
  };
}

function loadOpenAIProviderForTest(fetchImpl, storage = createMemoryStorage(), windowOverrides = {}) {
  const window = { setTimeout, clearTimeout, localStorage: storage, fetch: fetchImpl, ...windowOverrides };
  const CONTENT = { preferences: { posture: 'sfw', enabledCategories: [], gameplayVariants: {} } };
  const MODULE_SYSTEM = {
    _publicSceneBeatSummary(event) { return JSON.parse(JSON.stringify(event)); },
    _publicNarrativeUnitSummary(unit) { return { id: unit.id, name: unit.name }; },
    _publicQuestSummary() { return null; },
    _publicActivitySummary() { return null; },
    async executePublicHook() {}
  };
  const runtime = new Function(
    'window', 'CONTENT', 'MODULE_SYSTEM',
    `${narrationSystemContent}\nreturn { YAW_NARRATION_SYSTEM, YAW_AI_PROVIDER_MANAGER };`
  )(window, CONTENT, MODULE_SYSTEM);
  const provider = new Function(
    'window', 'YAW_AI_PROVIDER_MANAGER',
    `${openAICompatibleProviderContent}\nreturn YAW_OPENAI_COMPATIBLE_PROVIDER;`
  )(window, runtime.YAW_AI_PROVIDER_MANAGER);
  return { ...runtime, provider, storage, window };
}

function createPackagedNarrationHarness(packagePaths, initialSettings = {}, contextForExchange = () => ({ characters: [] })) {
  const hooks = new Map();
  const orchestrators = [];
  const narrations = [];
  const requests = [];
  const actions = new Map();
  const tileNarrationCache = new Map();
  const settings = new Map(Object.entries(initialSettings));
  const connections = [{ id: 'connection-1', providerId: 'fake' }];
  let cancelCount = 0;

  for (const packagePath of packagePaths) {
    const packageData = JSON.parse(fs.readFileSync(packagePath, 'utf8'));
    const moduleId = packageData.module.manifest.id;
    const key = name => `${moduleId}:${name}`;
    const MODS = {
      id: moduleId,
      registerHook(event, callback) {
        if (!hooks.has(event)) hooks.set(event, []);
        hooks.get(event).push({ moduleId, callback });
      },
      registerNarrationOrchestrator(config) { orchestrators.push({ moduleId, ...config }); },
      async ownsNarrationExchange(envelope) {
        const policy = envelope?.policy || { posture: 'sfw', enabledCategories: [] };
        const candidates = orchestrators
          .filter(item => item.minPosture !== 'mature' || policy.posture === 'mature')
          .filter(item => (item.requiredCategories || []).every(category => policy.enabledCategories.includes(category)))
          .sort((a, b) => (b.priority || 0) - (a.priority || 0));
        for (const candidate of candidates) {
          if (candidate.isActive && !(await candidate.isActive(policy))) continue;
          if (typeof candidate.claimsExchange === 'function' && !(await candidate.claimsExchange(envelope))) continue;
          return candidate.moduleId === moduleId;
        }
        return false;
      },
      registerSettingAction(name, callback) { actions.set(key(name), callback); },
      getSetting(name, fallback) { return Promise.resolve(settings.has(key(name)) ? settings.get(key(name)) : fallback); },
      setSetting(name, value) { settings.set(key(name), value); return Promise.resolve(); },
      publishNarration(record) {
        const stored = { ...record, ownerModuleId: moduleId };
        narrations.push(stored);
        return stored;
      },
      updateNarration(id, patch) {
        const record = narrations.find(item => item.id === id && item.ownerModuleId === moduleId);
        if (!record) throw new Error('Narration not found');
        Object.assign(record, patch);
        return record;
      },
      clearNarrations() {
        for (let index = narrations.length - 1; index >= 0; index--) {
          if (narrations[index].ownerModuleId === moduleId) narrations.splice(index, 1);
        }
      },
      getCachedTileNarration({ targetId, variant }) {
        const cached = tileNarrationCache.get(`${moduleId}:${targetId}:${variant}`);
        return cached ? JSON.parse(JSON.stringify(cached)) : null;
      },
      cacheTileNarration(narrationId, { variant }) {
        const record = narrations.find(item => item.id === narrationId && item.ownerModuleId === moduleId);
        if (!record || record.status !== 'ready') return null;
        const cached = { ...record };
        tileNarrationCache.set(`${moduleId}:${record.targetId}:${variant}`, cached);
        return JSON.parse(JSON.stringify(cached));
      },
      log(message) { requests.push({ moduleId, diagnostic: String(message) }); },
      getNarrationContext({ exchangeId }) { return contextForExchange(exchangeId); },
      ai: {
        listConnections() { return connections.map(connection => ({ ...connection })); },
        async generate(request) {
          requests.push({ moduleId, request: JSON.parse(JSON.stringify(request)) });
          return { text: `Narrated by ${moduleId}.`, providerId: 'fake', modelId: 'fake-v1' };
        },
        cancelPending() { cancelCount++; }
      }
    };
    new Function('MODS', packageData.module.code)(MODS);
  }

  return {
    hooks, narrations, requests, settings, actions, tileNarrationCache,
    get cancelCount() { return cancelCount; },
    async fire(event, envelope) {
      await Promise.all((hooks.get(event) || []).map(hook => hook.callback(JSON.parse(JSON.stringify(envelope)))));
    }
  };
}

