function createFakeIndexedDb(options = {}) {
  const data = {
    modules: new Map(),
    assets: new Map(),
    settings: new Map(),
    mediaPayloads: new Map(),
    mediaStaging: new Map(),
    mediaCatalog: new Map(),
    mediaRefs: new Map(),
    mediaOwners: new Map()
  };

  function clone(value) {
    if (value === undefined || value === null) return value;
    return typeof structuredClone === 'function' ? structuredClone(value) : JSON.parse(JSON.stringify(value));
  }

  function createRequest(tx, operation) {
    const request = { result: undefined, error: null, onsuccess: null, onerror: null };
    tx._pending++;
    setTimeout(() => {
      try {
        request.result = operation();
        tx._pending--;
        if (request.onsuccess) request.onsuccess({ target: request });
        tx._scheduleComplete();
      } catch (error) {
        request.error = error;
        tx.error = error;
        tx._pending--;
        if (request.onerror) request.onerror({ target: request });
        if (tx.onerror) tx.onerror({ target: tx });
      }
    }, 0);
    return request;
  }

  function createStore(name, tx) {
    const store = data[name];
    return {
      get(key) {
        return createRequest(tx, () => clone(store.get(key)));
      },
      getAll(query) {
        return createRequest(tx, () => {
          const values = Array.from(store.values());
          return clone(values);
        });
      },
      put(value) {
        return createRequest(tx, () => {
          const key = value.id !== undefined
            ? value.id
            : value.key !== undefined
              ? value.key
              : value.ownerId !== undefined
                ? value.ownerId
                : value.hash;
          if (typeof options.onPut === 'function') options.onPut(name, clone(value), key);
          store.set(key, clone(value));
          return key;
        });
      },
      delete(key) {
        return createRequest(tx, () => {
          store.delete(key);
          return undefined;
        });
      },
      index(indexName) {
        return {
          getAll(query) {
            return createRequest(tx, () => clone(Array.from(store.values()).filter(value => value[indexName] === query)));
          }
        };
      }
    };
  }

  return {
    data,
    db: {
      transaction(storeNames) {
        const tx = {
          error: null,
          oncomplete: null,
          onerror: null,
          onabort: null,
          _pending: 0,
          _completed: false,
          _scheduleComplete() {
            if (this._completed) return;
            setTimeout(() => {
              if (this._pending === 0 && !this._completed) {
                this._completed = true;
                if (this.oncomplete) this.oncomplete({ target: this });
              }
            }, 0);
          },
          objectStore(name) {
            assert(Array.isArray(storeNames) ? storeNames.includes(name) : storeNames === name, `Store ${name} not in transaction`);
            return createStore(name, tx);
          }
        };
        return tx;
      }
    }
  };
}

