asyncTest('Persisted enabled modules restore their runtime hooks after refresh', async () => {
  const MODULE_SYSTEM = loadModuleSystemForTest();
  MODULE_SYSTEM.db = createFakeIndexedDb().db;
  await MODULE_SYSTEM.installModule({
    manifest: { id: 'restore-module', name: 'Restore Module', version: '1.0.0' },
    code: `MODS.registerHook('onTick', payload => payload.calls.push('restored'));`
  });
  await MODULE_SYSTEM.setModuleEnabled('restore-module', true);
  MODULE_SYSTEM.unloadModule('restore-module');
  assert(!MODULE_SYSTEM.activeModules.has('restore-module'), 'Refresh simulation should begin without the persisted module runtime');
  const before = { calls: [] };
  await MODULE_SYSTEM.executeHook('onTick', before);
  assertEqual(before.calls.length, 0, 'Unloaded runtime hooks should not run before restoration');
  const restored = await MODULE_SYSTEM.loadEnabledModules();
  assertEqual(restored.join(','), 'restore-module', 'Startup restoration should load the persisted enabled module');
  const after = { calls: [] };
  await MODULE_SYSTEM.executeHook('onTick', after);
  assertEqual(after.calls.join(','), 'restored', 'Restored module hooks should receive new gameplay events');
  assertContains(appContent, 'MODULE_SYSTEM.loadEnabledModules()', 'App startup should restore enabled modules after content preferences load');
  assertContains(contentSystemContent, "'mod.restoreFailed': 'Enabled modules could not be restored", 'Enabled-module restore failures should have Activity Log guidance');
});

test('Narrative modules receive bounded serializable public context', () => {
  const MODULE_SYSTEM = loadModuleSystemForTest({ CONTENT: { preferences: {
    posture: 'mature', maxTier: 1, language: 'es', enabledCategories: ['optional.story'],
    gameplayVariants: { 'story.branching': true, 'story.disabled': false }
  } } });
  const App = MODULE_SYSTEM._testApp;
  const player = {
    id: 'context-player', name: 'You', species: 'human', disposition: 'PARTY', level: 2,
    CPun: 80, MPun: 100, CPle: 30, MPle: 100, hunger: 20, size: 4,
    combatRow: 'front', ranged: true, parts: 'hidden-anatomy', stomach: [{ id: 'hidden-prey' }],
    status: { burning: { turns: 2 }, asleep: null }
  };
  App.location = { x: 3, y: -2 };
  App.combatState = { active: true };
  App.party = [player];
  App.creatures = [{ id: 'context-target', name: 'Target', species: 'siren', disposition: 'ENEMY', CPun: 40, MPun: 80, CPle: 5, MPle: 50, hunger: 0, size: 3, combatRow: 'back' }];
  App.quests = [{ id: 'context-quest', title: 'Find the Road', status: 'active', progress: 1, required: 3, objective: { type: 'travel', x: 8, y: 2 } }];
  App.storyEvents = [{ id: 'beat-1', mode: 'combat', action: 'fight', shape: 'one-to-one', resultKind: 'damage', summary: 'A clean hit.', actors: [player], targets: App.creatures, deltas: [{ type: 'punishment', amount: 4 }], tags: ['combat'], importance: 'normal', source: 'interaction-result' }];
  App.log = [{ text: 'Combat started.', type: 'combat', round: 1, turn: 1, actorId: 'context-player' }];
  App.getTileMapSummary = () => ({ x: 3, y: -2, displayBiome: 'Forest', explored: true, danger: 'nearby threat' });

  const api = MODULE_SYSTEM.createModAPI('context-reader', { permissions: ['ui.read'] });
  const context = api.getContext({ limit: 5 });
  assertEqual(context.version, 1, 'Public context should expose a versioned contract');
  assertEqual(context.mode, 'combat', 'Public context should expose deterministic game mode');
  assertEqual(context.content.posture, 'mature', 'Public context should expose active content posture');
  assertEqual(context.content.language, 'es', 'Public context should expose active language policy');
  assertEqual(context.content.enabledCategories.join(','), 'optional.story', 'Public context should expose opted-in content categories');
  assertEqual(Object.keys(context.content.gameplayVariants).join(','), 'story.branching', 'Public context should expose only enabled gameplay variants');
  assertEqual(context.party[0].statuses.join(','), 'burning', 'Public unit summary should expose normalized active status names');
  assertEqual(context.sceneBeats[0].actors[0].id, 'context-player', 'Scene Beat summaries should replace raw unit references with public unit summaries');
  assertEqual(context.location.tile.displayBiome, 'Forest', 'Public context should reuse safe tile map summaries');
  const serialized = JSON.stringify(context);
  assertNotContains(serialized, 'hidden-anatomy', 'Public context should not expose compatibility anatomy fields');
  assertNotContains(serialized, 'hidden-prey', 'Public context should not expose containment internals');
  assertEqual(JSON.parse(serialized).quests[0].id, 'context-quest', 'Public context should remain JSON serializable');

  let denied = false;
  try {
    MODULE_SYSTEM.createModAPI('context-denied', { permissions: [] }).getContext();
  } catch (e) {
    denied = true;
    assertContains(e.message, 'ui.read', 'Public context denial should name the required permission');
  }
  assertEqual(denied, true, 'Modules without ui.read should not receive public context');
});

asyncTest('Module unload clears trusted-local runtime timers', async () => {
  const scheduledTimeouts = new Set();
  const scheduledIntervals = new Set();
  const clearedTimeouts = [];
  const clearedIntervals = [];
  let nextTimerId = 1;
  const MODULE_SYSTEM = loadModuleSystemForTest({
    window: {
      setTimeout() {
        const id = `timeout-${nextTimerId++}`;
        scheduledTimeouts.add(id);
        return id;
      },
      clearTimeout(id) {
        clearedTimeouts.push(id);
        scheduledTimeouts.delete(id);
      },
      setInterval() {
        const id = `interval-${nextTimerId++}`;
        scheduledIntervals.add(id);
        return id;
      },
      clearInterval(id) {
        clearedIntervals.push(id);
        scheduledIntervals.delete(id);
      }
    }
  });
  const fakeDb = createFakeIndexedDb();
  MODULE_SYSTEM.db = fakeDb.db;

  await MODULE_SYSTEM.installModule({
    manifest: { id: 'timer-module', name: 'Timer Module', version: '1.0.0' },
    code: `
      const timeoutId = setTimeout(() => MODS.log('timeout'), 1000);
      const intervalId = setInterval(() => MODS.log('interval'), 1000);
      clearTimeout(timeoutId);
      setTimeout(() => MODS.log('second timeout'), 1000);
    `
  });
  await MODULE_SYSTEM.setModuleEnabled('timer-module', true);
  assertEqual(scheduledTimeouts.size, 1, 'Enabled module should track uncleared runtime timeouts');
  assertEqual(scheduledIntervals.size, 1, 'Enabled module should track runtime intervals');
  assertEqual(clearedTimeouts.length, 1, 'Module clearTimeout should delegate to the host clearTimeout');

  await MODULE_SYSTEM.setModuleEnabled('timer-module', false);
  assertEqual(scheduledTimeouts.size, 0, 'Disabling module should clear remaining runtime timeouts');
  assertEqual(scheduledIntervals.size, 0, 'Disabling module should clear runtime intervals');
  assertEqual(clearedTimeouts.length, 2, 'Disabling module should clear tracked timeout handles');
  assertEqual(clearedIntervals.length, 1, 'Disabling module should clear tracked interval handles');

  await MODULE_SYSTEM.installModule({
    manifest: { id: 'failing-timer-module', name: 'Failing Timer Module', version: '1.0.0' },
    code: `
      setTimeout(() => MODS.log('leaked timeout'), 1000);
      setInterval(() => MODS.log('leaked interval'), 1000);
      throw new Error('timer load failed');
    `
  });
  let rejected = false;
  try {
    await MODULE_SYSTEM.setModuleEnabled('failing-timer-module', true);
  } catch (e) {
    rejected = true;
    assertContains(e.message, 'timer load failed', 'Failing timer module should surface load failure');
  }
  assertEqual(rejected, true, 'Failing timer module should reject enable');
  assertEqual(scheduledTimeouts.size, 0, 'Failed module load should clear partial timeout handles');
  assertEqual(scheduledIntervals.size, 0, 'Failed module load should clear partial interval handles');
  assertEqual(MODULE_SYSTEM.activeModules.has('failing-timer-module'), false, 'Failed timer module should not remain active');
});

asyncTest('Failed enabled module reload persists disabled rollback state', async () => {
  const MODULE_SYSTEM = loadModuleSystemForTest();
  const modulePuts = [];
  const fakeDb = createFakeIndexedDb({
    onPut(storeName, value) {
      if (storeName === 'modules' && value.id === 'stale-enabled-module') {
        modulePuts.push(value.enabled);
      }
    }
  });
  MODULE_SYSTEM.db = fakeDb.db;

  await MODULE_SYSTEM.installModule({
    manifest: { id: 'stale-enabled-module', name: 'Stale Enabled Module', version: '1.0.0' },
    code: "throw new Error('stored runtime failed');"
  });
  const stored = fakeDb.data.modules.get('stale-enabled-module');
  stored.enabled = true;
  fakeDb.data.modules.set('stale-enabled-module', stored);

  let rejected = false;
  try {
    await MODULE_SYSTEM.setModuleEnabled('stale-enabled-module', true);
  } catch (e) {
    rejected = true;
    assertContains(e.message, 'stored runtime failed', 'Failed enabled reload should surface runtime failure');
  }
  assertEqual(rejected, true, 'Failed enabled reload should reject');
  assertEqual(MODULE_SYSTEM.activeModules.has('stale-enabled-module'), false, 'Failed enabled reload should not leave runtime active');
  assertEqual(modulePuts.includes(false), true, 'Failed enabled reload should persist disabled rollback state');
  const reloaded = (await MODULE_SYSTEM.getAllModules()).find(mod => mod.id === 'stale-enabled-module');
  assertEqual(reloaded.enabled, false, 'Stored module should be disabled after failed enabled reload');
});

