test('Content resolver falls back when higher tier templates are gated or unavailable', () => {
  const CONTENT = loadContentSystemForTest();
  CONTENT.registerTemplate('test', 'rating', 'default', {
    safe: () => 'safe text',
    mature: () => 'mature text',
    adult: () => null
  });

  CONTENT.setMaxTier(CONTENT.TIERS.ADULT);
  CONTENT.setPreference('explicitDescriptions', true);
  assertEqual(CONTENT.getContent('test.rating'), 'mature text', 'Null adult template should fall back to mature text');

  CONTENT.registerTemplate('test', 'explicitGate', 'default', {
    safe: () => 'safe text',
    mature: () => 'mature text',
    adult: () => 'adult text'
  });
  CONTENT.setPreference('explicitDescriptions', false);
  assertEqual(CONTENT.getContent('test.explicitGate'), 'mature text', 'Adult tier should be skipped when explicit descriptions are disabled');

  CONTENT.setPreference('voreEnabled', false);
  assertEqual(CONTENT.getContent('test.explicitGate', { voreEnabled: true }), 'safe text', 'Vore-gated context should fall back to safe text when vore is disabled');
});

test('Content preference loading normalizes stored policy values', () => {
  const CONTENT = loadContentSystemForTest({
    'yaw-content-prefs': JSON.stringify({
      maxTier: '99',
      voreEnabled: 'true',
      explicitDescriptions: 'true',
      filterTags: ['safe_tag', 'bad tag', 'safe_tag', 'mature:tag'],
      language: 'missing',
      unexpected: 'kept'
    })
  });
  assertEqual(CONTENT.preferences.maxTier, CONTENT.TIERS.ADULT, 'Stored max tier should clamp to the highest known tier');
  assertEqual(CONTENT.preferences.voreEnabled, false, 'String truthy values should not enable gated content flags');
  assertEqual(CONTENT.preferences.explicitDescriptions, false, 'String truthy values should not enable explicit descriptions');
  assertEqual(CONTENT.preferences.filterTags.join(','), 'safe_tag,mature:tag', 'Filter tags should keep only valid unique token tags');
  assertEqual(CONTENT.preferences.language, 'en', 'Unknown language should fall back to English');
  assertEqual(CONTENT.preferences.unexpected, undefined, 'Unknown preference keys should be dropped');

  const stored = JSON.parse(CONTENT.__testStorage.get('yaw-content-prefs'));
  assertEqual(stored.unexpected, undefined, 'Normalized preferences should be written back without unknown keys');
  assertEqual(stored.voreEnabled, false, 'Normalized preferences should persist sanitized booleans');

  const malformed = loadContentSystemForTest({ 'yaw-content-prefs': '{bad json' });
  assertEqual(malformed.preferences.maxTier, malformed.TIERS.SAFE, 'Malformed preference JSON should reset to safe defaults');
  assertEqual(malformed.preferences.posture, malformed.POSTURES.SFW, 'Malformed preference JSON should reset to SFW posture');
  assertEqual(malformed.preferences.voreEnabled, true, 'Malformed preference JSON should retain neutral core consumption');
  assertEqual(JSON.parse(malformed.__testStorage.get('yaw-content-prefs')).maxTier, malformed.TIERS.SAFE, 'Malformed preference JSON should be overwritten with safe defaults');
});

test('Locale Pack V1 restores a pending module locale and falls back safely on unload', () => {
  const CONTENT = loadContentSystemForTest({
    'yaw-content-prefs': JSON.stringify({ language: 'qps-ploc' })
  });
  assertEqual(CONTENT.preferences.language, 'en', 'An unavailable stored module locale should use English during startup');
  assertEqual(CONTENT.pendingLanguage, 'qps-ploc', 'A valid unavailable locale id should remain pending for module restoration');

  CONTENT.registerLocale('pseudo-pack', {
    id: 'qps-ploc',
    displayName: 'Pseudo Locale',
    fallback: 'en',
    targets: [{ moduleId: 'core', minVersion: '0.14.0' }]
  });
  CONTENT.registerLocaleEntries('qps-ploc', { 'settings.language': '[Language]' });
  assertEqual(CONTENT.preferences.language, 'qps-ploc', 'Registering the pending owned locale should restore the player selection');
  assertEqual(CONTENT.t('settings.language'), '[Language]', 'Owned locale entries should override the fallback locale');
  assertEqual(CONTENT.t('action.fight'), 'Fight', 'Missing owned locale entries should fall back to English');
  assertEqual(CONTENT.localeCatalog().some(locale => locale.id === 'qps-ploc'), true, 'Owned locales should appear in the dynamic locale catalog');

  const removal = CONTENT.unregisterLocale('qps-ploc', 'pseudo-pack');
  assertEqual(removal.languageChanged, true, 'Unloading the selected locale should report a language transition');
  assertEqual(CONTENT.preferences.language, 'en', 'Unloading the selected locale should return to its available fallback');
  assertEqual(CONTENT.localeCatalog().some(locale => locale.id === 'qps-ploc'), false, 'Unloaded locale definitions should leave the dynamic catalog');
});

test('Content policy catalog deduplicates provider declarations and persists category and variant choices', () => {
  const CONTENT = loadContentSystemForTest();
  CONTENT.registerPolicyProvider('provider-a', {
    name: 'Provider A',
    contentCategories: [{ id: 'optional.story', label: 'Optional Story', required: true }],
    gameplayVariants: [{ id: 'story.branching', label: 'Branching Story' }]
  }, { installed: true, enabled: false });
  CONTENT.registerPolicyProvider('provider-b', {
    name: 'Provider B',
    contentCategories: [{ id: 'optional.story', label: 'Optional Story', required: false }],
    gameplayVariants: [{ id: 'story.branching', label: 'Branching Story' }]
  }, { installed: true, enabled: true });

  const catalog = CONTENT.policyCatalog();
  const category = catalog.categories.find(entry => entry.id === 'optional.story');
  const variant = catalog.variants.find(entry => entry.id === 'story.branching');
  assertEqual(category.providers.length, 2, 'Shared category should list both providers without duplicate settings rows');
  assertEqual(category.required, true, 'Shared category should remain required when any provider requires opt-in');
  assertEqual(variant.providers.length, 2, 'Shared variant should list both providers without duplicate settings rows');

  CONTENT.setCategoryEnabled('optional.story', true);
  CONTENT.setGameplayVariant('story.branching', true);
  assertEqual(CONTENT.isCategoryEnabled('optional.story'), true, 'Category opt-in should update runtime policy');
  assertEqual(CONTENT.preferences.gameplayVariants['story.branching'], true, 'Gameplay variant choice should update runtime policy');
  const stored = JSON.parse(CONTENT.__testStorage.get('yaw-content-prefs'));
  assertEqual(stored.enabledCategories.join(','), 'optional.story', 'Category opt-in should persist');
  assertEqual(stored.gameplayVariants['story.branching'], true, 'Gameplay variant choice should persist');
});

test('Explicit provider category can supply adult template tiers without creating a core Adult posture', () => {
  const CONTENT = loadContentSystemForTest();
  CONTENT.registerTemplate('test', 'providerTier', 'default', {
    safe: () => 'safe text',
    mature: () => 'mature text',
    adult: () => 'provider explicit text'
  });
  CONTENT.setPosture('mature');
  assertEqual(CONTENT.getContent('test.providerTier'), 'mature text', 'Mature posture alone should not select provider explicit prose');
  CONTENT.setCategoryEnabled('explicit.sexual', true);
  assertEqual(CONTENT.getContent('test.providerTier'), 'provider explicit text', 'Explicit category opt-in should unlock provider explicit prose');
  assertEqual(CONTENT.preferences.posture, 'mature', 'Explicit category should not create or select a third core posture');
  assertEqual(CONTENT.preferences.maxTier, CONTENT.TIERS.MATURE, 'Explicit category should preserve the mature legacy tier value');
});

test('Content template registration rejects malformed template definitions', () => {
  const CONTENT = loadContentSystemForTest();

  let rejected = false;
  try {
    CONTENT.registerTemplate('bad category', 'type', 'default', {
      safe: () => 'bad'
    });
  } catch (e) {
    rejected = true;
    assertContains(e.message, 'category', 'Invalid template category should report category validation');
  }
  assertEqual(rejected, true, 'Invalid template category should reject');
  assertEqual(CONTENT.templates['bad category'], undefined, 'Rejected category should not mutate the template registry');

  rejected = false;
  try {
    CONTENT.registerTemplate('test', 'badTier', 'default', {
      safe: () => 'safe',
      unsafe: () => 'bad'
    });
  } catch (e) {
    rejected = true;
    assertContains(e.message, 'safe, mature, adult', 'Unknown template tiers should report allowed tiers');
  }
  assertEqual(rejected, true, 'Unknown template tier should reject');
  assertEqual(CONTENT.templates.test?.badTier, undefined, 'Rejected tier set should not mutate the template registry');

  rejected = false;
  try {
    CONTENT.registerTemplate('test', 'badValue', 'default', {
      safe: 'plain text'
    });
  } catch (e) {
    rejected = true;
    assertContains(e.message, 'function or null', 'Non-function template tiers should report type validation');
  }
  assertEqual(rejected, true, 'Non-function template tier should reject');
  assertEqual(CONTENT.templates.test?.badValue, undefined, 'Rejected template value should not mutate the template registry');

  rejected = false;
  try {
    CONTENT.registerTemplate('test', 'empty', 'default', {
      safe: null,
      mature: null,
      adult: null
    });
  } catch (e) {
    rejected = true;
    assertContains(e.message, 'at least one renderable tier', 'All-null template registration should report missing renderable tier');
  }
  assertEqual(rejected, true, 'All-null template registration should reject');
  assertEqual(CONTENT.templates.test?.empty, undefined, 'Rejected all-null template should not mutate the registry');
});

test('Built-in content pack handles retain core and mature examples without bundling explicit content', () => {
  const registered = [];
  const CONTENT = {
    preferences: { maxTier: 0, explicitDescriptions: false },
    registerTemplate(category, type, variant, templates) {
      registered.push({ category, type, variant, templates });
    }
  };
  const packs = loadContentPacksForTest(CONTENT);
  const baseRegistrations = registered.length;

  assert(baseRegistrations > 0, 'Core content pack should still install automatically');
  assertEqual(packs.species.canInstall(), false, 'Mature optional content pack should not install while policy is safe');
  assertContains(packs.species.blockReason(), 'higher content tier', 'Blocked mature content pack should report tier policy');

  let rejected = false;
  try {
    packs.species.install();
  } catch (e) {
    rejected = true;
    assertContains(e.message, 'higher content tier', 'Mature content pack install should report tier policy');
  }
  assertEqual(rejected, true, 'Safe policy should reject mature optional content pack install');
  assertEqual(registered.length, baseRegistrations, 'Rejected content pack should not register templates');

  CONTENT.preferences.maxTier = 1;
  packs.species.install();
  assert(registered.length > baseRegistrations, 'Mature policy should allow mature optional content pack install');
  assertEqual(packs.adult, undefined, 'Default game should not expose a bundled Adult content pack handle');
  assertNotContains(marketplaceContent, 'ADULT_CONTENT_PACK', 'Default marketplace source should not bundle an explicit content provider');
});

