test('Settings overlay returns to a centered active main menu from the menu route', () => {
  const screenIds = ['screen-menu', 'screen-settings', 'screen-game', 'screen-create', 'screen-mods', 'screen-market', 'save-manager'];
  const { App, document } = loadAppForCombat(() => 0.5, {
    querySelectorAll(selector, elements) {
      if (selector !== '.screen') return [];
      return screenIds.map(id => {
        if (!elements.has(id)) elements.set(id, makeElement());
        return elements.get(id);
      });
    }
  });
  const appShell = document.getElementById('app');
  const game = document.getElementById('screen-game');
  const menu = document.getElementById('screen-menu');
  const settings = document.getElementById('screen-settings');
  App.player = makeUnit('Existing Player', { CPun: 80, MPun: 100 });
  App.party = [App.player];
  App.screen = 'menu';
  menu.style.display = 'flex';
  menu.classList.add('active');
  game.style.display = 'none';
  game.classList.remove('active');

  App.openSettingsFromMenu();
  assertEqual(App.screen, 'settings', 'Settings should become the active screen');
  assertEqual(App.settingsReturnScreen, 'menu', 'Settings opened from the menu should remember the menu return target');
  assertEqual(menu.style.display, 'none', 'Menu should be hidden while settings is open');
  assertEqual(menu.classList.contains('active'), false, 'Menu should not stay active behind settings');

  App.returnToGame();
  assertEqual(App.screen, 'menu', 'Closing settings from the main menu should restore menu screen state even with a living player');
  assertEqual(appShell.style.display, 'none', 'Game app shell should remain hidden on menu return');
  assertEqual(game.style.display, 'none', 'Game screen should remain hidden on menu return');
  assertEqual(game.classList.contains('active'), false, 'Game screen should not become active on menu return');
  assertEqual(menu.style.display, 'flex', 'Menu should become visible after closing settings');
  assertEqual(menu.classList.contains('active'), true, 'Menu should regain active class after closing settings');
  assertEqual(settings.classList.contains('active'), false, 'Settings overlay active class should be cleared on close');
  assertEqual(App.settingsReturnScreen, null, 'Settings return target should clear after closing');
});

test('Settings overlay returns to live game from the app menu route', () => {
  const screenIds = ['screen-menu', 'screen-settings', 'screen-game', 'screen-create', 'screen-mods', 'screen-market', 'save-manager'];
  const { App, document } = loadAppForCombat(() => 0.5, {
    querySelectorAll(selector, elements) {
      if (selector !== '.screen') return [];
      return screenIds.map(id => {
        if (!elements.has(id)) elements.set(id, makeElement());
        return elements.get(id);
      });
    }
  });
  const appShell = document.getElementById('app');
  const game = document.getElementById('screen-game');
  const menu = document.getElementById('screen-menu');
  const settings = document.getElementById('screen-settings');
  const appMenu = document.getElementById('app-menu');
  const appMenuToggle = document.getElementById('app-menu-toggle');
  App.player = makeUnit('Existing Player', { CPun: 80, MPun: 100 });
  App.party = [App.player];
  App.screen = 'game';
  appShell.style.display = 'grid';
  game.style.display = 'flex';
  game.classList.add('active');
  menu.style.display = 'none';
  App.setAppMenuOpen(true);

  App.openSettingsFromGame();
  assertEqual(App.screen, 'settings', 'Game app menu Settings should open the settings overlay');
  assertEqual(App.settingsReturnScreen, 'game', 'Game app menu Settings should remember the game return target');
  assertEqual(appMenu.classList.contains('open'), false, 'Opening Settings from app menu should close the menu popover');
  assertEqual(appMenuToggle.getAttribute('aria-expanded'), 'false', 'Opening Settings should collapse the app-menu toggle state');
  assertEqual(appShell.style.display, 'none', 'Game shell should hide while settings is open');
  assertEqual(game.classList.contains('active'), false, 'Game screen should not stay active behind settings');

  App.returnToGame();
  assertEqual(App.screen, 'game', 'Closing app-menu Settings should restore live game screen state');
  assertEqual(appShell.style.display, 'grid', 'Game app shell should be visible after closing settings');
  assertEqual(game.style.display, 'flex', 'Game screen should be visible after closing settings');
  assertEqual(game.classList.contains('active'), true, 'Game screen should regain active class after closing settings');
  assertEqual(menu.style.display, 'none', 'Main menu should stay hidden after returning to a live game');
  assertEqual(settings.classList.contains('active'), false, 'Settings overlay active class should clear on game return');
  assertEqual(appMenu.classList.contains('open'), false, 'App menu should remain closed after returning to game');
  assertEqual(App.settingsReturnScreen, null, 'Game settings return target should clear after closing');
});

test('Nested system screens return through Settings and Mods origins', () => {
  const screenIds = ['screen-menu', 'screen-settings', 'screen-providers', 'screen-game', 'screen-create', 'screen-mods', 'screen-market', 'save-manager'];
  const { App, document } = loadAppForCombat(() => 0.5, {
    hostCatalog: [{ id: 'host-fixture' }],
    querySelectorAll(selector, elements) {
      if (selector !== '.screen') return [];
      return screenIds.map(id => {
        if (!elements.has(id)) elements.set(id, makeElement());
        return elements.get(id);
      });
    }
  });

  App.screen = 'menu';
  document.getElementById('screen-menu').style.display = 'flex';
  App.openSettingsFromMenu();
  App.showAIProviderScreen();
  assertEqual(App.screen, 'providers', 'Settings should open the AI Providers screen');
  assertEqual(App.overlayReturnStack.join(','), 'settings', 'AI Providers should remember Settings as its immediate origin');

  App.returnToGame();
  assertEqual(App.screen, 'settings', 'Closing AI Providers should return to Settings');
  assertEqual(App.settingsReturnScreen, 'menu', 'Returning to Settings should preserve its original menu return route');
  App.returnToGame();
  assertEqual(App.screen, 'menu', 'Closing returned Settings should restore the main menu');

  App.showModScreen();
  App.showMarketScreen();
  assertEqual(App.screen, 'market', 'Mods should open the Host Catalog when supplied');
  assertEqual(App.overlayReturnStack.join(','), 'menu,mods', 'Host Catalog should remember Mods and the underlying menu origin');
  App.returnToGame();
  assertEqual(App.screen, 'mods', 'Closing Host Catalog should return to Mods');
  assertEqual(App.overlayReturnStack.join(','), 'menu', 'Returning to Mods should retain its menu origin');
  App.returnToGame();
  assertEqual(App.screen, 'menu', 'Closing returned Mods should restore the main menu');

  App.player = makeUnit('Existing Player', { CPun: 80, MPun: 100 });
  App.party = [App.player];
  App.showScreen('game');
  App.showMarketScreen();
  App.showModScreen();
  assertEqual(App.screen, 'mods', 'My Modules should switch directly from Host Catalog to Mods');
  assertEqual(App.overlayReturnStack.join(','), 'game', 'Switching between sibling module screens should preserve the live-game origin');
  App.returnToGame();
  assertEqual(App.screen, 'game', 'Closing switched Mods should restore the live game');
});

