test('Sync action resolves only at stored round and queue index', () => {
  const { App } = loadAppForCombat(() => 0);
  const player = makeUnit('You');
  const ally = makeUnit('Ally');
  const enemy = makeUnit('Enemy', { disposition: App.DISPOSITION.ENEMY });
  App.player = player;
  App.party = [player, ally];
  App.creatures = [enemy];
	  App.combatState = {
	    active: true,
	    round: 1,
	    currentTurn: 0,
	    processing: false,
	    xpEarned: 0,
	    turnQueue: [{ unit: player, initiative: 20 }, { unit: ally, initiative: 10 }],
	    syncActions: [{ type: 'sync_fight', participants: [player, ally], target: enemy, resolveAtIndex: 1, resolved: false, round: 1 }]
	  };
	  App.processTurn();
	  assertEqual(App.combatState.syncActions[0]?.resolved, false, 'Sync resolved before slowest participant index');
	  assertEqual(enemy.CPun, 100, 'Sync should not affect the target before the stored queue index');
	  App.combatState.currentTurn = 1;
	  App.processTurn();
	  assert(enemy.CPun < 100 || enemy.disposition === App.DISPOSITION.CORPSE, 'Sync did not resolve at slowest participant index');
});

test('Sync failure and submissive recruit prompts localize', () => {
  const syncCase = loadAppForCombat(() => 0);
  const player = makeUnit('You');
  const ally = makeUnit('Ally');
  const enemy = makeUnit('Enemy', { disposition: syncCase.App.DISPOSITION.ENEMY });
  syncCase.App.player = player;
  syncCase.App.party = [player, ally];
  syncCase.App.creatures = [enemy];
  syncCase.App.combatState = { active: true, round: 1, currentTurn: 0, processing: false, xpEarned: 0, turnQueue: [], syncActions: [] };
  syncCase.App._syncParticipants = [player, ally];
  syncCase.App.nextTurn = function() { this._syncFailedAdvanced = true; };
  syncCase.App.updateLanguage('es');
  assertEqual(syncCase.App.queueSyncAction('sync_fight', 0), false, 'Missing participant queue should reject before queueing');
  assertEqual(syncCase.App.combatState.syncActions.length, 0, 'Missing participant queue should not create a queued sync action');
  assertEqual(syncCase.App._syncFailedAdvanced, undefined, 'Missing participant queue should preserve the active turn for correction');
  assertContains(syncCase.App.log[syncCase.App.log.length - 1].text, 'Sincronizacion fallida! Los participantes ya no estan en la cola de turnos.', 'Missing queue sync failure should localize');

  const downed = loadAppForCombat(() => 0);
  const downedPlayer = makeUnit('You');
  const downedAlly = makeUnit('Downed Ally', { CPun: 0 });
  const downedEnemy = makeUnit('Enemy', { disposition: downed.App.DISPOSITION.ENEMY });
  downed.App.player = downedPlayer;
  downed.App.party = [downedPlayer, downedAlly];
  downed.App.creatures = [downedEnemy];
  downed.App.combatState = { active: true, round: 1, currentTurn: 0, processing: false, xpEarned: 0, turnQueue: [], syncActions: [] };
  downed.App.nextTurn = function() { this._incapacitatedFailedAdvanced = true; };
  downed.App.updateLanguage('es');
  downed.App._resolveSyncAction({ type: 'sync_fight', participants: [downedPlayer, downedAlly], target: downedEnemy, resolved: false, round: 1 });
  assertEqual(downed.App._incapacitatedFailedAdvanced, true, 'Incapacitated sync failure should still advance turn');
  assertContains(downed.App.log[downed.App.log.length - 1].text, 'Sincronizacion fallida! Downed Ally no puede participar.', 'Incapacitated sync failure should localize');

  const recruitCase = loadAppForCombat(() => 0, { confirm: false });
  const seducer = makeUnit('You', { Fuck: 80, Flir: 80 });
  const target = makeUnit('Mouse', { disposition: recruitCase.App.DISPOSITION.ENEMY, CPle: 79, MPle: 100, wis: 1 });
  recruitCase.App.player = seducer;
  recruitCase.App.party = [seducer];
  recruitCase.App.creatures = [target];
  recruitCase.App.combatState.active = true;
  recruitCase.App.nextTurn = function() {};
  recruitCase.App.updateLanguage('es');
  recruitCase.App.executeActionAgainstTarget('fuck', seducer, target);
  assertEqual(recruitCase.confirmations.length, 0, 'Submissive recruitment should not call the browser-native confirm dialog');
  assert(recruitCase.App.pendingConfirm, 'Submissive recruitment should open an in-app confirmation dialog');
  assertEqual(recruitCase.App.pendingConfirm.message, 'Mouse esta listo para seguirte. Reclutarlo para tu grupo?', 'Recruitment confirmation should localize');
  assertContains(recruitCase.body.innerHTML, 'role="dialog"', 'Submissive recruitment confirmation should render an in-app modal dialog');
  recruitCase.App.resolveConfirmDialog(false);
  assertEqual(recruitCase.App.pendingConfirm, null, 'Cancelling submissive recruitment should clear pending confirmation state');
  assertEqual(recruitCase.App.party.length, 1, 'Cancelled submissive recruitment should not add target to party');

  const approveRecruitCase = loadAppForCombat(() => 0, { confirm: true });
  const approveSeducer = makeUnit('You', { Fuck: 80, Flir: 80 });
  const approveTarget = makeUnit('Mouse', { disposition: approveRecruitCase.App.DISPOSITION.ENEMY, CPle: 79, MPle: 100, wis: 1 });
  approveRecruitCase.App.player = approveSeducer;
  approveRecruitCase.App.party = [approveSeducer];
  approveRecruitCase.App.creatures = [approveTarget];
  approveRecruitCase.App.combatState.active = true;
  approveRecruitCase.App.nextTurn = function() {};
  approveRecruitCase.App.executeActionAgainstTarget('fuck', approveSeducer, approveTarget);
  assertEqual(approveRecruitCase.confirmations.length, 0, 'Approved submissive recruitment should not call the browser-native confirm dialog');
  assert(approveRecruitCase.App.pendingConfirm, 'Approved submissive recruitment should open an in-app confirmation dialog');
  approveRecruitCase.App.resolveConfirmDialog(true);
  assertEqual(approveRecruitCase.App.pendingConfirm, null, 'Approved submissive recruitment should clear pending confirmation state');
  assert(approveRecruitCase.App.party.some(unit => unit.name === 'Mouse'), 'Approved submissive recruitment should add target to party');

	  const syncRecruitCase = loadAppForCombat(() => 0, { confirm: false });
	  const syncSeducer = makeUnit('You', { Fuck: 100, Flir: 100 });
	  const syncHelper = makeUnit('Ally', { Fuck: 100, Flir: 100 });
	  const syncTarget = makeUnit('Mouse', { disposition: syncRecruitCase.App.DISPOSITION.ENEMY, CPle: 0, MPle: 100, wis: 1 });
	  syncRecruitCase.App.player = syncSeducer;
	  syncRecruitCase.App.party = [syncSeducer, syncHelper];
	  syncRecruitCase.App.creatures = [syncTarget];
	  syncRecruitCase.App.combatState = { active: true, round: 1, currentTurn: 0, processing: false, xpEarned: 0, turnQueue: [], syncActions: [] };
	  syncRecruitCase.App.nextTurn = function() {};
	  syncRecruitCase.App.updateLanguage('es');
	  syncRecruitCase.App._resolveSyncAction({ type: 'sync_fuck', participants: [syncSeducer, syncHelper], target: syncTarget, resolved: false, round: 1 });
  assertEqual(syncRecruitCase.confirmations.length, 0, 'Sync submissive recruitment should not call the browser-native confirm dialog');
  assert(syncRecruitCase.App.pendingConfirm, 'Sync submissive recruitment should open an in-app confirmation dialog');
  assertEqual(syncRecruitCase.App.pendingConfirm.message, 'Mouse esta listo para seguirte. Reclutarlo para tu grupo?', 'Sync recruitment confirmation should localize');
});

test('Sync action menus localize visible and accessible labels', () => {
  const { App, elements } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'sync-player' });
  const ally = makeUnit('Ally', { id: 'sync-ally' });
  const enemy = makeUnit('Enemy', { id: 'sync-enemy', disposition: App.DISPOSITION.ENEMY });
  App.player = player;
  App.party = [player, ally];
  App.creatures = [enemy];
  App.combatState = { active: true, round: 1, currentTurn: 0, processing: false, turnQueue: [{ unit: player, initiative: 20 }, { unit: ally, initiative: 10 }, { unit: enemy, initiative: 5 }], syncActions: [] };
  App.activeActor = player;
  App.updateLanguage('es');
  App.showSyncMenu();
  let html = elements.get('desktop-context-belt').innerHTML;
  assertContains(html, 'Elegir accion sincronizada', 'Sync action heading should localize');
  assertContains(html, 'class="panel-interaction-tray combat-sync-tray" data-command-surface="sync-intents" data-command-mode="combat" data-command-grammar="actor-target-intent"', 'Sync choose tray root should identify sync intent composer ownership');
  assertContains(html, 'data-command-surface="sync-intents"', 'Sync action composer should identify the sync intent surface');
  assertContains(html, 'data-command-surface="sync-intents" data-command-mode="combat"', 'Sync action composer should identify combat command mode');
  assertContains(html, 'data-command-surface="sync-intents" data-command-mode="combat" data-command-grammar="actor-target-intent"', 'Sync action composer should identify the shared command grammar');
  assertContains(html, 'data-command-intent="sync_fight"', 'Sync fight should expose its stable group intent id');
  assertContains(html, 'data-command-mode="combat" data-command-intent="sync_fight"', 'Sync fight should expose combat command mode');
  assertContains(html, 'data-command-mode="combat" data-command-intent="sync_fight" data-command-grammar="actor-target-intent"', 'Sync fight should identify the shared command grammar on the intent itself');
  assertContains(html, 'data-command-intent="sync_fight" data-command-grammar="actor-target-intent" data-command-slot="intent"', 'Sync fight should identify itself as an intent-slot control');
  assertNotContains(html, 'selected-target-summary', 'Sync action tray should leave actor intent summary to the composer sentence');
  assertContains(html, 'aria-label="Ataque grupal"', 'Sync fight action should expose localized accessible label');
  assertContains(html, 'data-command-surface="sync-intents" data-command-mode="combat" data-command-grammar="actor-target-intent" data-command-control="cancel-sync"', 'Sync action composer should tag cancel as a combat-mode exit');
  assertContains(html, 'data-command-control="cancel-sync" data-command-slot="exit"', 'Sync action composer should tag cancel as an exit-slot control');
  assertContains(html, 'data-command-control="cancel-sync"', 'Sync action composer should expose a structural cancel control');
  assertContains(html, 'Cancel Sync', 'Sync tray should expose a mode-specific cancel exit');
  assertNotContains(elements.get('party-content').innerHTML, 'Elegir accion sincronizada', 'Party panel should not duplicate composer-owned sync action controls');
  assertNotContains(elements.get('scene-description')?.innerHTML || '', 'Elegir accion sincronizada', 'Sync action menu should not render in center scene');

  App.selectSyncParticipants('sync_fight');
  html = elements.get('desktop-context-belt').innerHTML;
  assertContains(html, 'Seleccionar participantes para sincronizar', 'Sync participant control should localize');
  assertContains(html, 'class="panel-interaction-tray combat-sync-tray" data-command-surface="sync-participants" data-command-mode="combat" data-command-grammar="actor-target-intent"', 'Sync participant tray root should identify participant composer ownership');
  assertContains(html, 'data-command-surface="sync-participants"', 'Sync participant composer should identify its participant surface');
  assertContains(html, 'data-command-surface="sync-participants" data-command-mode="combat"', 'Sync participant composer should identify combat command mode');
  assertContains(html, 'data-command-surface="sync-participants" data-command-mode="combat" data-command-grammar="actor-target-intent"', 'Sync participant composer should identify the shared command grammar');
  assertContains(html, 'data-command-control="confirm-sync-participants"', 'Sync participant composer should expose confirm as a structural control');
  assertContains(html, 'data-command-control="confirm-sync-participants" data-command-slot="actor"', 'Sync participant confirm should identify the actor slot');
  assertContains(html, 'data-command-surface="sync-participants" data-command-mode="combat" data-command-grammar="actor-target-intent" data-command-control="cancel-sync"', 'Sync participant composer should tag cancel as a combat-mode exit');
  assertContains(html, 'data-command-control="cancel-sync" data-command-slot="exit"', 'Sync participant composer should tag cancel as an exit-slot control');
  assertContains(html, 'Confirmar participantes', 'Sync participant composer should expose confirm');
  assertContains(html, 'Cancel Sync', 'Sync participant composer should keep a mode-specific cancel exit');
  assertNotContains(html, 'selected-target-summary', 'Sync participant tray should leave actor intent summary to the composer sentence');
  assertContains(elements.get('party-content').innerHTML, 'aria-label="Seleccionar Ally para sincronizar"', 'Sync participant card should expose localized accessible label');
  assertContains(elements.get('party-content').innerHTML, 'data-command-mode="combat" data-command-grammar="actor-target-intent" data-command-control="toggle-sync-participant"', 'Sync participant card button should identify the shared group actor grammar');
  assertContains(elements.get('party-content').innerHTML, 'data-command-slot="actor" data-command-intent="sync_fight"', 'Sync participant card button should identify actor-slot selection for the stable group intent');
  assertContains(elements.get('party-content').innerHTML, 'data-selection-control="sync-participant" data-selection-mode="sync-participant"', 'Sync participant card button should expose participant selection semantics');

  App._syncSelected = [0, 1];
  App.syncSelection.participantIds = ['sync-player', 'sync-ally'];
  App.confirmSyncParticipants('sync_fight');
  html = elements.get('desktop-context-belt').innerHTML;
  assertContains(html, 'Seleccionar objetivo sincronizado', 'Sync target heading should localize');
  assertContains(html, 'class="panel-interaction-tray combat-sync-tray" data-command-surface="sync-targeting" data-command-mode="combat" data-command-grammar="actor-target-intent"', 'Sync target tray root should identify target-pick composer ownership');
  assertContains(html, 'data-command-surface="sync-targeting"', 'Sync target composer should identify its target-pick surface');
  assertContains(html, 'data-command-surface="sync-targeting" data-command-mode="combat"', 'Sync target composer should identify combat command mode');
  assertContains(html, 'data-command-surface="sync-targeting" data-command-mode="combat" data-command-grammar="actor-target-intent"', 'Sync target composer should identify the shared command grammar');
  assertContains(html, 'data-command-surface="sync-targeting" data-command-mode="combat" data-command-grammar="actor-target-intent" data-command-control="cancel-sync"', 'Sync target composer should tag cancel as a combat-mode exit');
  assertContains(html, 'data-command-control="cancel-sync" data-command-slot="exit"', 'Sync target composer should tag cancel as an exit-slot control');
  assertContains(html, 'Cancel Sync', 'Sync target composer should keep a mode-specific cancel exit');
  assertNotContains(html, 'selected-target-summary', 'Sync target tray should leave actor intent summary to the composer sentence');
  html = elements.get('enemies-content').innerHTML;
  assertContains(html, 'aria-label="Seleccionar Enemy como objetivo de Sincronizar"', 'Sync target card should expose localized accessible label');
  assertNotContains(elements.get('scene-description')?.innerHTML || '', 'Seleccionar objetivo sincronizado', 'Sync target menu should not render in center scene');
});

test('Softcore player death removes player from acting while allies continue', () => {
  const { App } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { CPun: 5, MPun: 100 });
  const ally = makeUnit('Ally', { CPun: 100 });
  const enemy = makeUnit('Enemy', { disposition: App.DISPOSITION.ENEMY, Figh: 50 });
  App.player = player;
  App.party = [player, ally];
  App.creatures = [enemy];
  App.combatState.active = true;
  App.nextTurn = function() { this._nextTurnCalled = true; };
  App.updateLanguage('es');
  App.enemyTurn(enemy);
  assertEqual(player.CPun, 0, 'Softcore death should clamp player HP to 0 during combat');
  assert(player.knockedOut, 'Softcore death should remove the player from the turn queue');
  assertEqual(App.defeatState.status, 'dead', 'Softcore combat death should create a terminal pending recovery state');
  assertEqual(App.defeatState.awaitingEncounterSettlement, true, 'Recovery should wait while living allies remain in battle');
  assert(App.combatState.active, 'Combat should continue when allies remain');
  assert(App._nextTurnCalled, 'Combat should advance after player death');
  assertContains(App.log.map(entry => entry.text).join('\n'), 'You have died. Your companions must finish the battle.', 'Player death feedback should remain explicit when the compact test locale omits the new key');
  assertContains(App.log.map(entry => entry.text).join('\n'), 'Tus aliados continuan la pelea...', 'Ally continue feedback should localize');
});

