test('Digestion container configs preserve per-container drain behavior', () => {
  const { App } = loadAppForCombat();
  const predator = makeUnit('Predator', {
    hunger: 50,
    stomach: [makeUnit('Stomach Prey', { CPun: 100, MPun: 100, alive: true, inStomach: true, statDrain: null })],
    womb: [makeUnit('Womb Prey', { CPun: 100, MPun: 100, alive: true, inWomb: true, statDrain: null })],
    balls: [makeUnit('Balls Prey', { CPun: 100, MPun: 100, alive: true, inCock: true, statDrain: null })]
  });
  App.party = [predator];
  App.creatures = [];
  App.settings.statAbsorption = false;
  App.settings.slowDigestion = false;

  App._processDigestion();

  const stomachPrey = predator.stomach[0];
  const wombPrey = predator.womb[0];
  const ballsPrey = predator.balls[0];
  assertEqual(stomachPrey.digestionState, 'digesting', 'Stomach prey should advance from contained to digesting');
  assertEqual(stomachPrey.digestionProgress, 5, 'Stomach prey should use the preserved fast stomach rate');
  assertEqual(stomachPrey.statDrain.str, 1, 'Stomach drain should affect strength');
  assertEqual(stomachPrey.statDrain.con, 1, 'Stomach drain should affect constitution');
  assertEqual(stomachPrey.statDrain.Figh, 1, 'Stomach drain should affect fight');
  assertEqual(stomachPrey.str, 10, 'Digestion tick should not directly mutate visible strength');
  assertEqual(stomachPrey.con, 10, 'Digestion tick should not directly mutate visible constitution');
  assertEqual(stomachPrey.Figh, 10, 'Digestion tick should not directly mutate visible fight stat');
  assert(stomachPrey.vitalRemaining < stomachPrey.vitalMax, 'Stomach digestion should reduce vital integrity');
  assertEqual(wombPrey.digestionProgress, 3, 'Womb prey should use the preserved fast womb rate');
  assertEqual(wombPrey.statDrain.cha, 1, 'Womb drain should track charisma without NaN');
  assertEqual(wombPrey.statDrain.Flir, 1, 'Womb drain should affect flirt');
  assertEqual(wombPrey.statDrain.Fuck, 1, 'Womb drain should affect fuck');
  assertEqual(wombPrey.cha, 10, 'Womb tick should not directly mutate visible charisma');
  assertEqual(wombPrey.Flir, 10, 'Womb tick should not directly mutate visible flirt stat');
  assertEqual(wombPrey.Fuck, 10, 'Womb tick should not directly mutate visible play stat');
  assertEqual(Number.isNaN(wombPrey.statDrain.cha), false, 'Womb charisma drain should remain numeric');
  assertEqual(ballsPrey.digestionProgress, 3, 'Balls prey should use the preserved fast balls rate');
  assertEqual(ballsPrey.statDrain.Feas, 1, 'Balls drain should affect feast');
  assertEqual(ballsPrey.statDrain.Fuck, 1, 'Balls drain should affect fuck');
  assertEqual(ballsPrey.Feas, 10, 'Reserve tick should not directly mutate visible feast stat');
  assertEqual(ballsPrey.Fuck, 10, 'Reserve tick should not directly mutate visible play stat');
});

test('Fast and slow digestion deliver the same size-scaled total nutrition', () => {
  const run = slowDigestion => {
    const { App } = loadAppForCombat();
    const prey = makeUnit('Sized Prey', { id: `nutrition-${slowDigestion}`, CPun: 1000, MPun: 1000, size: 4, alive: true, inStomach: true });
    const predator = makeUnit('Predator', { id: `predator-${slowDigestion}`, hunger: 90, stomach: [prey] });
    App.player = predator;
    App.party = [predator];
    App.creatures = [];
    App.settings.slowDigestion = slowDigestion;
    App._processDigestion({ ticks: slowDigestion ? 50 : 20 });
    return { hunger: predator.hunger, progress: prey.digestionProgress, applied: prey.nutritionReliefApplied };
  };
  const fast = run(false);
  const slow = run(true);
  assertEqual(fast.progress, 100, 'Fast digestion should complete after twenty five-point ticks');
  assertEqual(slow.progress, 100, 'Slow digestion should complete after fifty two-point ticks');
  assertEqual(fast.applied, 60, 'Size-four prey should provide sixty digestion nutrition points');
  assertEqual(slow.applied, fast.applied, 'Slow digestion should spread nutrition over time without reducing its total');
  assertEqual(slow.hunger, fast.hunger, 'Fast and slow completion should produce the same final hunger relief');
});

