  const enemy = makeUnit('Charmed Enemy', {
    id: 'charm-no-target-enemy',
    disposition: App.DISPOSITION.ENEMY,
    status: { charm: { turns: 2, by: 'You' } }
  });
  App.player = player;
  App.party = [player];
  App.creatures = [enemy];
  App.combatState = {
    active: true,
    round: 1,
    currentTurn: 0,
    processing: false,
    turnQueue: [{ unit: enemy, initiative: 20 }, { unit: player, initiative: 10 }],
    syncActions: []
  };
  let advances = 0;
  App.nextTurn = () => { advances++; };
