test('Core gameplay loop can move fight loot save and reload state', () => {
  const Binary = loadBinaryForTest();
  const { App } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'player-e2e', Figh: 80, spd: 100, xp: 0, xpToNext: 1000, gold: 0 });
  const enemy = makeUnit('Hostile Guide', {
    id: 'hostile-guide-e2e',
    disposition: App.DISPOSITION.ENEMY,
    CPun: 1,
    MPun: 20,
    con: 1,
    spd: 1,
    goldLoot: 3
  });
  App.worldMeta = { worldId: 'e2e-world', seed: 'e2e-seed', generatorVersion: 2, mapModsHash: 'core' };
  App.player = player;
  App.party = [player];
  App.creatures = [];
  App.inventory = [];
  App.log = [];
  App.location = { x: 0, y: 0 };
  App.currentBiome = 'grove';
  App.timeHour = 8;
  App.dayCount = 0;
  App.quests = [];
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  App.exploredTiles = new Set(['0,0', '1,0']);
  App.worldMap.set('0,0', { ...App.getBaseTile(0, 0), explored: true, biome: 'grove', description: 'Origin', creatures: [], items: [] });
  App.worldMap.set('1,0', { ...App.getBaseTile(1, 0), explored: true, biome: 'grove', description: 'Encounter tile', creatures: [enemy], items: [] });

  App.move(1, 0);
  assertEqual(App.combatState.active, true, 'Moving into an explored hostile tile should start combat');
  assertEqual(App.location.x, 1, 'Movement should update x coordinate');
  assertEqual(App.location.y, 0, 'Movement should update y coordinate');
  assertEqual(App.creatures[0].id, 'hostile-guide-e2e', 'Encounter creature should be restored from the destination tile');

  App.executeAction('fight', 0);
  assertEqual(App.combatState.active, false, 'One-hit victory should end combat');
  assertEqual(App.creatures[0].disposition, App.DISPOSITION.CORPSE, 'Defeated creature should become a corpse');
  assertEqual(App.lootCorpse('hostile-guide-e2e'), true, 'Corpse should be lootable after combat');
  assertEqual(App.player.gold, 3, 'Authored corpse gold should be awarded during loot');

  const saved = Binary.saveGame(App);
  const loaded = Binary.loadGame(saved);
  assertEqual(loaded.locationX, 1, 'Saved state should preserve current x coordinate');
  assertEqual(loaded.locationY, 0, 'Saved state should preserve current y coordinate');
  assertEqual(loaded.questState.playerGold, 3, 'Saved state should preserve looted gold');
  assertEqual(loaded.worldMap['1,0'].creatures[0].disposition, App.DISPOSITION.CORPSE, 'Saved world tile should preserve corpse disposition');
  assertEqual(loaded.worldMap['1,0'].creatures[0].looted, true, 'Saved world tile should preserve corpse loot state');
});

test('SFW-created characters omit optional fields while legacy save values remain compatible', () => {
  const Binary = loadBinaryForTest();
  const created = loadAppForCombat(() => 0.5, { binary: Binary });
  created.document.getElementById('char-name').value = 'Safe Tester';
  created.App.setContentTier('safe');
  created.App.selectSpecies('human');
  created.App.selectGender('female');
  created.App.autoSave = () => {};
  created.App.createCharacter();

  assertEqual(created.App.screen, 'game', 'Safe character creation should enter the game screen');
  assertEqual(created.App.player.parts, null, 'SFW-created player should not receive a hidden optional primary field');
  assertEqual(created.App.player.chest, null, 'SFW-created player should not receive a hidden optional chest field');
  assertEqual(created.App.player.adultEligibility.status, 'eligible', 'Core character creation should assign authoritative adult eligibility');
  created.App.player.parts = 'clit';
  created.App.player.chest = 'tits';
  const loaded = Binary.loadGame(Binary.saveGame(created.App));
  assertEqual(loaded.party[0].name, 'Safe Tester', 'Loaded save should preserve name');
  assertEqual(loaded.questState.playerCompatibility.parts, 'clit', 'Loaded legacy save should preserve its compatibility primary field');
  assertEqual(loaded.questState.playerCompatibility.chest, 'tits', 'Loaded legacy save should preserve its compatibility chest field');
  assertEqual(loaded.questState.playerCompatibility.lifeStage, 'adult', 'Binary compatibility data should preserve life stage without changing the unit codec');
  assertEqual(loaded.questState.playerCompatibility.adultEligibility.status, 'eligible', 'Binary compatibility data should preserve structured adult eligibility');
  assertEqual(loaded.questState.playerCompatibility.adultEligibility.authority, 'species-canon', 'Binary compatibility data should preserve eligibility authority');

  created.App.showCharacterStats();
  const safeStatsHtml = holdingsHtml(created.elements);
  assertNotContains(safeStatsHtml, 'Body Type:', 'Loaded safe-tier stats should not reveal compatibility body type');
  assertNotContains(safeStatsHtml, 'Chest Type:', 'Loaded safe-tier stats should not reveal compatibility chest type');
  created.App.setContentTier('mature');
  created.content.setCategoryEnabled('explicit.sexual', true);
  created.App.showCharacterStats();
  assertContains(holdingsHtml(created.elements), 'Lower Anatomy:', 'Explicit provider category should reveal preserved optional body detail fields');
});

