test('Hardcore finalization deletes only the active full and sparse slot data', async () => {
  const { App, window } = loadAppForCombat(() => 0.5);
  App.player = makeUnit('You', { id: 'player-hardcore', CPun: 0, MPun: 100 });
  App.party = [App.player];
  App.activeSlot = 'slot3';
  App.safeAnchor = { x: 0, y: 0, label: 'The Beginning' };
  App._setStoredValue('lastSlot', 'slot3');
  const deletes = [];
  App._dbDelete = async (store, key) => { deletes.push(`${store}:${key}`); };
  App.refreshContinueButton = async () => true;
  App._pruneUnreferencedWorldStore = async () => true;
  const state = App._resolvePlayerState({ status: 'dead', terminal: true, cause: 'combat-damage', source: 'test' });

  await window.YAW_DEFEAT_RECOVERY.finalizeHardcore(App, state);

  assert(deletes.includes('saves:slot3'), 'Hardcore should delete the active full save');
  assert(deletes.includes('saveManifests:slot3'), 'Hardcore should delete the active sparse manifest');
  assert(deletes.some(entry => entry === 'saveRecords:slot3:player'), 'Hardcore should delete active sparse records');
  assertEqual(deletes.some(entry => entry.includes('slot1')), false, 'Hardcore should leave unrelated slot1 data intact');
  assertEqual(deletes.some(entry => entry.includes('slot2')), false, 'Hardcore should leave unrelated slot2 data intact');
  assertEqual(App._getStoredValue('lastSlot'), null, 'Hardcore should clear resume metadata for the ended active slot');
  assertEqual(App._autoSaveSuppressed, true, 'Hardcore should suppress autosave after the run ends');
  assertEqual(App.defeatState.status, 'run-ended', 'Hardcore should finish in an explicit run-ended state');
});

test('Safe place action is available only on safe overworld rest-capable structures', () => {
  const { App, window } = loadAppForCombat(() => 0.5);
  App.player = makeUnit('You');
  App.party = [App.player];
  App.location = { x: 3, y: 4 };
  App.combatState = { active: false, turnQueue: [], currentTurn: 0, round: 1, syncActions: [], processing: false, xpEarned: 0 };
  App.creatures = [];
  App.worldMap = new Map([['3,4', { ...App.getBaseTile(3, 4), x: 3, y: 4, explored: true, biome: 'grove', creatures: [], structure: null }]]);
  assertEqual(App._canSetSafeAnchor(), false, 'Ordinary overworld tiles should not allow marking home by default');
  assert(!window.YAW_CENTER_CONTEXT.actionKeys(App).includes('setSafePlace'), 'Safe place action should stay hidden on ordinary tiles');

  App.worldMap.get('3,4').structure = 'tree';
  assertEqual(App._canSetSafeAnchor(), false, 'Scenic non-rest structures should not allow marking home');

  App.worldMap.get('3,4').structure = 'camp';
  App.worldMap.get('3,4').overlays = {};
  assertEqual(App._canSetSafeAnchor(), false, 'Ordinary camps should not allow marking home unless generated as rest sites');

  App.worldMap.get('3,4').overlays = { poi: { category: 'restSite' } };
  assertEqual(App._canSetSafeAnchor(), true, 'Rest-site camps should allow marking home');
  assert(window.YAW_CENTER_CONTEXT.actionKeys(App).includes('setSafePlace'), 'Safe place action should be exposed on safe rest sites');

  App.worldMap.get('3,4').overlays = {};
  App.worldMap.get('3,4').structure = 'cabin';
  assertEqual(App._canSetSafeAnchor(), true, 'Rest-capable structures should allow marking home');

  App.creatures = [makeUnit('Hostile', { disposition: App.DISPOSITION.ENEMY })];
  assertEqual(App._canSetSafeAnchor(), false, 'Living hostile should block home marking');

  App.creatures = [];
  App.inInterior = true;
  assertEqual(App._canSetSafeAnchor(), false, 'Interior rooms should not be safe anchors until interior persistence is explicit');

  App.inInterior = false;
  App.combatState.active = true;
  assertEqual(App._canSetSafeAnchor(), false, 'Combat should block home marking');
});

