test('Panel wrappers use one command dispatcher for adventure interactions', () => {
  const { App } = loadAppForCombat(() => 0);
  const actor = makeUnit('Actor', { id: 'actor-panel-dispatch', Flir: 30, cha: 20 });
  const partyTarget = makeUnit('Party Target', { id: 'party-panel-dispatch' });
  const creatureTarget = makeUnit('Creature Target', { id: 'creature-panel-dispatch', disposition: App.DISPOSITION.FRIENDLY });
  App.player = actor;
  App.party = [actor, partyTarget];
  App.creatures = [creatureTarget];
  App.explorationActorIds = ['actor-panel-dispatch'];
  const seen = [];
  const originalDispatch = App._dispatchInteractionCommand.bind(App);
  App._dispatchInteractionCommand = command => {
    seen.push({
      mode: command.mode,
      action: command.action,
      source: command.source,
      actorIds: command.actorIds,
      targetIds: command.targetIds,
      targetType: command.targetType
    });
    return originalDispatch(command);
  };
  assertEqual(App.outsideActionForParty('flirt', 1), true, 'Party wrapper should resolve through shared panel dispatch');
  assertEqual(App.outsideActionForCreature('flirt', 'creature-panel-dispatch'), true, 'Creature wrapper should resolve through shared panel dispatch');
  assertEqual(App.outsideAction('flirt', 'party', 0), true, 'Filtered-index party compatibility wrapper should still resolve');
  assertEqual(App.outsideAction('flirt', 'creature', 0), true, 'Filtered-index creature compatibility wrapper should still resolve');
  App.toggleExplorationTarget('party', 'party-panel-dispatch');
  assertEqual(App.resolveExplorationTargetAction('feed', 'heal', 'composer-tray'), true, 'Marked-target tray should resolve through shared panel dispatch');
  assertEqual(seen.length, 5, 'Each panel interaction route should hit the same dispatcher once');
  assertEqual(seen[0].source, 'command-composer', 'Party wrapper should route through command composer provenance');
  assertEqual(seen[0].targetType, 'party', 'Party wrapper should preserve target type');
  assertEqual(seen[1].source, 'command-composer', 'Creature wrapper should route through command composer provenance');
  assertEqual(seen[1].targetIds[0], 'creature-panel-dispatch', 'Creature wrapper should resolve target id through command metadata');
  assertEqual(seen[2].source, 'command-composer', 'Filtered-index party compatibility wrapper should delegate to the command composer');
  assertEqual(seen[3].source, 'command-composer', 'Filtered-index creature compatibility wrapper should delegate to the command composer');
  assertNotContains(seen.map(entry => entry.source).join(','), 'wrapper', 'Filtered-index compatibility wrappers should not emit legacy wrapper command sources');
  assertEqual(seen[4].source, 'composer-tray', 'Marked target tray should keep source metadata');
  assertEqual(seen[4].targetType, 'marked', 'Marked target tray should preserve marked target type');
});

test('Panel wrappers use one command dispatcher for combat target clicks', () => {
  const { App } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'player-combat-panel-dispatch', Figh: 60 });
  const enemy = makeUnit('Enemy', { id: 'enemy-combat-panel-dispatch', disposition: App.DISPOSITION.ENEMY, CPun: 80, con: 1 });
  App.player = player;
  App.party = [player];
  App.creatures = [enemy];
  App.combatState = {
    active: true,
    round: 1,
    currentTurn: 0,
    processing: false,
    xpEarned: 0,
    turnQueue: [{ unit: player, initiative: 20 }, { unit: enemy, initiative: 10 }],
    syncActions: []
  };
  App.activeActor = player;
  App.nextTurn = function() {};
  const seen = [];
  const originalDispatch = App._dispatchInteractionCommand.bind(App);
  App._dispatchInteractionCommand = command => {
    seen.push({
      mode: command.mode,
      action: command.action,
      source: command.source,
      actorIds: command.actorIds,
      targetIds: command.targetIds
    });
    return originalDispatch(command);
  };
  App.selectTarget('fight');
  assertEqual(App.executeActionOnTarget('fight', 'enemy-combat-panel-dispatch'), true, 'Combat target card should mark the target during target-pick');
  assertEqual(seen.length, 0, 'Combat target click should not dispatch until the marked target is confirmed');
  assertEqual(App.combatTargetIds.join(','), 'enemy-combat-panel-dispatch', 'Combat target click should preserve the marked target id');
  assertEqual(App.confirmCombatTargets(), true, 'Combat target confirmation should resolve through shared panel dispatch');
  assertEqual(seen.length, 1, 'Combat target confirmation should hit the same dispatcher once');
  assertEqual(seen[0].mode, 'combat', 'Combat target click should build a combat command');
  assertEqual(seen[0].source, 'action-variant-options', 'Combat target confirmation should identify the shared Fight variant command surface');
  assertEqual(seen[0].actorIds[0], 'player-combat-panel-dispatch', 'Combat command should record active actor id');
  assertEqual(seen[0].targetIds[0], 'enemy-combat-panel-dispatch', 'Combat command should record clicked target id');

  enemy.CPun = 80;
  App.combatState.processing = false;
  App.combatState.currentTurn = 0;
  App.targetSelection = null;
  assertEqual(App.executeAction('fight', 0), true, 'Legacy filtered-index combat wrapper should still resolve');
  assertEqual(seen.length, 2, 'Legacy combat wrapper should delegate through the same dispatcher once');
  assertEqual(seen[1].source, 'combat-targeting', 'Legacy combat wrapper should delegate through the combat target-picker command surface');
  assertEqual(seen[1].targetIds[0], 'enemy-combat-panel-dispatch', 'Legacy combat wrapper should resolve the same target id before dispatch');
});

test('InteractionPlan infers exploration shapes and distributions', () => {
  const { App } = loadAppForCombat(() => 0);
  const actorA = makeUnit('Actor A', { id: 'plan-actor-a' });
  const actorB = makeUnit('Actor B', { id: 'plan-actor-b' });
  const targetA = makeUnit('Target A', { id: 'plan-target-a', disposition: App.DISPOSITION.FRIENDLY });
  const targetB = makeUnit('Target B', { id: 'plan-target-b', disposition: App.DISPOSITION.FRIENDLY });
  App.player = actorA;
  App.party = [actorA, actorB, targetA];
  App.creatures = [targetB];

  let plan = App._buildPanelInteractionCommand({ mode: 'adventure', actors: [actorA], targets: [targetB], action: 'inspect', source: 'test-plan' });
  assertEqual(plan.mode, 'adventure', 'Compatibility command mode should stay adventure for existing exploration routes');
  assertEqual(plan.plan.mode, 'exploration', 'InteractionPlan mode should normalize adventure to exploration');
  assertEqual(plan.shape, 'one-to-one', 'One actor and one target should infer one-to-one shape');
  assertEqual(plan.distribution, 'single', 'One-to-one exploration should infer single distribution');
  assertEqual(plan.timing, 'immediate', 'Exploration plans should default to immediate timing');

  plan = App._buildPanelInteractionCommand({ mode: 'adventure', actors: [actorA, actorB], targets: [targetB], action: 'flirt' });
  assertEqual(plan.shape, 'many-to-one', 'Many actors and one target should infer many-to-one shape');

  plan = App._buildPanelInteractionCommand({ mode: 'adventure', actors: [actorA], targets: [targetA, targetB], action: 'inspect' });
  assertEqual(plan.shape, 'one-to-many', 'One actor and many targets should infer one-to-many shape');
  assertEqual(plan.distribution, 'all', 'One-to-many should infer all-target distribution');

  plan = App._buildPanelInteractionCommand({ mode: 'adventure', actors: [actorA, actorB], targets: [targetA, targetB], action: 'inspect' });
  assertEqual(plan.shape, 'many-to-many', 'Equal non-overlapping actor and target groups should infer collective many-to-many shape');
  assertEqual(plan.distribution, 'all', 'Many-to-many exploration should send every actor across every target');

  plan = App._buildPanelInteractionCommand({ mode: 'adventure', actors: [actorA, actorB], targets: [targetA, targetB], action: 'inspect', distribution: 'paired' });
  assertEqual(plan.distribution, 'paired', 'Explicit paired distribution should remain representable without being inferred from counts');

  plan = App._buildPanelInteractionCommand({ mode: 'adventure', actors: [actorA, actorB], targets: [actorA, actorB], action: 'feed' });
  assertEqual(plan.shape, 'mutual', 'Identical actor and target sets should infer mutual shape');
  assertEqual(plan.distribution, 'mutual', 'Mutual shape should infer mutual distribution');
});

test('InteractionPlan backs combat current-turn target plans and validation', () => {
  const { App } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'plan-combat-player', Figh: 20, combatRow: 'front' });
  const ally = makeUnit('Ally', { id: 'plan-combat-ally', Figh: 20, combatRow: 'front' });
  const frontEnemy = makeUnit('Front Enemy', { id: 'plan-front-enemy', disposition: App.DISPOSITION.ENEMY, CPun: 100, MPun: 100, combatRow: 'front' });
  const backEnemy = makeUnit('Back Enemy', { id: 'plan-back-enemy', disposition: App.DISPOSITION.ENEMY, CPun: 100, MPun: 100, combatRow: 'back' });
  App.player = player;
  App.party = [player, ally];
  App.creatures = [frontEnemy, backEnemy];
  App.combatState = {
    active: true,
    round: 1,
    currentTurn: 0,
    processing: false,
    xpEarned: 0,
    turnQueue: [{ unit: player, initiative: 30 }, { unit: ally, initiative: 20 }, { unit: frontEnemy, initiative: 10 }],
    syncActions: []
  };
  App.activeActor = player;

  const plan = App._buildPanelInteractionCommand({ mode: 'combat', actors: [player], targets: [frontEnemy, backEnemy], action: 'fight', source: 'combat-composer' });
  assertEqual(plan.plan.mode, 'combat', 'Combat command should carry a combat InteractionPlan');
  assertEqual(plan.shape, 'one-to-many', 'Current combat actor with multiple targets should infer one-to-many shape');
  assertEqual(plan.timing, 'current-turn', 'Combat target plans should default to current-turn timing');
  assertEqual(plan.constraints.requireCurrentTurn, true, 'Combat target plans should require the current turn');
  assertEqual(plan.constraints.hostileOnly, true, 'Combat target plans should preserve hostile-only targeting by default');
  assertEqual(plan.constraints.checkReach, true, 'Combat target plans should preserve reach checks by default');

  assertEqual(App._validateInteractionCommand(App._buildPanelInteractionCommand({ mode: 'combat', actors: [ally], targets: [frontEnemy], action: 'fight' })).ok, false, 'Combat plans should reject non-current actors');
  const backRowAttempt = App._validateInteractionCommand(App._buildPanelInteractionCommand({ mode: 'combat', actors: [player], targets: [backEnemy], action: 'fight' }));
  assertEqual(backRowAttempt.ok, true, 'Combat plans should accept a valid attempt against a protected physical target');
  assertEqual(App._combatReachResult(player, backEnemy, 'fight').canSucceed, false, 'Protected physical target should still preview its tactical failure');
  frontEnemy.CPun = 0;
  const exposedBackRow = App._validateInteractionCommand(App._buildPanelInteractionCommand({ mode: 'combat', actors: [player], targets: [backEnemy], action: 'fight' }));
  assertEqual(exposedBackRow.ok, true, 'Combat plans should allow exposed back-row targets when no front blockers remain');
  assertEqual(App._validateInteractionCommand(App._buildPanelInteractionCommand({ mode: 'combat', actors: [player], targets: [frontEnemy, backEnemy], action: 'fight', constraints: { maxTargets: 1 } })).reason, 'too-many-targets', 'Combat plans should enforce target count constraints when mechanics declare them');
});

