  App.party = [actor, helper, allyTarget];
  App.creatures = [creatureTarget];
  App.explorationActorIds = ['actor-1', 'helper-1'];
  App.explorationActorId = 'actor-1';
  App.explorationActorSelectionExplicit = true;
  App.updateLanguage('es');
  App.renderParty();
  App.renderCreatures();
