test('Starting and restoring combat clear adventure target marks', () => {
  const fresh = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'player-1' });
  const ally = makeUnit('Ally', { id: 'ally-1' });
  const enemy = makeUnit('Enemy', { id: 'enemy-1', disposition: fresh.App.DISPOSITION.ENEMY });
  fresh.App.player = player;
  fresh.App.party = [player, ally];
  fresh.App.creatures = [enemy];
  fresh.App.explorationActorIds = ['ally-1'];
  fresh.App.explorationTargetIds = ['party:ally-1', 'creature:enemy-1'];
  fresh.App.targetSelection = { action: 'flirt', source: 'adventure' };
  fresh.App.syncSelection = { active: true };
  fresh.App.feedSelection = { active: true };
  fresh.App.processTurn = () => {};
  fresh.App.startCombat([enemy]);
  assertEqual(fresh.App.combatState.active, true, 'Combat should start');
  assertEqual(fresh.App.explorationActorIds.includes('ally-1'), true, 'Selected adventure actor can survive combat entry as separate state');
  assertEqual(fresh.App.explorationTargetIds.length, 0, 'Combat entry should clear stale adventure target marks');
  assertEqual(fresh.App.targetSelection, null, 'Combat entry should clear stale non-combat target selection');
  assertEqual(fresh.App.syncSelection, null, 'Combat entry should clear stale sync selection');
  assertEqual(fresh.App.feedSelection, null, 'Combat entry should clear stale feed selection');

  const restored = loadAppForCombat(() => 0);
  const restoredPlayer = makeUnit('You', { id: 'player-restore' });
  const restoredEnemy = makeUnit('Enemy', { id: 'enemy-restore', disposition: restored.App.DISPOSITION.ENEMY });
  restored.App.player = restoredPlayer;
  restored.App.party = [restoredPlayer];
  restored.App.creatures = [restoredEnemy];
  restored.App.explorationActorIds = ['player-restore'];
  restored.App.explorationTargetIds = ['party:player-restore', 'creature:enemy-restore'];
  const restoredActive = restored.App._restoreCombatState({
    active: true,
    round: 2,
    currentTurn: 0,
    activeActorId: 'player-restore',
    turnQueue: [
      { unitId: 'player-restore', initiative: 20 },
      { unitId: 'enemy-restore', initiative: 10 }
    ],
    syncActions: []
  });
  assertEqual(restoredActive, true, 'Active combat should restore');
  assertEqual(restored.App.combatState.active, true, 'Restored combat should stay active');
  assertEqual(restored.App.explorationTargetIds.length, 0, 'Restoring active combat should clear stale adventure target marks');
});

test('Moving tiles clears current tile event feed but keeps durable log', () => {
  const { App, elements } = loadAppForCombat(() => 1);
  const player = makeUnit('You', { id: 'player-1' });
  App.player = player;
  App.party = [player];
  App.creatures = [];
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map([
    ['0,0', { x: 0, y: 0, biome: 'forest', explored: true, creatures: [], items: [], description: 'Start' }],
    ['1,0', { x: 1, y: 0, biome: 'forest', explored: true, creatures: [], items: [], description: 'Next' }]
  ]);
  App.exploredTiles = new Set(['0,0', '1,0']);
  App.log = [{ text: 'Old durable entry', type: 'discovery' }];
  App.tileEvents = [{ text: 'Old tile-only event', type: 'discovery', time: '08:00 Day' }];
  App.renderTileEvents();
  assertContains(elements.get('tile-event-feed').innerHTML, 'Old tile-only event', 'Precondition: tile feed should render current tile events');

  App.move(1, 0);

  assertEqual(App.log.some(entry => entry.text === 'Old durable entry'), true, 'Durable log should survive tile movement');
  assertEqual(App.tileEvents.some(entry => entry.text === 'Old tile-only event'), false, 'Tile feed should clear events from the prior tile');
  assertContains(elements.get('tile-event-feed').innerHTML, 'Moved to 1, 0', 'New tile feed should show arrival context');
  assertContains(elements.get('mobile-tile-event-feed').innerHTML, 'Moved to 1, 0', 'Mobile scene should mirror tile events');
});

test('Tile event feed renders safe actor intent and semantic metadata', () => {
  const { App, elements } = loadAppForCombat();
  App.location = { x: 2, y: -1 };
  App._addTileEvent('older scene beat', 'discovery', {
    actorName: 'Scout <One>',
    intent: 'Scout',
    semanticKind: 'speech',
    icon: '💬',
    label: 'Creature event'
  });
  const event = App._addTileEvent('checks the trail ahead', 'discovery', {
    actorName: 'Scout <One>',
    intent: 'Scout',
    semanticKind: 'speech',
    icon: '💬',
    label: 'Creature event'
  });
  assertEqual(event.actorName, 'Scout <One>', 'Tile event should preserve actor metadata');
  assertEqual(event.intent, 'Scout', 'Tile event should preserve intent metadata');
  assertEqual(event.semanticKind, 'speech', 'Tile event should preserve semantic kind');
  const desktopHtml = elements.get('tile-event-feed').innerHTML;
  const mobileHtml = elements.get('mobile-tile-event-feed').innerHTML;
  assertContains(desktopHtml, 'tile-event-feed compact', 'Desktop center tile should render the latest event as a compact presentation strip');
  assertNotContains(desktopHtml, 'tile-event-title', 'Desktop compact center feed should not render a boxed Here now title');
  assertContains(desktopHtml, 'data-event-kind="speech"', 'Desktop tile feed should expose semantic kind');
  assertContains(desktopHtml, 'Scout &lt;One&gt;', 'Desktop tile feed should escape actor labels');
  assertContains(desktopHtml, 'Scout', 'Desktop tile feed should render intent labels');
  assertContains(desktopHtml, 'checks the trail ahead', 'Desktop tile feed should render event text');
  assertNotContains(desktopHtml, 'older scene beat', 'Desktop center tile should show only the latest tile event');
  assertContains(desktopHtml, 'aria-label="Creature event"', 'Desktop tile feed should expose category label');
  assertContains(mobileHtml, 'data-event-kind="speech"', 'Mobile tile feed should mirror semantic kind');
  assertContains(mobileHtml, 'Scout &lt;One&gt;', 'Mobile tile feed should mirror escaped actor labels');
  assertNotContains(mobileHtml, 'older scene beat', 'Mobile scene should show only the latest tile event');
});

test('Recruitment is gated by pleasure and willingness score', () => {
  const { App, elements } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { cha: 10, Flir: 10, Fuck: 10, xp: 0, xpToNext: 1000 });
  const reluctant = makeUnit('Reluctant', { id: 'reluctant-1', disposition: App.DISPOSITION.FRIENDLY, CPle: 10, MPle: 100 });
  const willing = makeUnit('Willing', { id: 'willing-1', disposition: App.DISPOSITION.FRIENDLY, CPle: 90, MPle: 100, willing: true });
  const neutralReady = makeUnit('Neutral Ready', { id: 'neutral-ready-1', disposition: App.DISPOSITION.NEUTRAL, CPle: 85, MPle: 100 });
  App.player = player;
  App.party = [player];
  App.creatures = [reluctant, willing, neutralReady];
  App.updateLanguage('es');
  App.renderCreatures();
  const html = elements.get('enemies-content').innerHTML;
  assertNotContains(html, "selectIntent('creature','reluctant-1','recruit','panel-card')", 'Low-pleasure friendly should not show recruitment');
  assertNotContains(html, "selectIntent('creature','willing-1','recruit','panel-card')", 'High-pleasure willing friendly should not duplicate recruitment on the card');
  App.toggleExplorationTarget('creature', 'willing-1');
  assertContains(elements.get('desktop-context-belt').innerHTML, "selectIntent('creature','willing-1','recruit','composer-tray')", 'High-pleasure willing friendly should show recruitment through the composer');
  App.clearExplorationTargets();
  App.recruitCreatureById('reluctant-1');
  assert(!App.party.includes(reluctant), 'Low-score friendly should not join');
  assertContains(App.log[App.log.length - 1].text, 'Reluctant aun no esta listo para unirse al grupo.', 'Failed recruitment log should localize');
  App.recruitCreatureById('willing-1');
  assert(App.party.includes(willing), 'High-score willing friendly should join');
  App.recruitCreatureById('neutral-ready-1');
  assert(App.party.includes(neutralReady), 'High-spirit neutral should join when baseline recruit eligibility allows it');
  assertEqual(player.xp, App.BALANCE.recruitXP * 2, 'Successful recruitment should use configured recruit XP reward for each recruit');
  assertContains(App.log[App.log.length - 1].text, 'Neutral Ready se une a tu grupo!', 'Successful recruitment log should localize');
});

