test('Dropping carried inventory creates tile-local pickup state', () => {
  const { App } = loadAppForCombat(() => 1);
  const player = makeUnit('You');
  let autoSaveCalls = 0;
  App.player = player;
  App.party = [player];
  App.inventory = [{ id: 'pack-coin', name: 'Old Coin' }];
  App.autoSave = () => { autoSaveCalls += 1; };
  App.location = { x: 0, y: 0 };
  App.currentBiome = 'forest';
  App.worldMap = new Map([['0,0', { x: 0, y: 0, biome: 'forest', explored: true, description: 'A saved clearing.', creatures: [], items: [{ id: 'ground-herb', name: 'Healing Herb' }] }]]);

  assertEqual(App.dropItem('pack-coin'), true, 'Dropping carried inventory should report a handled action');
  assertEqual(App.inventory.length, 0, 'Dropping should remove only the carried item from inventory');
  assertEqual(App.worldMap.get('0,0').items.length, 2, 'Dropping should append to tile-local ground items');
  assertEqual(App.worldMap.get('0,0').items[1].name, 'Old Coin', 'Dropped item should keep its item identity on the tile');
  assertEqual(App.getTileDelta(0, 0).items[1].name, 'Old Coin', 'Dropped item should persist through sparse tile deltas');
  assertContains(App._centerTileContext().description, 'A saved clearing.', 'Center context should keep the tile prose after a drop');
  assertNotContains(App._centerTileContext().description, 'Items here: Healing Herb, Old Coin.', 'Center context should not duplicate dropped tile-local items');
  assertContains(App._renderContextActions(), 'App.takeTileItems()', 'Dropped tile-local items should expose pickup from the composer belt');
  assertContains(App.log[App.log.length - 1].text, 'Dropped Old Coin.', 'Dropping should log the item transfer');
  assertEqual(autoSaveCalls, 1, 'Dropping should autosave changed world and inventory state');
});

test('Interior item pickup and drop persist through structure tile deltas', () => {
  const { App } = loadAppForCombat(() => 1);
  const player = makeUnit('You');
  let autoSaveCalls = 0;
  App.player = player;
  App.party = [player];
  App.inventory = [];
  App.autoSave = () => { autoSaveCalls += 1; };
  App.location = { x: 0, y: 0 };
  App.currentBiome = 'forest';
  App.worldMap = new Map([['0,0', { x: 0, y: 0, biome: 'forest', explored: true, creatures: [], structure: 'cabin', structureSpawned: true }]]);
  App.STRUCTURES.cabin.enterable = true;
  App.enterStructure();
  autoSaveCalls = 0;
  App._currentExplorationTile().items = [{ id: 'room-key', name: 'Room Key' }];

  assertEqual(App.takeTileItems(), true, 'Interior tile-local pickup should report a handled action');
  assertEqual(App.inventory.length, 1, 'Interior pickup should move the room item into carried inventory');
  assertEqual(App._currentExplorationTile().items.length, 0, 'Interior pickup should remove the item from the current room');
  assertEqual(App.getTileDelta(0, 0).interior.tiles['0,0'].items.length, 0, 'Interior pickup should persist through the origin structure tile delta');

  assertEqual(App.dropItem('room-key'), true, 'Interior drop should report a handled action');
  assertEqual(App.inventory.length, 0, 'Interior drop should remove the carried item');
  assertEqual(App._currentExplorationTile().items[0].name, 'Room Key', 'Interior drop should place the item back in the current room');
  assertEqual(App.getTileDelta(0, 0).interior.tiles['0,0'].items[0].name, 'Room Key', 'Interior drop should persist through the origin structure tile delta');
  assertNotContains(App._centerTileContext().description, 'Items here: Room Key.', 'Interior center context should not duplicate room-local item presence');
  assertEqual(autoSaveCalls, 2, 'Interior pickup and drop should each autosave changed world and inventory state');
});

test('Interior movement persists room creatures and exits to overworld', () => {
  const { App } = loadAppForCombat(() => 1);
  const player = makeUnit('You');
  const roomCreature = makeUnit('Room Creature', { disposition: App.DISPOSITION.FRIENDLY });
  App.player = player;
  App.party = [player];
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map([['0,0', { x: 0, y: 0, biome: 'forest', explored: true, creatures: [], structure: 'cabin', structureSpawned: true }]]);
  App.STRUCTURES.cabin.enterable = true;
  App.updateLanguage('es');
  App.enterStructure();
  App.creatures = [roomCreature];
  const directionById = { north: [0, -1], east: [1, 0], south: [0, 1], west: [-1, 0] };
  const firstDirection = App.activeInterior.tiles['0,0'].connections[0];
  const [moveX, moveY] = directionById[firstDirection];
  App.move(moveX, moveY);
  assertEqual(App.activeInterior.tiles['0,0'].creatures.includes(roomCreature), true, 'Leaving an interior room should persist its creatures');
  assertEqual(`${App.interiorLocation.x},${App.interiorLocation.y}`, `${moveX},${moveY}`, 'Interior move should follow a connected cardinal room');
  assertEqual(App.log[App.log.length - 1].text, `Movimiento dentro de Cabin a ${moveX}, ${moveY}.`, 'Interior movement feedback should localize');
  const room = Object.values(App.activeInterior.tiles).sort((a, b) => a.connections.length - b.connections.length)[0];
  App.interiorLocation = { x: room.x, y: room.y };
  const blockedDirection = Object.keys(directionById).find(direction => !room.connections.includes(direction));
  App.move(...directionById[blockedDirection]);
  assertEqual(App.log[App.log.length - 1].text, 'Una pared bloquea el camino.', 'Interior wall feedback should localize');
  App.exitStructure();
  assertEqual(App.inInterior, false, 'Exit should return to overworld mode');
  assertEqual(App.log[App.log.length - 1].text, 'Saliste de Cabin.', 'Exit structure feedback should localize');
  assertEqual(App.location.x, 0, 'Exit should restore overworld x coordinate');
});

test('Legacy contaminated interiors regenerate without surface POIs', () => {
  const { App } = loadAppForCombat(() => 1);
  const tile = {
    x: 0,
    y: 0,
    biome: 'forest',
    explored: true,
    creatures: [],
    structure: 'dungeon',
    structureSpawned: true,
    interior: {
      id: 'legacy-interior',
      generatorVersion: 1,
      tiles: {
        '0,0': { x: 0, y: 0, biome: 'indoors', exit: true, structure: null },
        '1,0': { x: 1, y: 0, biome: 'indoors', exit: false, structure: 'hotSpring' }
      }
    }
  };
  App.worldMap = new Map([['0,0', tile]]);
  App.tileDeltas = new Map();

  const interior = App._ensureStructureInterior(tile);
  assertEqual(interior.generatorVersion, 2, 'Version-one interiors should migrate through deterministic regeneration');
  assertEqual(interior.id === 'legacy-interior', false, 'Legacy contaminated layout should be replaced rather than reused');
  assertEqual(Object.values(interior.tiles).every(room => room.structure === null), true, 'Regenerated dungeon cells should contain only interior room archetypes');
  assertEqual(App.getTileDelta(0, 0).interior.generatorVersion, 2, 'Regenerated interior should persist through the canonical tile delta');
});

