test('Mobile play surface resolves only the 3x3 traversal neighborhood without exploring it', () => {
  const { App, elements } = loadAppForCombat(() => 0);
  App.player = makeUnit('You');
  const ally = makeUnit('Ally', { id: 'ally-1', icon: '🧭' });
  const guide = makeUnit('Guide', { id: 'guide-1', icon: '👤', disposition: App.DISPOSITION.FRIENDLY });
  const trader = makeUnit('Trader', { id: 'trader-1', icon: '🧑', disposition: App.DISPOSITION.FRIENDLY });
  const watcher = makeUnit('Watcher', { id: 'watcher-1', icon: '👁️', disposition: App.DISPOSITION.FRIENDLY });
  App.party = [App.player, ally];
  App.creatures = [guide, trader, watcher];
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map();
  App.exploredTiles = new Set(['0,0']);
  App.getTile(0, 0).explored = true;
  App.renderMap();
  const adjacentTile = App.worldMap.get('1,0');
  assert(adjacentTile, 'Adjacent minimap tile should be resolved into worldMap');
  assertEqual(App.exploredTiles.has('1,0'), false, 'Resolved adjacent tile should not be marked explored');
  const adjacentBiome = App.biomes[adjacentTile.biome];
  const html = elements.get('mobile-mini-map').innerHTML;
  assertEqual((html.match(/data-mobile-play-cell=/g) || []).length, 9, 'Mobile routine play should render exactly 9 traversal cells');
  assertContains(html, 'data-mobile-play-cell="center"', 'Mobile routine play should expose a center tile');
  assertContains(html, 'data-stage-surface="current-tile" data-stage-layer="tile" data-stage-cell="center"', 'Mobile routine play should identify the center stage tile layer');
  assertContains(html, 'data-stage-surface="traversal-cell" data-stage-layer="tile" data-stage-cell="e"', 'Mobile routine play should identify traversal stage tile layers');
  assertContains(html, 'mobile-play-presence', 'Mobile center tile should include compact local presence');
  assertEqual((html.match(/mobile-play-presence-dot/g) || []).length, 1, 'Crowded mobile center tile should reserve one large presence control plus overflow');
  assertContains(html, 'mobile-play-presence-dot friendly', 'Mobile center tile should prioritize a directly selectable creature presence marker');
  assertContains(html, 'data-stage-surface="presence"', 'Mobile center presence should identify the stage presence surface');
  assertContains(html, 'data-command-surface="stage-presence"', 'Mobile center presence should identify stage-presence command routing');
  assertContains(html, 'data-command-surface="stage-presence" data-command-mode="exploration" data-command-grammar="actor-target-intent"', 'Mobile center actor/target presence should identify the shared command grammar');
  assertContains(html, 'data-command-control="focus-target"', 'Mobile center creature presence should identify target composer routing');
  assertContains(html, 'data-command-mode="exploration"', 'Mobile center presence should identify exploration command mode');
  assertContains(html, 'data-presence-type="creature"', 'Mobile center creature presence should identify its presence type');
  assertContains(html, "App.focusPresence('creature','guide-1')", 'Mobile center creature presence should select creature targets through the composer');
  assertNotContains(html, 'selected selected-actor', 'Implicit player fallback should not visibly mark mobile actor presence as explicitly selected');
  assertNotContains(html, 'data-selection-mode="act-actor" data-selection-state="selected"', 'Implicit player fallback should not expose selected actor state in mobile center presence');
  assertContains(html, 'aria-label="Mark Guide as target"', 'Mobile center creature presence should advertise mark-target semantics');
  assertContains(html, 'mobile-play-presence-more', 'Mobile center presence should expose overflow when local presence is clipped');
  assertContains(html, 'data-command-control="open-target-picker"', 'Mobile center presence overflow should identify target-picker routing when hidden creatures are clipped');
  assertContains(html, 'data-command-control="open-target-picker" data-command-grammar="actor-target-intent" data-command-slot="target"', 'Mobile center presence overflow should identify the target slot');
  assertContains(html, 'data-command-target-count="2"', 'Mobile center presence overflow should expose the hidden creature target count');
  assertContains(html, 'data-command-grammar="actor-target-intent"', 'Mobile center presence overflow should preserve the shared command grammar');
  assertContains(html, "App.focusPresenceOverflow('target')", 'Mobile center presence overflow should focus the advertised target picker');
  assertContains(html, 'aria-label="Open 2 hidden targets; 4 total hidden"', 'Mobile center overflow presence should describe filtered target-picker scope');
  assertNotContains(html, 'aria-label="Open 2 more in details"', 'Mobile center target overflow should not advertise drawer details');
  assertNotContains(html, 'toggleExplorationTarget(', 'Mobile center presence should not duplicate target marking controls');
  assertNotContains(html, 'selectIntent(', 'Mobile center presence should not duplicate intent controls');
  assertContains(html, 'data-mobile-play-cell="e"', 'Mobile routine play should expose east movement');
  assertContains(html, 'onclick="App.move(1,0)"', 'Mobile east cell should use normal movement dispatch');
  assertContains(html, adjacentBiome.icon, 'Adjacent tile biome icon should render on mobile play surface');
  assertContains(html, adjacentBiome.name, 'Adjacent tile biome name should be available as label');
});

test('Map tile visuals expose tileset keys while preserving base biome identity', () => {
  const { App, elements } = loadAppForCombat();
  const forestRoad = {
    x: 0,
    y: 0,
    biome: 'forest',
    baseBiome: 'forest',
    derivedBiome: 'forest',
    displayBiome: 'road',
    explored: true,
    creatures: [],
    overlays: { road: { id: 'road-test', direction: 'north-south' } }
  };
  const waterBridge = {
    x: 1,
    y: 0,
    biome: 'water',
    baseBiome: 'water',
    derivedBiome: 'water',
    displayBiome: 'bridge',
    water: true,
    explored: true,
    creatures: [],
    overlays: {
      road: { id: 'road-test', direction: 'east-west' },
      bridge: { id: 'bridge-test', direction: 'east-west', roadId: 'road-test' }
    }
  };
  const campTile = {
    x: 0,
    y: 1,
    biome: 'grove',
    baseBiome: 'grove',
    derivedBiome: 'grove',
    displayBiome: 'grove',
    explored: true,
    creatures: [],
    structure: 'camp',
    overlays: {}
  };

  const roadVisual = App._mapTileVisual(forestRoad);
  const bridgeVisual = App._mapTileVisual(waterBridge);
  const campVisual = App._mapTileVisual(campTile);
  assertEqual(roadVisual.tilesetKey, 'route-road-vertical', 'Road visual should expose a direction-specific tileset key');
  assertEqual(roadVisual.baseTilesetKey, 'terrain-forest', 'Road visual should preserve forest base terrain key');
  assertEqual(roadVisual.routeShape, 'north-south', 'Road visual should use stored direction when no neighbor resolver is available');
  assertEqual(roadVisual.asset.key, 'route-road-vertical', 'Road visual should resolve manifest asset metadata');
  assertEqual(roadVisual.asset.tilesetId, 'default-basic-tileset', 'Road visual should resolve through the bundled basic tileset when available');
  assertEqual(roadVisual.asset.src, '../media/basic-tileset-overlays-v1.png', 'Road visual metadata should identify the transparent sidecar overlay atlas');
  assertEqual(roadVisual.hasPaintedAsset, true, 'Road visual should flag bundled painted asset metadata when available');
  assertEqual(forestRoad.biome, 'forest', 'Visual mapping should not replace the base biome with road');
  assertEqual(bridgeVisual.tilesetKey, 'route-bridge-horizontal', 'Bridge visual should expose a direction-specific tileset key');
  assertEqual(bridgeVisual.baseTilesetKey, 'terrain-water', 'Bridge visual should preserve water base terrain key');
  assertEqual(campVisual.tilesetKey, 'structure-camp', 'Known structures should expose structure tileset keys');
  assertEqual(App._mapTileVisual(null).tilesetKey, 'unknown', 'Unknown tiles should expose a stable unknown key');

  forestRoad.overlays.road.connections = ['east'];
  App.player = makeUnit('You');
  App.party = [App.player];
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map([
    ['0,0', forestRoad],
    ['1,0', waterBridge],
    ['0,1', campTile],
    ['0,-1', { ...campTile, x: 0, y: -1, structure: null }],
    ['-1,0', { ...campTile, x: -1, y: 0, structure: null }]
  ]);
  App.exploredTiles = new Set(['0,0', '1,0', '0,1']);
  App.renderMap();
  App.renderLargeMap();
  assertContains(elements.get('mobile-mini-map').innerHTML, 'data-tileset-key="route-road-end-east"', 'Mobile minimap should infer a directional road end from known connections');
  assertContains(elements.get('mobile-mini-map').innerHTML, 'data-base-tileset-key="terrain-forest"', 'Mobile minimap should render base terrain tileset keys');
  assertContains(elements.get('mobile-mini-map').innerHTML, 'data-tileset-semantic-keys="terrain-forest route-road-end-east', 'Mobile minimap should expose its ordered base and directional-route semantic stack');
  assertContains(elements.get('large-map').innerHTML, 'data-tileset-key="route-bridge-horizontal"', 'Large map should render bridge tileset keys');
  assertContains(elements.get('large-map').innerHTML, 'data-tileset-key="structure-camp"', 'Large map should render structure tileset keys');
  assertContains(elements.get('large-map').innerHTML, 'data-asset-id="default-basic-tileset:structure-camp"', 'Large map should expose bundled basic structure asset ids');
  assertContains(elements.get('large-map').innerHTML, 'data-asset-src="../media/basic-tileset-v1.png"', 'Large map should expose the relative sidecar bitmap path');
});

test('Map route visuals infer corners and intersections from known neighbors', () => {
  const { App, elements } = loadAppForCombat();
  const road = (x, y, direction = 'east-west') => ({
    x,
    y,
    biome: 'plains',
    baseBiome: 'plains',
    derivedBiome: 'plains',
    displayBiome: 'road',
    explored: true,
    creatures: [],
    overlays: { road: { id: `road-${x}-${y}`, direction } }
  });
  const cornerCenter = road(0, 0, 'east-west');
  const cornerTiles = new Map([
    ['0,0', cornerCenter],
    ['0,-1', road(0, -1, 'north-south')],
    ['1,0', road(1, 0, 'east-west')]
  ]);
  const cornerResolver = (x, y) => cornerTiles.get(`${x},${y}`) || null;
  const cornerVisual = App._mapTileVisual(cornerCenter, { neighborResolver: cornerResolver });
  assertEqual(cornerVisual.routeShape, 'corner-ne', 'Known north/east road neighbors should infer a corner shape');
  assertEqual(cornerVisual.tilesetKey, 'route-road-corner-ne', 'Corner route shape should map to a directional tileset key');

  const intersectionCenter = road(5, 5, 'east-west');
  const intersectionTiles = new Map([
    ['5,5', intersectionCenter],
    ['5,4', road(5, 4, 'north-south')],
    ['6,5', road(6, 5, 'east-west')],
    ['5,6', road(5, 6, 'north-south')],
    ['4,5', road(4, 5, 'east-west')]
  ]);
  const intersectionResolver = (x, y) => intersectionTiles.get(`${x},${y}`) || null;
  const intersectionVisual = App._mapTileVisual(intersectionCenter, { neighborResolver: intersectionResolver });
  assertEqual(intersectionVisual.routeShape, 'intersection', 'Four known road neighbors should infer an intersection');
  assertEqual(intersectionVisual.tilesetKey, 'route-road-intersection', 'Intersection route shape should map to the intersection tileset key');

  App.player = makeUnit('You');
  App.party = [App.player];
  App.location = { x: 0, y: 0 };
  App.worldMap = cornerTiles;
  App.exploredTiles = new Set(['0,0', '0,-1', '1,0']);
  App.renderLargeMap();
  assertContains(elements.get('large-map').innerHTML, 'data-route-shape="corner-ne"', 'Rendered large map should expose inferred corner route shape from known tiles');
  assertContains(elements.get('large-map').innerHTML, 'data-tileset-key="route-road-corner-ne"', 'Rendered large map should expose inferred corner tileset key from known tiles');
});

test('Touching road segments merge visually while bridges preserve their axis', () => {
  const { App } = loadAppForCombat();
  const road = (x, y, id, connections = []) => ({
    x,
    y,
    biome: 'grove',
    baseBiome: 'grove',
    derivedBiome: 'grove',
    explored: true,
    creatures: [],
    overlays: { road: { id, direction: 'north-south', connections } }
  });
  const center = road(0, 0, 'road-a', ['north', 'south']);
  const east = road(1, 0, 'road-b', ['north', 'south']);
  const north = road(0, -1, 'road-a', ['south']);
  const south = road(0, 1, 'road-a', ['north']);
  const tiles = new Map([
    ['0,0', center],
    ['1,0', east],
    ['0,-1', north],
    ['0,1', south]
  ]);
  const resolver = (x, y) => tiles.get(`${x},${y}`) || null;
  const merged = App._mapTileVisual(center, { neighborResolver: resolver });
  assertEqual(merged.routeShape, 't-east', 'Touching generated road segments should read as one continuous junction');
  assertEqual(merged.tilesetKey, 'route-road-t-east', 'Merged road segments should select the matching T-junction art');

  tiles.set('1,0', {
    ...east,
    overlays: {
      road: east.overlays.road,
      bridge: { direction: 'north-south', connections: ['north', 'south'] }
    }
  });
  const constrained = App._mapTileVisual(center, { neighborResolver: resolver });
  assertEqual(constrained.routeShape, 'vertical', 'A perpendicular bridge should not create a false road-to-bridge junction');

  tiles.set('1,0', { ...east, water: true, biome: 'water', overlays: {} });
  const pruned = App._mapTileVisual(center, { neighborResolver: resolver });
  assertEqual(pruned.routeShape, 'vertical', 'A resolved non-route water tile should remove a stale explicit road seam');
});

