test('Road and bridge overlays are deterministic constrained features', () => {
  const { App } = loadAppForCombat();
  App.worldMeta = { worldId: 'world-routes', seed: 'route-seed', generatorVersion: 2, mapModsHash: 'core' };
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  let roadTile = null;
  let bridgeTile = null;
  let waterWithoutRoad = null;
  let sampledWaterRoads = 0;
  for (let x = -140; x <= 140 && (!roadTile || !bridgeTile || !waterWithoutRoad || sampledWaterRoads === 0); x++) {
    for (let y = -140; y <= 140 && (!roadTile || !bridgeTile || !waterWithoutRoad || sampledWaterRoads === 0); y++) {
      const tile = App.getBaseTile(x, y);
      if (!roadTile && tile.overlays?.road) roadTile = tile;
      if (!bridgeTile && tile.overlays?.bridge) bridgeTile = tile;
      if (!waterWithoutRoad && tile.water && !tile.overlays?.road) waterWithoutRoad = tile;
      if (tile.water && tile.overlays?.road) {
        sampledWaterRoads += 1;
        assert(tile.overlays.bridge, 'Every generated road over deep water should materialize as a valid bridge');
        assertEqual(tile.traversal.passable, true, 'A retained water crossing should be traversable');
      }
    }
  }
  assert(roadTile, 'Test seed should produce at least one deterministic road overlay');
  assertEqual(roadTile.biome === 'road', false, 'Road should be an overlay, not a base biome replacement');
  assert(bridgeTile, 'Test seed should produce at least one deterministic bridge overlay in the sampled area');
  assert(bridgeTile.overlays.road, 'Bridge requires a road overlay');
  assertEqual(bridgeTile.water, true, 'Bridge requires a water crossing tile');
  assert(['east-west', 'north-south'].includes(bridgeTile.overlays.bridge.direction), 'Bridge direction should be coherent');
  assertEqual(bridgeTile.overlays.bridge.roadId, bridgeTile.overlays.road.id, 'Bridge should reference its road overlay');
  assertEqual(bridgeTile.biome === 'bridge', false, 'Bridge should be an overlay, not a base biome replacement');
  assert(waterWithoutRoad, 'Test seed should produce a water tile without road overlay');
  assertEqual(Boolean(waterWithoutRoad.overlays?.bridge), false, 'Bridge should not appear without a road overlay');
  assert(sampledWaterRoads > 0, 'Sampled routes should include at least one valid bridged water crossing');
});

test('Terrain traversal metadata defines conservative passability and route costs', () => {
  const WorldGen = loadWorldGenForTest();
  const plain = WorldGen.getTraversal({ biome: 'plains', water: false, overlays: {} });
  const forest = WorldGen.getTraversal({ biome: 'forest', water: false, overlays: {} });
  const forestRoad = WorldGen.getTraversal({ biome: 'forest', baseBiome: 'forest', water: false, overlays: { road: { id: 'road-test' } } });
  const water = WorldGen.getTraversal({ biome: 'water', water: true, overlays: {} });
  const bridge = WorldGen.getTraversal({ biome: 'water', water: true, overlays: { road: { id: 'road-test' }, bridge: { id: 'bridge-test' } } });
  const beach = WorldGen.getTraversal({ biome: 'beach', water: false, overlays: {} });
  const cliff = WorldGen.getTraversal({ biome: 'cliff', water: false, overlays: {} });
  assertEqual(plain.passable, true, 'Plain terrain should be passable');
  assertEqual(water.passable, false, 'Deep water should be blocked without capability or bridge');
  assertEqual(water.requiredCapability, 'swim', 'Blocked water should declare a swim capability contract');
  assertEqual(bridge.passable, true, 'Bridge should make water crossing passable');
  assertEqual(bridge.traversalCost, 1, 'Bridge should provide road-like traversal cost');
  assertEqual(beach.passable, true, 'Beach/coast should be passable');
  assert(cliff.traversalCost > plain.traversalCost, 'Cliff should cost more to traverse than plain terrain');
  assert(forestRoad.traversalCost < forest.traversalCost, 'Road overlay should lower traversal cost without replacing the forest biome');
});

test('Traversal resolver enforces cardinal terrain and bridge topology', () => {
  const { App } = loadAppForCombat();
  App.player = makeUnit('You');
  App.party = [App.player];
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map([
    ['0,0', { x: 0, y: 0, biome: 'plains', traversal: { passable: true, traversalCost: 1 }, overlays: {} }],
    ['1,0', { x: 1, y: 0, biome: 'water', water: true, traversal: { passable: false, traversalCost: 5, requiredCapability: 'swim' }, overlays: {} }],
    ['0,-1', { x: 0, y: -1, biome: 'forest', traversal: { passable: true, traversalCost: 2 }, overlays: {} }]
  ]);
  assertEqual(App._traversalDecision(1, 1).reasonCode, 'cardinal-only', 'Diagonal travel should be rejected by the shared resolver');
  assertEqual(App._traversalDecision(1, 0).reasonCode, 'capability', 'Deep water should require declared traversal capability');
  assertEqual(App._traversalDecision(0, -1).cost, 2, 'Traversal should return target terrain time cost');

  App.worldMap.set('1,0', {
    x: 1, y: 0, biome: 'water', water: true,
    traversal: { passable: true, traversalCost: 1 },
    overlays: { bridge: { direction: 'north-south', connections: ['north', 'south'] } }
  });
  assertEqual(App._traversalDecision(1, 0).reasonCode, 'bridge-direction', 'A north-south bridge should block east-west entry');
  App.worldMap.get('1,0').overlays.bridge = { direction: 'east-west', connections: ['east', 'west'] };
  assertEqual(App._traversalDecision(1, 0).allowed, true, 'An east-west bridge should permit east-west entry');
});

test('Generator v3 separates interior themes and creates reciprocal route topology', () => {
  const { App } = loadAppForCombat();
  App.worldMeta = { worldId: 'world-v3-topology', seed: 'topology-seed', generatorVersion: 3, mapModsHash: 'core' };
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  const regionKeys = App._regionBiomeKeys();
  assert(!regionKeys.includes('cave'), 'Cave should be an interior theme instead of an overworld region');
  assert(!regionKeys.includes('dungeon'), 'Dungeon should be a structure interior instead of an overworld region');
  assert(!regionKeys.includes('manor'), 'Manor should be a structure interior instead of an overworld region');
  let checked = 0;
  for (let x = -80; x <= 80 && checked < 10; x++) {
    for (let y = -80; y <= 80 && checked < 10; y++) {
      const tile = App.getBaseTile(x, y);
      const connections = tile.overlays?.road?.connections || [];
      for (const direction of connections) {
        const delta = { north: [0, -1, 'south'], east: [1, 0, 'west'], south: [0, 1, 'north'], west: [-1, 0, 'east'] }[direction];
        const neighbor = App.getBaseTile(x + delta[0], y + delta[1]);
        assertEqual(neighbor.overlays?.road?.id, tile.overlays.road.id, 'Explicit road connection should reference the same route on both tiles');
        assert(neighbor.overlays.road.connections.includes(delta[2]), 'Explicit road connection should be reciprocal');
        checked += 1;
      }
    }
  }
  assert(checked > 0, 'Generator v3 should expose explicit road connections in the sampled area');
});

test('Generator v3 cave cells expose two mouths into one bounded underground network', () => {
  const WorldGen = loadWorldGenForTest();
  const { App } = loadAppForCombat();
  App.worldMeta = { worldId: 'world-v3-caves', seed: 'cave-cell-seed', generatorVersion: 3, mapModsHash: 'core' };
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  const network = WorldGen.getCavePortalsForCell(App.worldMeta.seed, 3, 2, -1);
  assertEqual(network.portals.length, 2, 'Each initial cave cell should expose two surface portals');
  assert(network.portals[0].x !== network.portals[1].x || network.portals[0].y !== network.portals[1].y, 'Cave portals should occupy different surface tiles');
  const first = App.getTile(network.portals[0].x, network.portals[0].y);
  const second = App.getTile(network.portals[1].x, network.portals[1].y);
  assertEqual(first.structure, 'cave', 'First portal should materialize as a cave structure');
  assertEqual(second.site.networkId, first.site.networkId, 'Both surface mouths should reference one cave network');
  App.player = makeUnit('You');
  App.party = [App.player];
  App.creatures = [];
  App.location = { x: first.x, y: first.y };
  App.enterStructure();
  assertEqual(App.activeInterior.kind, 'cave-network', 'Cellular cave portals should generate a cave-network interior');
  assertEqual(Object.keys(App.activeInterior.tiles).length, 13, 'Initial cave networks should stay bounded');
  const directions = {
    north: { dx: 0, dy: -1, opposite: 'south' },
    east: { dx: 1, dy: 0, opposite: 'west' },
    south: { dx: 0, dy: 1, opposite: 'north' },
    west: { dx: -1, dy: 0, opposite: 'east' }
  };
  const firstEntryKey = App.activeInterior.entryRooms[first.site.portalId];
  const secondEntryKey = App.activeInterior.entryRooms[second.site.portalId];
  assertEqual(`${App.interiorLocation.x},${App.interiorLocation.y}`, firstEntryKey, 'Entering the first mouth should place the player in its authored portal room');
  const queue = [{ key: firstEntryKey, path: [] }];
  const visited = new Set([firstEntryKey]);
  let route = null;
  while (queue.length) {
    const current = queue.shift();
    if (current.key === secondEntryKey && !route) {
      route = current.path;
    }
    const room = App.activeInterior.tiles[current.key];
    for (const directionId of room.connections || []) {
      const direction = directions[directionId];
      assert(direction, `Cave room ${current.key} should only expose cardinal connection ids`);
      const nextKey = `${room.x + direction.dx},${room.y + direction.dy}`;
      const nextRoom = App.activeInterior.tiles[nextKey];
      assert(nextRoom, `Cave connection ${directionId} from ${current.key} should lead to a real room`);
      assert(nextRoom.connections.includes(direction.opposite), `Cave connection ${directionId} from ${current.key} should be reciprocal`);
      if (visited.has(nextKey)) continue;
      visited.add(nextKey);
      queue.push({ key: nextKey, path: [...current.path, direction] });
    }
  }
  assert(route && route.length > 0, 'The two surface cave mouths should have a traversable underground route between them');
  assertEqual(visited.size, Object.keys(App.activeInterior.tiles).length, 'Every generated cave branch should remain connected to the two-mouth trunk');
  App._worldChance = () => false;
  App.autoSave = () => true;
  route.forEach(direction => {
    assertEqual(App.moveInterior(direction.dx, direction.dy), true, 'The player should traverse each reciprocal cave connection toward the second mouth');
  });
  assertEqual(`${App.interiorLocation.x},${App.interiorLocation.y}`, secondEntryKey, 'Traversing the cave should reach the other portal room without teleporting');
  App.exitStructure();
  assertEqual(`${App.location.x},${App.location.y}`, `${second.x},${second.y}`, 'The second underground exit should emerge from the other surface portal');
});

test('Generated structure interiors form connected reciprocal room graphs with one surface exit', () => {
  const { App } = loadAppForCombat();
  const structures = [
    { id: 'cabin', budget: 6, kind: 'building' },
    { id: 'ruins', budget: 12, kind: 'building' },
    { id: 'burrow', budget: 10, kind: 'burrow' },
    { id: 'manor', budget: 14, kind: 'building' },
    { id: 'dungeon', budget: 16, kind: 'building' }
  ];
  const directions = {
    north: { dx: 0, dy: -1, opposite: 'south' },
    east: { dx: 1, dy: 0, opposite: 'west' },
    south: { dx: 0, dy: 1, opposite: 'north' },
    west: { dx: -1, dy: 0, opposite: 'east' }
  };

  for (const [index, expected] of structures.entries()) {
    const x = 30 + index;
    const y = -20 - index;
    App.worldMeta = { worldId: `interior-graph-${expected.id}`, seed: `interior-graph-${expected.id}`, generatorVersion: 3, mapModsHash: 'core' };
    App.worldMap = new Map();
    App.tileDeltas = new Map();
    const tile = {
      ...App.getBaseTile(x, y),
      x,
      y,
      explored: true,
      structure: expected.id,
      creatures: [],
      items: []
    };
    App.worldMap.set(`${x},${y}`, tile);
    const interior = App._ensureStructureInterior(tile);
    const rooms = Object.values(interior.tiles);

    assertEqual(interior.kind, expected.kind, `${expected.id} should generate the expected interior kind`);
    assertEqual(rooms.length, expected.budget, `${expected.id} should fill its bounded room budget`);
    assertEqual(interior.entryRooms.default, '0,0', `${expected.id} should expose its authored entry room`);
    assertEqual(rooms.filter(room => room.exit).length, 1, `${expected.id} should expose exactly one surface exit`);
    assertEqual(interior.tiles['0,0'].exit, true, `${expected.id} entry room should be its surface exit`);
    assert(rooms.every(room => room.structure === null), `${expected.id} rooms should not inherit surface structures`);

    const queue = ['0,0'];
    const visited = new Set(queue);
    while (queue.length) {
      const roomKey = queue.shift();
      const room = interior.tiles[roomKey];
      for (const directionId of room.connections || []) {
        const direction = directions[directionId];
        assert(direction, `${expected.id} room ${roomKey} should only expose cardinal connection ids`);
        const nextKey = `${room.x + direction.dx},${room.y + direction.dy}`;
        const nextRoom = interior.tiles[nextKey];
        assert(nextRoom, `${expected.id} connection ${directionId} from ${roomKey} should lead to a real room`);
        assert(nextRoom.connections.includes(direction.opposite), `${expected.id} connection ${directionId} from ${roomKey} should be reciprocal`);
        if (visited.has(nextKey)) continue;
        visited.add(nextKey);
        queue.push(nextKey);
      }
    }
    assertEqual(visited.size, rooms.length, `Every generated ${expected.id} room should be reachable from its surface exit`);
  }
});

test('Versioned start area validation guarantees early route and rest access', () => {
  const WorldGen = loadWorldGenForTest();
  const { App, elements } = loadAppForCombat();
  const seeds = ['default', 'layout-a', 'layout-b', 'route-seed', 'coastal-seed', 'wet-start', 'mountain-start'];
  for (const generatorVersion of [2, 3]) {
    for (const seed of seeds) {
    App.worldMeta = { worldId: `world-start-safe-v${generatorVersion}-${seed}`, seed, generatorVersion, mapModsHash: 'core' };
    App.worldMap = new Map();
    App.tileDeltas = new Map();
    App.exploredTiles = new Set();
    const result = WorldGen.validateStartArea(App.worldMeta, App._regionBiomeKeys());
    assertEqual(result.ok, true, `Versioned start area should satisfy safety invariants for generator v${generatorVersion}, seed ${seed}`);
    assertEqual(result.checks.safeBiomeRadius, true, `Start area should have enough low-danger passable terrain for seed ${seed}`);
    assertEqual(result.checks.noHardLockout, true, `Start should not be surrounded by blocked terrain for seed ${seed}`);
    assertEqual(result.checks.lowDangerResource, true, `Start should have low-danger resource terrain for seed ${seed}`);
    assertEqual(result.checks.resourceSite, true, `Start should have a reachable starter resource site for seed ${seed}`);
    assertEqual(result.checks.routeAccess, true, `Start should have nearby route access for seed ${seed}`);
    assertEqual(result.checks.restCandidate, true, `Start should have a nearby rest-site candidate for seed ${seed}`);
    assertEqual(result.checks.connectedRestRoute, true, `Start should have a reachable route to rest for seed ${seed}`);
    assertEqual(result.checks.recoveryReachable, true, `Start should expose a reachable recovery-anchor seam for seed ${seed}`);
    assert(result.paths.recoveryAnchor.length > 0, `Start should retain a deterministic recovery path for seed ${seed}`);
    assertEqual(result.checks.earlyPoi, true, `Start should have early POI availability for seed ${seed}`);
    assert(result.metrics.reachableTiles >= result.metrics.safeTiles, `Start validation should count safe terrain from reachable tiles for seed ${seed}`);
    assertEqual(result.metrics.nearestResourceSite?.x, -2, `Start validation should identify the deterministic resource-site x for seed ${seed}`);
    assertEqual(result.metrics.nearestResourceSite?.y, 0, `Start validation should identify the deterministic resource-site y for seed ${seed}`);
    assertEqual(result.metrics.nearestRestCandidate?.x, 4, `Start validation should identify the deterministic rest-site x for seed ${seed}`);
    assertEqual(result.metrics.nearestRestCandidate?.y, 0, `Start validation should identify the deterministic rest-site y for seed ${seed}`);
    assertEqual(JSON.stringify(result.paths.resourceSite.map(({ x, y }) => [x, y])), JSON.stringify([[0, 0], [-1, 0], [-2, 0]]), `Start validation should expose a concrete route to the resource site for seed ${seed}`);
    assertEqual(JSON.stringify(result.paths.restCandidate.map(({ x, y }) => [x, y])), JSON.stringify([[0, 0], [1, 0], [2, 0], [3, 0], [4, 0]]), `Start validation should expose a concrete route to the rest site for seed ${seed}`);
    [...result.paths.resourceSite, ...result.paths.restCandidate].forEach(({ x, y }) => {
      assertEqual(App.getBaseTile(x, y).traversal.passable, true, `Start validation path tile ${x},${y} should be passable for seed ${seed}`);
    });

    const startBase = App.getBaseTile(0, 0);
    assertEqual(startBase.traversal.passable, true, `Start tile should be passable for seed ${seed}`);
    const passableAdjacent = [[1, 0], [-1, 0], [0, 1], [0, -1]]
      .filter(([dx, dy]) => App.getBaseTile(dx, dy).traversal.passable).length;
    assert(passableAdjacent >= 2, `Start should have at least two passable cardinal exits for seed ${seed}`);

    const startRoad = [];
    for (let x = 0; x <= 4; x++) {
      const tile = App.getBaseTile(x, 0);
      startRoad.push(tile);
      assert(tile.overlays?.road, `Route to start rest site should stay on road at ${x},0 for seed ${seed}`);
      assertEqual(tile.traversal.passable, true, `Route tile ${x},0 should be passable for seed ${seed}`);
    }
    assert(startRoad.every(tile => ['grove', 'plains', 'forest', 'beach'].includes(tile.baseBiome)), `Start route should stay on safe base terrain for seed ${seed}`);

    const restBase = App.getBaseTile(4, 0);
    assertEqual(restBase.overlays?.poi?.category, 'restSite', `Start rest candidate should be a deterministic rest-site POI for seed ${seed}`);
    const discovered = App.exploreTile(4, 0);
    assertEqual(discovered.structure, 'camp', `Rest-site POI should resolve to a rest-capable structure on discovery for seed ${seed}`);
    App.player = makeUnit('You', { CPun: 30, MPun: 100 });
    App.party = [App.player];
    App.location = { x: 4, y: 0 };
    App.renderExplorationActions();
    assertContains(elements.get('desktop-context-belt').innerHTML, 'App.rest()', `Starter rest site should expose Rest for seed ${seed}`);
    App.rest();
    assert(App.player.CPun > 30, `Starter rest site should recover the player for seed ${seed}`);

    const resourceBase = App.getBaseTile(-2, 0);
    assertEqual(resourceBase.overlays?.poi?.category, 'resourceSite', `Start resource candidate should be a deterministic resource-site POI for seed ${seed}`);
    App.player = makeUnit('You');
    App.party = [App.player];
    App.inventory = [];
    App.location = { x: -2, y: 0 };
    App.exploreTile(-2, 0);
    App.renderExplorationActions();
    assertContains(elements.get('desktop-context-belt').innerHTML, 'App.search()', `Starter resource site should expose Search for seed ${seed}`);
    App.search();
    assertEqual(App.inventory.length, 1, `Starter resource site search should grant one item for seed ${seed}`);
    assertEqual(App.getTile(-2, 0).resourceSearched, true, `Starter resource site should persist consumed state for seed ${seed}`);
    }
  }
});

test('Map summary and encounter pressure expose safe UI metadata', () => {
  const WorldGen = loadWorldGenForTest();
  const wildTile = {
    x: 8,
    y: -2,
    biome: 'forest',
    baseBiome: 'forest',
    derivedBiome: 'forest',
    displayBiome: 'forest',
    dangerPressure: 0.5,
    overlays: {},
    terrainTags: ['dense-growth'],
    explored: false
  };
  const roadTile = { ...wildTile, overlays: { road: { id: 'road-test' } }, terrainTags: ['dense-growth', 'road'] };
  const dangerTile = { ...wildTile, overlays: { dangerInfluence: { siteId: 'danger-test', category: 'dangerSite', distance: 1, modifier: 0.1 } } };
  const wildPressure = WorldGen.getEncounterPressure(wildTile, { biomeDanger: 3 });
  const roadPressure = WorldGen.getEncounterPressure(roadTile, { biomeDanger: 3 });
  const dangerPressure = WorldGen.getEncounterPressure(dangerTile, { biomeDanger: 3 });
  assert(roadPressure.finalChance < wildPressure.finalChance, 'Road overlay should lower wilderness encounter pressure');
  assert(dangerPressure.finalChance > wildPressure.finalChance, 'Bounded danger-site influence should raise encounter pressure');
  const summary = WorldGen.getTileMapSummary({
    ...roadTile,
    structure: 'camp',
    overlays: { ...roadTile.overlays, poi: { category: 'restSite' } },
    explored: true,
    creatures: [
      { name: 'Merchant', disposition: 'merchant', stock: [{ id: 'ration' }] },
      { name: 'Guide', disposition: 'friendly' }
    ]
  }, { biomeDanger: 3, questRelevant: true });
  assertEqual(summary.biome, 'forest', 'Summary should keep the display/base biome visible');
  assertEqual(summary.coords.x, 8, 'Summary should expose coordinates');
  assertEqual(summary.traversal.passable, true, 'Summary should expose traversal contract');
  assertEqual(summary.restAvailable, true, 'Summary should expose safe rest availability');
  assert(summary.markers.includes('Road'), 'Summary should expose route markers');
  assert(summary.markers.includes('Merchant'), 'Summary should expose merchant markers from tile creatures');
  assert(summary.markers.includes('Quest'), 'Summary should expose quest relevance markers');
  assertEqual(summary.questRelevant, true, 'Summary should preserve quest relevance flag');
});

test('POI budgets create stable spaced region candidates and route anchors', () => {
  const WorldGen = loadWorldGenForTest();
  const seed = 'poi-budget-seed';
  const version = 2;
  const budgetA = WorldGen.getPoiBudgetForRegion(seed, version, 3, -2);
  const budgetB = WorldGen.getPoiBudgetForRegion(seed, version, 3, -2);
  assertEqual(JSON.stringify(budgetA), JSON.stringify(budgetB), 'POI budget should be stable for a seed/version/region');
  assertEqual(budgetA.regionId, '3,-2', 'POI budget should expose stable region identity');
  assert(budgetA.categories.restSite.count >= 1, 'Region budget should include at least one rest-site opportunity');
  assert(budgetA.categories.resourceSite.count >= 1, 'Region budget should include at least one resource opportunity');
  assert(budgetA.categories.landmark.count >= 1, 'Region budget should include at least one landmark opportunity');

  const candidatesA = WorldGen.getPoiCandidatesForRegion(seed, version, 3, -2);
  const candidatesB = WorldGen.getPoiCandidatesForRegion(seed, version, 3, -2);
  assertEqual(JSON.stringify(candidatesA), JSON.stringify(candidatesB), 'POI candidates should be stable for a seed/version/region');
  assert(candidatesA.length > 0, 'Region should expose deterministic POI candidates');
  for (let i = 0; i < candidatesA.length; i++) {
    for (let j = i + 1; j < candidatesA.length; j++) {
      if (candidatesA[i].category !== candidatesA[j].category) continue;
      const dx = candidatesA[i].anchor.x - candidatesA[j].anchor.x;
      const dy = candidatesA[i].anchor.y - candidatesA[j].anchor.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      assert(dist >= candidatesA[i].minDistance, `POI candidates in ${candidatesA[i].category} should respect minimum spacing`);
    }
  }
  const routeAnchors = WorldGen.getRouteAnchorsForRegion(seed, version, 3, -2);
  assert(routeAnchors.length > 0, 'Region should expose route anchors');
  assert(routeAnchors.every(anchor => anchor.routeAnchor), 'Route anchor seam should only return route-capable anchors');
  const first = candidatesA[0];
  const tilePoi = WorldGen.getPoiForTile(seed, version, first.anchor.x, first.anchor.y);
  assert(tilePoi, 'Tile lookup should resolve deterministic POI candidate anchors');
  assertEqual(tilePoi.id, first.id, 'Tile POI lookup should return the matching candidate id');
  const resource = candidatesA.find(candidate => candidate.category === 'resourceSite');
  assert(resource, 'Deterministic region should provide a resource-site candidate');
  const resourceFootprint = [];
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      resourceFootprint.push(WorldGen.getPoiForTile(seed, version, resource.anchor.x + dx, resource.anchor.y + dy));
    }
  }
  assertEqual(resourceFootprint.filter(poi => poi?.id === resource.id).length, 1, 'A resource site should expose one searchable anchor rather than a 3x3 marker and loot carpet');
});

test('Danger sites render one anchor while retaining bounded surrounding influence', () => {
  const { App } = loadAppForCombat();
  const WorldGen = loadWorldGenForTest();
  const seed = 'danger-anchor-seed';
  const version = 3;
  const candidate = WorldGen.getPoiCandidatesForRegion(seed, version, 0, 0)
    .find(entry => entry.category === 'dangerSite');
  assert(candidate, 'Deterministic region should provide a danger-site candidate');
  App.worldMeta = { worldId: 'world-danger-anchor', seed, generatorVersion: version, mapModsHash: 'core' };
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  const footprint = [];
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      footprint.push(App.getBaseTile(candidate.anchor.x + dx, candidate.anchor.y + dy));
    }
  }
  const anchors = footprint.filter(tile => tile.overlays?.poi?.category === 'dangerSite');
  const influenced = footprint.filter(tile => tile.overlays?.dangerInfluence?.siteId === candidate.id);
  assertEqual(anchors.length, 1, 'A danger footprint should expose exactly one skull-marker anchor');
  assertEqual(anchors[0].x, candidate.anchor.x, 'Danger marker should stay on the candidate anchor x coordinate');
  assertEqual(anchors[0].y, candidate.anchor.y, 'Danger marker should stay on the candidate anchor y coordinate');
  assertEqual(influenced.length, 9, 'The bounded 3x3 footprint should retain deterministic danger influence');
  assertEqual(anchors[0].overlays.dangerInfluence.modifier, 0.18, 'Anchor pressure should retain the strongest bounded modifier');
  assert(influenced.filter(tile => tile !== anchors[0]).every(tile => tile.overlays.dangerInfluence.modifier === 0.1), 'Surrounding danger influence should use the restrained ring modifier');

  const anchorVisual = App._mapTileVisual(anchors[0]);
  const ringVisual = App._mapTileVisual(influenced.find(tile => tile !== anchors[0]));
  assertEqual(anchorVisual.tilesetKey, 'poi-danger-site', 'Only the anchor should resolve the skull-marker semantic');
  assert(ringVisual.semanticKeys.includes('state-danger-influence'), 'Influence ring should expose its own mod-overridable semantic');
  assertEqual(ringVisual.semanticKeys.includes('state-danger'), false, 'Regional influence should not masquerade as immediate creature danger');
  assertContains(App._mapTileAttrs(ringVisual), 'data-danger-influence="true"', 'All map surfaces should receive restrained danger-influence metadata');
});

test('Landmarks and structures are deterministic by seed and coordinate', () => {
  const first = loadAppForCombat(() => 1);
  const App = first.App;
  App.worldMeta = { worldId: 'world-features-a', seed: 'feature-seed', generatorVersion: 2, mapModsHash: 'core' };
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  App.exploredTiles = new Set();
  let landmarkA = null;
  let structureA = null;
  for (let x = -80; x <= 80 && (!landmarkA || !structureA); x++) {
    for (let y = -80; y <= 80 && (!landmarkA || !structureA); y++) {
      const tile = App.exploreTile(x, y);
      if (!landmarkA && tile.hasLandmark) landmarkA = { coord: [x, y], name: tile.landmarkName };
      if (!structureA && tile.structure) structureA = { coord: [x, y], structure: tile.structure };
    }
  }
  assert(landmarkA, 'Test seed should produce at least one deterministic landmark coordinate even when Math.random is 1');
  assert(structureA, 'Test seed should produce at least one deterministic structure coordinate even when Math.random is 1');
  const second = loadAppForCombat(() => 0);
  second.App.worldMeta = { ...App.worldMeta };
  second.App.worldMap = new Map();
  second.App.tileDeltas = new Map();
  const landmarkB = second.App.exploreTile(landmarkA.coord[0], landmarkA.coord[1]);
  const structureB = second.App.exploreTile(structureA.coord[0], structureA.coord[1]);
  assertEqual(landmarkB.landmarkName, landmarkA.name, 'Same seed and coordinate should reproduce landmark name');
  assertEqual(structureB.structure, structureA.structure, 'Same seed and coordinate should reproduce structure kind');
});

test('Wild encounter generation is deterministic by seed and coordinate outside first entry', () => {
  const buildCase = random => {
    const { App } = loadAppForCombat(random);
    App.worldMeta = { worldId: 'world-wild-a', seed: 'wild-seed', generatorVersion: 2, mapModsHash: 'core' };
    App.worldMap = new Map();
    App.tileDeltas = new Map();
    App.location = { x: 11, y: -7 };
    App.currentBiome = 'forest';
    App.player = makeUnit('Tester', { id: 'tester', species: 'human', level: 4, mc: true, hero: true });
    App.party = [App.player];
    App.player.level = 4;
    const tile = { x: 11, y: -7, biome: 'forest', creatures: [] };
    App.creatures = [];
    App.spawnWildEncounter(tile, false, false);
    return (tile.creatures || []).map(creature => ({
      id: creature.id,
      name: creature.name,
      species: creature.species,
      level: creature.level,
      MPun: creature.MPun,
      CPun: creature.CPun,
      Figh: creature.Figh,
      Feas: creature.Feas,
      Flir: creature.Flir,
      Feed: creature.Feed,
      hunger: creature.hunger,
      disposition: creature.disposition,
      willing: creature.willing
    }));
  };

  const lowRandom = buildCase(() => 0);
  const highRandom = buildCase(() => 0.99);
  assert(lowRandom.length > 0, 'Wild encounter test should generate at least one creature');
  assertEqual(JSON.stringify(lowRandom), JSON.stringify(highRandom), 'Wild encounter generation should not depend on ambient Math.random');
});

test('Sparse map helpers separate generated base tiles from durable deltas', () => {
  const { App } = loadAppForCombat(() => 1);
  App.worldMeta = { worldId: 'world-delta', seed: 'shared-seed', generatorVersion: 1, mapModsHash: 'core' };
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  App.superPatchMap = new Map();
  const base = App.getBaseTile(12, -4);
  assertEqual(App.worldMap.has('12,-4'), false, 'Base tile generation should not materialize compatibility worldMap entries');
  assertEqual(base.explored, false, 'Base tiles should be unexplored');
  const tile = App.getTile(12, -4);
  tile.explored = true;
  tile.description = 'A changed clearing.';
  tile.creatures = [makeUnit('Mouse', { id: 'mouse-1', disposition: App.DISPOSITION.FRIENDLY })];
  App.persistTileDelta(12, -4, tile);
  const delta = App.getTileDelta(12, -4);
  assert(delta, 'Changed effective tile should create a durable delta');
  assertEqual(delta.explored, true, 'Delta should preserve explored state');
  assertEqual(delta.description, 'A changed clearing.', 'Delta should preserve changed description');
  assertEqual(delta.creatures.length, 1, 'Delta should preserve tile entities');
  const effective = App.applyTileDelta(base, delta);
  assertEqual(effective.biome, base.biome, 'Effective tile should inherit generated biome when biome is unchanged');
  assertEqual(effective.elevation, base.elevation, 'Effective tile should retain generated field metadata');
  assertEqual(effective.creatures[0].name, 'Mouse', 'Effective tile should restore delta entities');
});

test('Map generation hooks run on first exploration and persist safe tile metadata', () => {
  const { App, hooks, moduleSystem } = loadAppForCombat(() => 1);
  App.worldMeta = { worldId: 'world-hook', seed: 'hook-seed', generatorVersion: 1, mapModsHash: 'core' };
  App.worldMap = new Map();
  App.tileDeltas = new Map();
  App.exploredTiles = new Set();
  App.superPatchMap = new Map();
  moduleSystem.executeHook = (event, ...args) => {
    hooks.push({ event, payload: args[0], args });
    if (event === 'onMapGenerate') {
      const [tile, x, y, app] = args;
      assertEqual(x, 5, 'Map generate hook should receive the explored x coordinate');
      assertEqual(y, -3, 'Map generate hook should receive the explored y coordinate');
      assertEqual(app, App, 'Map generate hook should receive the live app reference');
      tile.tag = 'CrystalCave';
      tile.name = 'Shimmering Cavern';
      tile.color = '#9b59b6';
      tile.description = 'Hooked description.';
    }
    return Promise.resolve();
  };

  App.getBaseTile(6, -3);
  assertEqual(hooks.length, 0, 'Base tile previews should not emit map generation hooks');

  const tile = App.exploreTile(5, -3);
  const hook = hooks.find(entry => entry.event === 'onMapGenerate');
  assert(hook, 'First tile exploration should emit onMapGenerate');
  assertEqual(hook.args[0], tile, 'Map generate hook should receive the live mutable tile');
  assertEqual(tile.tag, 'CrystalCave', 'Map generate hook should be able to set safe tile tags');
  assertEqual(tile.name, 'Shimmering Cavern', 'Map generate hook should be able to set safe tile names');
  assertEqual(tile.color, '#9b59b6', 'Map generate hook should be able to set safe tile colors');

  const delta = App.getTileDelta(5, -3);
  assert(delta, 'Hook-mutated tile should create a durable tile delta');
  assertEqual(delta.tag, 'CrystalCave', 'Tile delta should preserve hook-provided tag metadata');
  assertEqual(delta.name, 'Shimmering Cavern', 'Tile delta should preserve hook-provided name metadata');
  assertEqual(delta.color, '#9b59b6', 'Tile delta should preserve hook-provided color metadata');
  assertEqual(delta.description, 'Hooked description.', 'Tile delta should preserve hook-mutated core fields');

  const restored = App.applyTileDelta(App.getBaseTile(5, -3), delta);
  assertEqual(restored.tag, 'CrystalCave', 'Restored effective tile should include hook-provided tag metadata');
  assertEqual(restored.name, 'Shimmering Cavern', 'Restored effective tile should include hook-provided name metadata');
  assertEqual(restored.color, '#9b59b6', 'Restored effective tile should include hook-provided color metadata');
  hooks.length = 0;
  App.exploreTile(5, -3);
  assertEqual(hooks.length, 0, 'Revisiting an explored tile should not re-run map generation hooks');
});

