test('Combat target selection is rendered on creature panel cards', () => {
  const { App, elements } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { Figh: 30 });
  const enemy = makeUnit('Enemy', { id: 'enemy-1', disposition: App.DISPOSITION.ENEMY, CPun: 100, con: 1 });
  App.player = player;
  App.party = [player];
  App.creatures = [enemy];
  App.combatState.active = true;
  App.combatState.currentTurn = 0;
  App.combatState.turnQueue = [{ unit: player, initiative: 30 }, { unit: enemy, initiative: 10 }];
  App.nextTurn = function() {};
  App.selectTarget('fight');
  let centerHtml = elements.get('scene-description')?.innerHTML || '';
  assertNotContains(centerHtml, 'creature panel', 'Target picker should not replace center with target guidance');
  assertContains(centerHtml, 'combat-turn-order', 'Combat center should surface passive turn order context');
  assertContains(centerHtml, 'Turn order', 'Combat center should label passive turn order context');
  assertContains(centerHtml, 'Current', 'Combat center should label the current actor');
  assertContains(centerHtml, 'Next', 'Combat center should label the next actor');
  assertContains(centerHtml, 'Enemy', 'Combat center should name the next actor from the queue');
  assertContains(centerHtml, 'combat-selected-intent', 'Target picker should surface selected combat intent as passive center context');
  assertContains(centerHtml, 'Selected intent', 'Target picker should label the selected intent summary');
  assertContains(centerHtml, 'You selected Fight.', 'Target picker should summarize selected actor and action');
  assertContains(elements.get('enemies-content').innerHTML, "toggleCombatTarget('enemy-1')", 'Enemy card should mark selected targets');
  assertContains(elements.get('enemies-content').innerHTML, 'aria-label="Select Enemy as Fight target"', 'Target button should describe selected combat action');
  assertContains(elements.get('enemies-content').innerHTML, 'Enemy can be selected as the fight target.', 'Enemy card should expose targetability to screen readers');
  App.executeActionOnTarget('fight', 'enemy-1');
  assertEqual(enemy.CPun, 100, 'Panel target action should mark before resolving selected enemy');
  assertEqual(App.combatTargetIds.join(','), 'enemy-1', 'Panel target action should preserve selected target for confirmation');
  assertEqual(App.confirmCombatTargets(), true, 'Confirmed target-pick should resolve selected target marks');
  assert(enemy.CPun < 100, 'Panel target action should damage selected enemy');
  centerHtml = elements.get('scene-description')?.innerHTML || '';
  const sceneFeedHtml = elements.get('desktop-scene-feed-latest')?.innerHTML || '';
  assertContains(centerHtml, 'combat-scene-summary', 'Combat center should retain bounded turn context');
  assertNotContains(centerHtml, 'Recent exchange', 'Combat center should not duplicate resolved Scene Feed text');
  assertContains(sceneFeedHtml, 'hit', 'Shared Scene Feed should surface the resolved exchange text');
  assertNotContains(centerHtml, 'executeActionOnTarget', 'Combat center summary should not duplicate target controls');
  assertNotContains(centerHtml, 'executeCombatIntent', 'Combat center summary should not duplicate actor intent controls');
});

