test('Melee combat targeting previews protected attempts and allows exposed back rows', () => {
  const { App, elements } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'player-melee', Figh: 30 });
  const enemy = makeUnit('Backline', { id: 'backline-1', disposition: App.DISPOSITION.ENEMY, CPun: 100, combatRow: 'back' });
  const blocker = makeUnit('Blocker', { id: 'front-blocker-1', disposition: App.DISPOSITION.ENEMY, CPun: 100, combatRow: 'front' });
  App.player = player;
  App.party = [player];
  App.creatures = [enemy, blocker];
  App.combatState.active = true;
  App.activeActor = player;
  player.combatRow = 'front';
  let advanced = 0;
  App.nextTurn = function() { advanced++; };
  App.showActorActions(player);
  assertContains(elements.get('desktop-context-belt').innerHTML, 'data-command-intent="flirt"', 'Talk should remain available when physical reach is blocked by row');
  App.selectTarget('fight');
  const desktopTargetHtml = elements.get('enemies-content').innerHTML;
  assertNotContains(desktopTargetHtml, 'disabled aria-disabled="true"', 'Protected back-row enemy should remain a valid attempt');
  assertContains(desktopTargetHtml, 'data-selection-state="available"', 'Known-impossible protected target should remain available as a warned attempt');
  assertContains(desktopTargetHtml, 'front row closes ranks', 'Desktop target should preview protected back-row failure');
  assertContains(desktopTargetHtml, 'try a social action', 'Desktop target should suggest non-physical counterplay');
  assertNotContains(desktopTargetHtml, 'move rows before choosing', 'Unreachable desktop target should not imply Move Row solves current back-row reach rules');
  const mobileTargetHtml = App.renderMobileUnitChip(enemy, 0, 'creature');
  assertContains(mobileTargetHtml, 'data-selection-state="available"', 'Protected mobile target should remain available as an attempt');
  assertContains(mobileTargetHtml, 'front row closes ranks', 'Mobile target should preview protected back-row failure');
  assertNotContains(mobileTargetHtml, 'move rows before choosing', 'Unreachable mobile target should not imply Move Row solves current back-row reach rules');
  App.updateLanguage('es');
  const command = App._buildPanelInteractionCommand({
    mode: 'combat',
    actors: [player],
    targets: [enemy],
    action: 'fight',
    source: 'combat-targeting',
    constraints: { requireCurrentTurn: true, hostileOnly: true, checkReach: true, checkRows: true }
  });
  const valid = App._validateInteractionCommand(command);
  assertEqual(valid.ok, true, 'Protected back-row physical target should validate as a committed attempt');
  assertEqual(App._dispatchInteractionCommand(command), true, 'Protected back-row attempt should resolve as an in-world failure');
  assertEqual(enemy.CPun, 100, 'Unreachable target should not take damage');
  assertEqual(advanced, 1, 'Unreachable attempt should spend the actor turn');
  assertEqual(App.combatCorrectionMessage, null, 'Unreachable attempt should not leave a UI correction error');
  assertEqual(App.latestSceneBeat.resultKind, 'failure', 'Unreachable attempt should fail in the Scene Feed');
  assertEqual(App.latestSceneBeat.tags.includes('cannot-reach'), true, 'Unreachable attempt should retain its reach-failure semantics');
  blocker.CPun = 0;
  App.updateLanguage('en');
  const exposed = App._buildPanelInteractionCommand({
    mode: 'combat',
    actors: [player],
    targets: [enemy],
    action: 'fight',
    source: 'combat-targeting',
    constraints: { requireCurrentTurn: true, hostileOnly: true, checkReach: true, checkRows: true }
  });
  assertEqual(App._validateInteractionCommand(exposed).ok, true, 'Exposed back-row target should validate once no living front blockers remain');
  App._dispatchInteractionCommand(exposed);
  assert(enemy.CPun < 100, 'Exposed back-row target should take ordinary melee damage');
});

test('Intent reach profiles separate social ranged flying anti-flying and contact rules', () => {
  const { App } = loadAppForCombat(() => 0);
  const ground = makeUnit('Ground', { id: 'reach-ground', Figh: 40, Fuck: 40, Flir: 40, combatRow: 'front' });
  const flyer = makeUnit('Flyer', { id: 'reach-flyer', Figh: 40, flying: true, combatRow: 'back' });
  const anti = makeUnit('Anti', { id: 'reach-anti', Figh: 40, antiflying: true, combatRow: 'front' });
  const ranged = makeUnit('Ranged', { id: 'reach-ranged', Figh: 40, ranged: true, combatRow: 'back' });
  const backline = makeUnit('Backline', { id: 'reach-backline', disposition: App.DISPOSITION.ENEMY, CPun: 100, CPle: 0, MPle: 100, wis: 1, combatRow: 'back' });
  const frontTarget = makeUnit('Frontline', { id: 'reach-frontline', disposition: App.DISPOSITION.ENEMY, CPun: 100, combatRow: 'front' });
  const flyingTarget = makeUnit('Harpy', { id: 'reach-harpy', disposition: App.DISPOSITION.ENEMY, CPun: 100, flying: true, combatRow: 'front', con: 1 });
  App.player = ground;
  App.party = [ground, flyer, anti, ranged];
  App.creatures = [backline, frontTarget, flyingTarget];
  App.combatState.active = true;
  App.nextTurn = function() {};

  assertEqual(App._combatReachResult(ground, backline, 'flirt').canSucceed, true, 'Talk/social should be cross-row by default');
  App.executeActionAgainstTarget('flirt', ground, backline);
  assertContains(App.lastCombatActionResult.result, 'talk', 'Cross-row Talk should resolve normally');
  assertEqual(App._combatReachResult(ground, backline, 'fuck').canSucceed, false, 'Play/Seduce should use contact-social reach by default');
  assertContains(App._combatReachFailureText([ground], backline, 'fuck', App._combatReachResult(ground, backline, 'fuck')), 'front row blocks every path to close contact', 'Contact-social failure should explain protected back-row contact');

  App.executeActionAgainstTarget('feast', ground, backline);
  assertContains(App.lastCombatActionResult.result, 'front row blocks every path to close contact', 'Feast should use a close/contact profile and respect front-row blockers');
  frontTarget.CPun = 0;
  flyingTarget.CPun = 0;
  assertEqual(App._combatReachResult(ground, backline, 'feast').canSucceed, true, 'Feast/contact should reach an exposed back-row target when no front blockers remain');
  backline.CPun = 100;
  frontTarget.CPun = 100;
  flyingTarget.CPun = 100;

  ground.combatRow = 'back';
  App.executeActionAgainstTarget('fight', ground, frontTarget);
  assertEqual(frontTarget.CPun, 100, 'Back-row ordinary melee should not damage a front-row target');
  assertContains(App.lastCombatActionResult.result, 'ordinary melee needs the front row', 'Back-row ordinary melee should explain why the attempt failed');
  App.executeActionAgainstTarget('feast', ground, frontTarget);
  assertEqual(frontTarget.CPun, 100, 'Back-row close/contact Feast should not affect a front-row target');
  assertContains(App.lastCombatActionResult.result, 'close contact needs the front row', 'Back-row contact failure should explain the front-row requirement');
  App.executeActionAgainstTarget('fuck', ground, frontTarget);
  assertEqual(frontTarget.CPle, 0, 'Back-row ground Play/Seduce should not affect a front-row target');
  assertContains(App.lastCombatActionResult.result, 'close contact needs the front row', 'Back-row Play/Seduce failure should explain the front-row requirement');
  ground.combatRow = 'front';

  assertEqual(App._combatReachResult(flyer, frontTarget, 'feast').canSucceed, false, 'Flying actors should not automatically bypass front-row contact rules for Feast');
  assertEqual(App._combatReachResult(flyer, frontTarget, 'fuck').canSucceed, false, 'Flying actors should not automatically bypass front-row contact rules for Play/Seduce');
  assertContains(App._combatReachFailureText([flyer], frontTarget, 'feast', App._combatReachResult(flyer, frontTarget, 'feast')), 'close contact needs the front row', 'Flying back-row contact failure should still require front-row contact');

  App.executeActionAgainstTarget('fight', flyer, backline);
  assert(backline.CPun < 100, 'Flying actor should be able to fight across rows');

  App.executeActionAgainstTarget('fight', anti, flyingTarget);
  assert(flyingTarget.CPun < 100, 'Anti-flying actor should be able to fight a front-row flying target');
  ranged.combatRow = 'front';
  assertEqual(App._combatReachResult(ranged, flyingTarget, 'feast').canSucceed, false, 'Ranged should not count as close-contact reach against flying targets');
  assertContains(App._combatReachFailureText([ranged], flyingTarget, 'feast', App._combatReachResult(ranged, flyingTarget, 'feast')), 'close contact cannot reach', 'Flying contact failure should not recommend ranged as contact reach');
  ranged.combatRow = 'back';
  flyingTarget.CPun = 100;
  flyingTarget.combatRow = 'back';
  assertEqual(App._combatReachResult(anti, flyingTarget, 'fight').canSucceed, false, 'Anti-flying should not bypass protected back-row blockers by itself');
  assertContains(App._combatReachFailureText([anti], flyingTarget, 'fight', App._combatReachResult(anti, flyingTarget, 'fight')), 'front row closes ranks', 'Anti-flying protected-row failure should name blockers');
  flyingTarget.combatRow = 'front';

  flyingTarget.CPun = 100;
  App.executeActionAgainstTarget('fight', ranged, flyingTarget);
  assert(flyingTarget.CPun < 100, 'Ranged actor should be able to fight flying targets');
  frontTarget.CPun = 100;
  assertEqual(App._combatReachResult(ranged, frontTarget, 'fight').canSucceed, true, 'Back-row ranged Fight should reach front-row grounded targets');
  App.executeActionAgainstTarget('fight', ranged, frontTarget);
  assert(frontTarget.CPun < 100, 'Back-row ranged actor should damage a front-row grounded target');

  backline.CPun = 100;
  frontTarget.CPun = 100;
  flyingTarget.CPun = 100;
  ranged.combatRow = 'front';
  assertEqual(App._combatReachResult(ranged, backline, 'fight').canSucceed, true, 'Ranged Fight should bypass front blockers from either row');
  App.executeActionAgainstTarget('fight', ranged, backline);
  assert(backline.CPun < 100, 'Front-row ranged actor should still damage a protected back-row target');
});

