test('Desktop party card management labels localize', () => {
  const { App, elements, body } = loadAppForCombat(() => 0);
  const player = makeUnit('You', { id: 'player-1' });
  const allyA = makeUnit('Ally A', { id: 'ally-a' });
  const allyB = makeUnit('Ally B', { id: 'ally-b', aiOrder: 'defensive' });
  App.player = player;
  App.party = [player, allyA, allyB];
  App.partyLeaderId = 'player-1';
  App.updateLanguage('es');
  App.renderParty();
  let html = elements.get('party-content').innerHTML;
  assertContains(html, 'aria-label="Agregar Ally B como actor"', 'Actor selection control should expose localized accessible role label');
  assertContains(html, '>Actor</button>', 'Actor selection visible label should localize as a role');
  assertContains(html, 'aria-label="Marcar Ally B como objetivo"', 'Target mark control should expose localized accessible label');
  assertContains(html, '>Marcar<', 'Target mark visible label should localize');
  assertNotContains(html, 'aria-label="Acciones del grupo: Ally B"', 'Party card should not expose a duplicate visible action menu');
  assertNotContains(html, "showRadialIntentMenu('party',2,'secondary-click')", 'Living party card should not expose a secondary-click primary-action popup');
  assertNotContains(html, 'aria-label="Luchar Ally B"', 'Party card should not show primary action spam by default');
  assertNotContains(html, 'aria-label="Mostrar estadisticas de Ally B"', 'Collapsed stats control should stay behind the detail expansion');
  assertNotContains(html, 'aria-label="Hacer lider a Ally B"', 'Compact party card should not expose leader management by default');
  assertNotContains(html, 'aria-label="Rol de grupo para Ally B"', 'Compact party card should not expose role selector by default');
  allyB.expanded = true;
  App.renderParty();
  html = elements.get('party-content').innerHTML;
  assertContains(html, 'aria-label="Mostrar estadisticas de Ally B"', 'Expanded stats control should expose localized accessible label');
  assertContains(html, '>Pertenencias<', 'Expanded deep-management route should localize the Holdings label');
  assertContains(html, 'aria-label="Hacer lider a Ally B"', 'Leader control should expose localized accessible label');
  assertContains(html, '>Hacer lider<', 'Leader visible label should localize');
  assertContains(html, 'aria-label="Arrastrar Ally B para reordenar"', 'Drag reorder handle should expose localized accessible label');
  assertContains(html, 'aria-label="Mover Ally B arriba"', 'Move-up control should expose localized accessible label');
  assertContains(html, 'aria-label="Rol de grupo para Ally B"', 'Party role selector should expose localized accessible label');
  assertContains(html, 'title="Rol: Sin rol especial de exploracion."', 'Party role selector title should include localized role description');
  assertContains(html, '<option value="companion" selected>Companero</option>', 'Selected role option text should localize');
  assertContains(html, '<option value="guard" >Guardia</option>', 'Role option text should localize');
  assertContains(html, 'aria-label="Orden IA para Ally B"', 'AI order selector should expose localized accessible label');
  assertContains(html, 'title="Orden IA: Prefiere posicionarse con cuidado y proteger aliados."', 'AI order selector title should include localized AI order description');
  assertContains(html, '<option value="defensive" selected>Defensivo</option>', 'Selected AI order option text should localize');
  assertContains(html, '<option value="passive" >Pasivo</option>', 'AI order option text should localize');
  assertContains(html, 'aria-label="Despedir a Ally B"', 'Dismiss control should expose localized accessible label');
  assertContains(html, '>Despedir<', 'Dismiss visible label should localize');
  App.selectExplorationActor(1);
  assertEqual(App.showIntentMenu('party', 2), false, 'Party action menu should stay suppressed in favor of actor and target selection controls');
  assertNotContains(body.innerHTML, 'aria-label="Luchar Ally B"', 'Suppressed party menu should not duplicate primary actions');
  assertNotContains(body.innerHTML, 'id="mobile-context-menu"', 'Suppressed party menu should not open a context menu');
});

test('Desktop creature card status and detail labels localize', () => {
  const { App, elements } = loadAppForCombat(() => 0);
  const enemy = makeUnit('Murcielago', {
    id: 'bat-1',
    disposition: App.DISPOSITION.ENEMY,
    combatRow: 'back',
    expanded: true,
    stomach: [makeUnit('Stored', { size: 2, alive: true, inStomach: true })]
  });
  App.player = makeUnit('You');
  App.party = [App.player];
  App.creatures = [enemy];
  App.combatState.active = true;
  App.updateLanguage('es');
  App.renderCreatures();
  const panelHtml = elements.get('enemies-content').innerHTML;
  assertEqual(elements.get('enemies-title').textContent, 'Enemigos', 'Enemy panel title should localize');
  assertContains(panelHtml, '<span class="unit-meta-badge">Hostil</span>', 'Creature disposition badge should localize');
  assertContains(panelHtml, 'Fila:Retaguardia', 'Combat row label should localize');
  assertNotContains(panelHtml, 'Tamano:', 'Expanded creature card should keep exact body stats in Stats/detail instead of the card body');
  assertNotContains(panelHtml, 'Apetito:', 'Expanded creature card should keep exact body stats in Stats/detail instead of the card body');
  assertContains(panelHtml, 'Barriga: 2/8', 'Capacity summary should localize container labels');
  assertContains(panelHtml, 'Equipo:', 'Expanded equipment label should localize');

  App.creatures = [];
  App.combatState.active = false;
  App.renderCreatures();
  assertContains(elements.get('enemies-content').innerHTML, 'No hay criaturas presentes', 'Empty creature panel should localize');
  assertContains(elements.get('mobile-creature-strip').innerHTML, 'No hay criaturas aqui', 'Empty mobile creature strip should localize');
});

test('Party management can reorder set leader and dismiss allies', () => {
  const { App } = loadAppForCombat(() => 0, { confirm: true });
  const player = makeUnit('You', { id: 'player-1' });
  const allyA = makeUnit('Ally A', { id: 'ally-a' });
  const allyB = makeUnit('Ally B', { id: 'ally-b' });
  App.player = player;
  App.party = [player, allyA, allyB];
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map([['0,0', { x: 0, y: 0, biome: 'forest', explored: true, creatures: [] }]]);
  App.creatures = [];
  App.partyLeaderId = 'player-1';
  App.explorationActorIds = ['ally-b'];
  App.movePartyMember(2, -1);
  assertEqual(App.party[1], allyB, 'Move up should reorder ally without moving before player');
  App.setPartyRole(1, 'guard');
  assertEqual(App.party[1].partyRole, 'guard', 'Set role should update ally role');
  App.setPartyLeader(1);
  assertEqual(App._getPartyLeader(), allyB, 'Set leader should update leader lookup');
  App.dismissPartyMember(1);
  assert(App.pendingConfirm, 'Dismiss should open an in-app confirmation dialog before removing an ally');
  App.resolveConfirmDialog(true);
  assertEqual(App.party.includes(allyB), false, 'Dismiss should remove ally from party');
  assertEqual(App.partyLeaderId, 'player-1', 'Dismissing leader should fall back to player');
  assertEqual(App.explorationActorIds.includes('ally-b'), false, 'Dismiss should clear selected actor id');
  assertEqual(App.creatures[0].id, 'ally-b', 'Dismissed ally should remain in the current tile creature list');
  assertEqual(App.creatures[0].disposition, App.DISPOSITION.NEUTRAL, 'Dismissed ally should become neutral instead of staying party-owned');
  assertEqual(App.creatures[0].formerPartyMember, true, 'Dismissed ally should be marked as a former party member');
  assertEqual(App.creatures[0].formerPartyRole, 'guard', 'Dismissed ally should remember their former party role');
  assertEqual(App.worldMap.get('0,0').creatures[0].id, 'ally-b', 'Dismissed ally should persist on the current tile');
  assertContains(App.log[App.log.length - 1].text, 'remains nearby', 'Dismiss log should explain where the ally went');
});

test('Party companions can be dropped off persistently and rejoin without duplicate recruitment XP', () => {
  const { App } = loadAppForCombat(() => 0.5);
  const player = makeUnit('You', { id: 'player-drop-off' });
  const companion = makeUnit('Harpy', { id: 'companion-drop-off', partyRole: 'guard', aiOrder: 'defensive' });
  App.player = player;
  App.party = [player, companion];
  App.location = { x: 2, y: -3 };
  App.worldMap = new Map([['2,-3', { ...App.getBaseTile(2, -3), explored: true, biome: 'grove', creatures: [] }]]);
  App.creatures = [];
  App.autoSave = () => true;
  let xpGranted = 0;
  App.gainXP = amount => { xpGranted += amount; };

  assertEqual(App._dropOffPartyMemberConfirmed(1), true, 'Drop Off should remove an eligible companion from the traveling party');
  assertEqual(App.party.length, 1, 'Only the player should continue traveling after drop-off');
  const placed = App.creatures.find(unit => unit.id === 'companion-drop-off');
  assert(placed, 'Dropped-off companion should remain present on the current tile');
  assertEqual(placed.disposition, App.DISPOSITION.FRIENDLY, 'Dropped-off companion should remain friendly');
  assertEqual(placed.droppedOffCompanion, true, 'Dropped-off companion should expose the explicit rejoin contract');
  assertEqual(App.worldMap.get('2,-3').creatures.some(unit => unit.id === 'companion-drop-off'), true, 'Drop-off should persist through tile state');
  assertEqual(App._canRecruit(player, placed), true, 'A dropped-off companion should always be eligible to rejoin while able to travel');

  assertEqual(App.recruitCreature(placed), true, 'Recruit routing should rejoin a dropped-off companion');
  assertEqual(App.party.some(unit => unit.id === 'companion-drop-off'), true, 'Rejoined companion should return to the traveling party');
  assertEqual(App.party.find(unit => unit.id === 'companion-drop-off').partyRole, 'guard', 'Rejoining should preserve the companion role');
  assertEqual(App.party.find(unit => unit.id === 'companion-drop-off').aiOrder, 'defensive', 'Rejoining should preserve the AI order');
  assertEqual(App.worldMap.get('2,-3').creatures.some(unit => unit.id === 'companion-drop-off'), false, 'Rejoining should remove the persistent tile placement');
  assertEqual(xpGranted, 0, 'Rejoining an existing companion should not grant recruitment XP again');
  assertContains(App.log[App.log.length - 1].text, 'rejoins your party', 'Rejoining should use distinct player-facing feedback');
});

test('Dropped-off companions survive save load and rejoin from their persisted tile', async () => {
  const Binary = loadBinaryForTest();
  const savedBuffers = [];
  const first = loadAppForCombat(() => 0.5, { binary: Binary });
  const { App } = first;
  const player = makeSerializableUnit('You', { id: 'player-drop-off-roundtrip' });
  const companion = makeSerializableUnit('Harpy', {
    id: 'companion-drop-off-roundtrip',
    partyRole: 'scout',
    aiOrder: 'defensive'
  });
  App.mode = App.GAME_MODE.NORMAL;
  App.player = player;
  App.party = [player, companion];
  App.location = { x: -4, y: 3 };
  App.currentBiome = 'grove';
  App.worldMeta = { worldId: 'drop-off-world', seed: 'drop-off-seed', generatorVersion: 2, mapModsHash: 'core' };
  App.worldMap = new Map([['-4,3', { ...App.getBaseTile(-4, 3), explored: true, biome: 'grove', creatures: [], items: [] }]]);
  App.tileDeltas = new Map();
  App.exploredTiles = new Set(['-4,3']);
  App.creatures = [];
  App.autoSave = () => true;

  assertEqual(App._dropOffPartyMemberConfirmed(1), true, 'Fixture should drop the companion before saving');
  App.persistWorldStateToMapStore = async () => { throw new Error('force inline world map'); };
  App._dbPut = async (_store, _key, value) => { savedBuffers.push(value); };
  assertEqual(await App._saveToSlotConfirmed('slot1'), true, 'Dropped-off companion state should save');

  const loaded = loadAppForCombat(() => 0.5, { binary: Binary });
  loaded.App._dbGet = async () => savedBuffers[0];
  loaded.App.loadWorldStateFromMapStore = async () => {};
  loaded.App.autoSave = () => true;
  let xpGranted = 0;
  loaded.App.gainXP = amount => { xpGranted += amount; };
  assertEqual(await loaded.App.loadFromSlot('slot1'), true, 'Dropped-off companion state should load');
  assertEqual(loaded.App.party.some(unit => unit.id === 'companion-drop-off-roundtrip'), false, 'Dropped-off companion should not return to the traveling party on load');
  const persisted = loaded.App.creatures.find(unit => unit.id === 'companion-drop-off-roundtrip');
  assert(persisted, 'Dropped-off companion should reload on the current tile');
  assertEqual(persisted.droppedOffCompanion, true, 'Reloaded companion should preserve the explicit rejoin contract');
  assertEqual(persisted.partyRole, 'scout', 'Reloaded companion should preserve its party role');
  assertEqual(persisted.aiOrder, 'defensive', 'Reloaded companion should preserve its AI order');

  assertEqual(loaded.App.recruitCreature(persisted), true, 'Reloaded dropped-off companion should rejoin normally');
  assertEqual(loaded.App.party.some(unit => unit.id === 'companion-drop-off-roundtrip'), true, 'Rejoined companion should return to the party after reload');
  assertEqual(loaded.App.worldMap.get('-4,3').creatures.some(unit => unit.id === 'companion-drop-off-roundtrip'), false, 'Rejoin should remove the loaded tile placement');
  assertEqual(xpGranted, 0, 'Rejoining after reload should not grant duplicate recruitment XP');
});

test('Interior companion drop-off and rejoin persist through the structure origin', () => {
  const { App } = loadAppForCombat(() => 0.5);
  const player = makeUnit('You', { id: 'player-interior-drop-off' });
  const companion = makeUnit('Harpy', { id: 'companion-interior-drop-off', partyRole: 'scout', aiOrder: 'defensive' });
  App.player = player;
  App.party = [player, companion];
  App.location = { x: 9, y: -4 };
  const origin = { ...App.getBaseTile(9, -4), explored: true, biome: 'grove', structure: 'cabin', creatures: [] };
  App.worldMap = new Map([['9,-4', origin]]);
  const interior = App._ensureStructureInterior(origin);
  const roomKey = Object.keys(interior.tiles).find(key => key !== '0,0');
  assert(roomKey, 'Interior fixture should include a room beyond the entrance');
  const [interiorX, interiorY] = roomKey.split(',').map(Number);
  App.inInterior = true;
  App.activeInterior = interior;
  App.interiorLocation = { x: interiorX, y: interiorY };
  App.creatures = [];
  App.autoSave = () => true;
  let xpGranted = 0;
  App.gainXP = amount => { xpGranted += amount; };

  assertEqual(App._dropOffPartyMemberConfirmed(1), true, 'A companion should be droppable in a safe interior room');
  const placed = interior.tiles[roomKey].creatures.find(unit => unit.id === 'companion-interior-drop-off');
  assert(placed, 'The dropped companion should remain in the exact interior room');
  assertEqual(placed.droppedOffAt.interior, true, 'Interior placement metadata should retain its namespace');
  assertEqual(placed.droppedOffAt.interiorX, interiorX, 'Interior placement should retain room x');
  assertEqual(placed.droppedOffAt.interiorY, interiorY, 'Interior placement should retain room y');
  assertEqual(App.tileDeltas.get('9,-4').interior.tiles[roomKey].creatures.some(unit => unit.id === placed.id), true, 'Interior drop-off should persist through the structure origin delta');

  assertEqual(App.recruitCreature(placed), true, 'Returning to the room should allow the companion to rejoin');
  const rejoined = App.party.find(unit => unit.id === 'companion-interior-drop-off');
  assert(rejoined, 'The interior companion should return to the traveling party');
  assertEqual(rejoined.partyRole, 'scout', 'Interior rejoin should preserve the companion role');
  assertEqual(rejoined.aiOrder, 'defensive', 'Interior rejoin should preserve the AI order');
  assertEqual(interior.tiles[roomKey].creatures.some(unit => unit.id === placed.id), false, 'Rejoining should remove the companion from the room');
  assertEqual(App.tileDeltas.get('9,-4').interior.tiles[roomKey].creatures.some(unit => unit.id === placed.id), false, 'Interior rejoin removal should persist through the structure origin delta');
  assertEqual(xpGranted, 0, 'Interior rejoin should not award recruitment XP again');
});

test('Interior companion drop-off survives save load re-entry and persistent rejoin removal', async () => {
  const Binary = loadBinaryForTest();
  const savedBuffers = [];
  const first = loadAppForCombat(() => 0.5, { binary: Binary });
  const { App } = first;
  const player = makeSerializableUnit('You', { id: 'player-interior-roundtrip' });
  const companion = makeSerializableUnit('Harpy', {
    id: 'companion-interior-roundtrip',
    partyRole: 'guard',
    aiOrder: 'defensive'
  });
  App.mode = App.GAME_MODE.NORMAL;
  App.player = player;
  App.party = [player, companion];
  App.location = { x: 11, y: 2 };
  App.currentBiome = 'grove';
  App.worldMeta = { worldId: 'interior-drop-world', seed: 'interior-drop-seed', generatorVersion: 3, mapModsHash: 'core' };
  const origin = { ...App.getBaseTile(11, 2), explored: true, biome: 'grove', structure: 'cabin', creatures: [], items: [] };
  App.worldMap = new Map([['11,2', origin]]);
  App.tileDeltas = new Map();
  App.exploredTiles = new Set(['11,2']);
  const interior = App._ensureStructureInterior(origin);
  const targetRoomKey = Object.keys(interior.tiles).find(key => key !== '0,0');
  assert(targetRoomKey, 'Interior round-trip fixture should include a room beyond the entrance');
  const [targetX, targetY] = targetRoomKey.split(',').map(Number);
  App.inInterior = true;
  App.activeInterior = interior;
  App.interiorLocation = { x: targetX, y: targetY };
  App.interiorEntrySurface = { x: 11, y: 2 };
  App.currentBiome = interior.tiles[targetRoomKey].biome;
  App.creatures = [];
  App.autoSave = () => true;

  assertEqual(App._dropOffPartyMemberConfirmed(1), true, 'Fixture should drop the companion in a non-entry interior room');
  assertEqual(interior.tiles[targetRoomKey].creatures.some(unit => unit.id === 'companion-interior-roundtrip'), true, 'Dropped companion should occupy the selected interior room before saving');
  App.persistWorldStateToMapStore = async () => { throw new Error('force inline world map'); };
  App._dbPut = async (_store, _key, value) => { savedBuffers.push(value); };
  assertEqual(await App._saveToSlotConfirmed('slot1'), true, 'Interior drop-off state should save while the player is inside');

  const loaded = loadAppForCombat(() => 0.5, { binary: Binary });
  loaded.App._dbGet = async () => savedBuffers[0];
  loaded.App.loadWorldStateFromMapStore = async () => {};
  loaded.App.autoSave = () => true;
  loaded.App._worldChance = () => false;
  let xpGranted = 0;
  loaded.App.gainXP = amount => { xpGranted += amount; };
  assertEqual(await loaded.App.loadFromSlot('slot1'), true, 'Interior drop-off save should load');
  assertEqual(loaded.App.inInterior, false, 'Reload should safely resume on the structure surface');
  assertEqual(loaded.App.location.x, 11, 'Reload should preserve the structure origin x coordinate');
  assertEqual(loaded.App.location.y, 2, 'Reload should preserve the structure origin y coordinate');
  assertEqual(loaded.App.party.some(unit => unit.id === 'companion-interior-roundtrip'), false, 'Interior companion should remain outside the traveling party after reload');

  loaded.App.enterStructure();
  assertEqual(loaded.App.inInterior, true, 'Player should be able to re-enter the persisted structure after reload');
  assertEqual(loaded.App.activeInterior.tiles[targetRoomKey].creatures.some(unit => unit.id === 'companion-interior-roundtrip'), true, 'Exact interior room placement should survive reload before traversal');

  const directionById = {
    north: { dx: 0, dy: -1 },
    east: { dx: 1, dy: 0 },
    south: { dx: 0, dy: 1 },
    west: { dx: -1, dy: 0 }
  };
  const startKey = `${loaded.App.interiorLocation.x},${loaded.App.interiorLocation.y}`;
  const queue = [{ key: startKey, path: [] }];
  const visited = new Set([startKey]);
  let route = null;
  while (queue.length && !route) {
    const current = queue.shift();
    if (current.key === targetRoomKey) {
      route = current.path;
      break;
    }
    const room = loaded.App.activeInterior.tiles[current.key];
    for (const directionId of room.connections || []) {
      const direction = directionById[directionId];
      const nextKey = `${room.x + direction.dx},${room.y + direction.dy}`;
      if (visited.has(nextKey) || !loaded.App.activeInterior.tiles[nextKey]) continue;
      visited.add(nextKey);
      queue.push({ key: nextKey, path: [...current.path, direction] });
    }
  }
  assert(route, 'Persisted room graph should retain a route to the dropped companion');
  route.forEach(direction => {
    assertEqual(loaded.App.moveInterior(direction.dx, direction.dy), true, 'Player should traverse each persisted connection toward the companion');
  });
  assertEqual(`${loaded.App.interiorLocation.x},${loaded.App.interiorLocation.y}`, targetRoomKey, 'Traversal should return to the exact drop-off room');
  const persisted = loaded.App.creatures.find(unit => unit.id === 'companion-interior-roundtrip');
  assert(persisted, 'Dropped companion should become active when the exact room is reached');
  assertEqual(loaded.App.recruitCreature(persisted), true, 'Interior companion should rejoin after the reload and return traversal');
  assertEqual(loaded.App.party.some(unit => unit.id === 'companion-interior-roundtrip'), true, 'Rejoined interior companion should return to the traveling party');
  assertEqual(loaded.App.activeInterior.tiles[targetRoomKey].creatures.some(unit => unit.id === 'companion-interior-roundtrip'), false, 'Rejoin should remove the exact-room placement');
  assertEqual(xpGranted, 0, 'Interior rejoin after reload should not grant duplicate recruitment XP');

  const rejoinedBuffers = [];
  loaded.App.persistWorldStateToMapStore = async () => { throw new Error('force inline world map'); };
  loaded.App._dbPut = async (_store, _key, value) => { rejoinedBuffers.push(value); };
  assertEqual(await loaded.App._saveToSlotConfirmed('slot1'), true, 'Rejoined interior state should save');

  const verified = loadAppForCombat(() => 0.5, { binary: Binary });
  verified.App._dbGet = async () => rejoinedBuffers[0];
  verified.App.loadWorldStateFromMapStore = async () => {};
  assertEqual(await verified.App.loadFromSlot('slot1'), true, 'Rejoined interior state should reload');
  const verifiedOrigin = verified.App.worldMap.get('11,2');
  assertEqual(verifiedOrigin.interior.tiles[targetRoomKey].creatures.some(unit => unit.id === 'companion-interior-roundtrip'), false, 'Removed interior placement should remain absent after the final reload');
  assertEqual(verified.App.party.some(unit => unit.id === 'companion-interior-roundtrip'), true, 'Rejoined companion should remain in the party after the final reload');
});

test('Party dismissal confirmation and log localize', () => {
  const cancelled = loadAppForCombat(() => 0, { confirm: false });
  const player = makeUnit('You', { id: 'player-1' });
  const ally = makeUnit('Ally', { id: 'ally-1' });
  cancelled.App.player = player;
  cancelled.App.party = [player, ally];
  cancelled.App.updateLanguage('es');
  cancelled.App.dismissPartyMember(1);
  assertEqual(cancelled.confirmations.length, 0, 'Dismiss should not call the browser-native confirm dialog');
  assert(cancelled.App.pendingConfirm, 'Dismiss should open an in-app confirmation dialog');
  assertEqual(cancelled.App.pendingConfirm.message, 'Despedir a Ally del grupo?', 'Dismiss confirmation should localize');
  assertContains(cancelled.body.innerHTML, 'role="dialog"', 'Dismiss confirmation should render an in-app modal dialog');
  cancelled.App.resolveConfirmDialog(false);
  assertEqual(cancelled.App.pendingConfirm, null, 'Cancelling dismissal should clear pending confirmation state');
  assertEqual(cancelled.App.party.includes(ally), true, 'Cancelled localized dismissal should keep ally in party');

  const approved = loadAppForCombat(() => 0, { confirm: true });
  const approvedPlayer = makeUnit('You', { id: 'player-1' });
  const approvedAlly = makeUnit('Ally', { id: 'ally-1' });
  approved.App.player = approvedPlayer;
  approved.App.party = [approvedPlayer, approvedAlly];
  approved.App.location = { x: 0, y: 0 };
  approved.App.worldMap = new Map([['0,0', { x: 0, y: 0, biome: 'forest', explored: true, creatures: [] }]]);
  approved.App.creatures = [];
  approved.App.updateLanguage('es');
  approved.App.dismissPartyMember(1);
  assertEqual(approved.confirmations.length, 0, 'Approved dismissal should not call the browser-native confirm dialog');
  assertEqual(approved.App.pendingConfirm.message, 'Despedir a Ally del grupo?', 'Approved dismissal confirmation should localize');
  approved.App.resolveConfirmDialog(true);
  assertEqual(approved.App.pendingConfirm, null, 'Approved dismissal should clear pending confirmation state');
  assertContains(approved.App.log[approved.App.log.length - 1].text, 'deja el grupo y permanece cerca', 'Dismiss nearby log should localize');
});

