test('Quest species objectives match exact internal ids and display species labels', () => {
  const { App, elements } = loadAppForCombat();
  const player = makeUnit('You', { xp: 0, xpToNext: 100, gold: 0 });
  App.player = player;
  App.party = [player];
  App.inventory = [];

  const objective = { type: 'defeat', species: 'wolf', required: 1, progress: 0, complete: false };
  assertEqual(App.questSpeciesLabel('wolf'), 'Wolfkin', 'Quest species labels should use player-facing species names');
  assertEqual(App._questObjectiveLabel(objective), 'Defeat Wolfkin', 'Generated objective labels should display localized action and species names instead of raw ids');
  assertEqual(App._questObjectiveMatches('defeat', { species: 'wolf', target: { species: 'wolf' } }, objective), true, 'Internal wolf species id should match exact wolf objective');
  App.species.push(
    { id: 'wolfgirl', name: 'Wolfgirl', icon: '🐺', desc: 'Sapient wolf person' },
    { id: 'wolf_boy', name: 'Wolfboy', icon: '🐺', desc: 'Sapient wolf person' },
    { id: 'moon_scout', name: 'Moon Scout', icon: '🐺', desc: 'Sapient wolf scout', questSpecies: 'wolf' }
  );
  assertEqual(App._questObjectiveMatches('defeat', { species: 'wolfgirl', target: { species: 'wolfgirl' } }, objective), false, 'Wolfgirl species should not satisfy an exact wolf objective');
  assertEqual(App._questObjectiveMatches('defeat', { species: 'wolf_boy', target: { species: 'wolf_boy' } }, objective), false, 'Wolfboy species should not satisfy an exact wolf objective');
  assertEqual(App._questObjectiveMatches('defeat', { species: 'moon_scout', target: { species: 'moon_scout' } }, objective), false, 'questSpecies metadata should not override exact species matching in this pass');
  assertEqual(App._questObjectiveMatches('defeat', { species: 'fox', target: { species: 'fox' } }, objective), false, 'Internal wolf species id should not fuzzy-match fox');
  assertEqual(App._questObjectiveMatches('defeat', { species: 'hyena', target: { species: 'hyena' } }, objective), false, 'Internal wolf species id should not fuzzy-match hyena or other canid-like species');
  assertEqual(App._questObjectiveMatches('consume', { target: { species: 'wolfgirl' } }, { ...objective, type: 'consume' }), false, 'Shared consume progress should use exact species matching');
  assertEqual(App._questObjectiveMatches('seduce', { target: { species: 'wolf_boy' } }, { ...objective, type: 'seduce' }), false, 'Shared seduce progress should use exact species matching');

  const normalized = App._normalizeQuest({
    id: 'wolfkin_hunt',
    title: 'Wolfkin Hunt',
    objectives: [objective],
    reward: { gold: 1 }
  });
  assertEqual(normalized.objectives[0].label, 'Defeat Wolfkin', 'Normalized quest objectives should generate display-name labels when no explicit label exists');
  App.quests = [normalized];
  App.showQuestLog();
  assertContains(elements.get('party-content').innerHTML, 'Defeat Wolfkin', 'Quest log should render the generated display-name objective label');

  const explicit = App._normalizeQuest({
    id: 'explicit_wolf',
    title: 'Explicit Wolf',
    objectives: [{ type: 'defeat', species: 'wolf', required: 1, label: 'Defeat the northern scout' }]
  });
  assertEqual(explicit.objectives[0].label, 'Defeat the northern scout', 'Explicit authored objective labels should be preserved');

  const fallback = App._normalizeQuest({
    id: 'localized-fallback-quest',
    objectives: [{ type: 'travel', required: 1, checkpoints: [{ x: 4, y: 5 }] }]
  });
  assertEqual(fallback.generatedTitle, true, 'Missing quest title should be marked as a core-generated fallback');
  assertEqual(fallback.objectives[0].generatedLabel, true, 'Missing objective label should be marked as a core-generated fallback');
  assertEqual(fallback.objectives[0].checkpoints[0].generatedLabel, true, 'Missing checkpoint label should be marked as a core-generated fallback');
  App.quests = [fallback];
  App.updateLanguage('es');
  App.showQuestLog();
  const fallbackHtml = elements.get('party-content').innerHTML;
  assertContains(fallbackHtml, 'Mision sin titulo', 'Quest log should re-resolve a generated title in the active locale');
  assertContains(fallbackHtml, 'Viajar a objetivo', 'Quest log should re-resolve a generated objective action and target in the active locale');
  assertContains(fallbackHtml, 'Punto de ruta 1', 'Quest log should re-resolve generated checkpoint names in the active locale');
  assertNotContains(fallbackHtml, 'Untitled Quest', 'Generated quest fallback should not leak its original English normalization locale');
  assertNotContains(fallbackHtml, 'Checkpoint 1', 'Generated checkpoint fallback should not leak its original English normalization locale');
});

test('Generated and mod species quest objectives use exact registered ids', () => {
  const { App } = loadAppForCombat(() => 0);
  const registered = new Set(App.species.map(species => species.id));
  Object.values(App.QUEST_TEMPLATES).forEach(template => {
    (template.objectives || []).forEach(objective => {
      if (objective.species) assert(registered.has(objective.species), `Quest template species ${objective.species} should be registered`);
    });
  });
  assertEqual(App.QUEST_TEMPLATES.camp_safety.objectives[0].species, 'wolf', 'Camp safety should keep the internal wolf species id');
  assertEqual(App.QUEST_TEMPLATES.camp_safety.objectives[0].label, 'Defeat a Wolfkin', 'Camp safety should display the player-facing Wolfkin label');

  App.STRUCTURES.test_invalid_quest_giver = {
    name: 'Test Outpost',
    icon: 'T',
    quest: { chance: 1, templates: ['camp_safety'], species: ['missing_species'] }
  };
  const giver = App._createStructureQuestGiver('test_invalid_quest_giver', { x: 4, y: 2 });
  assert(registered.has(giver.species), 'Generated quest giver species should fall back to a registered species id');
  assert(giver.species !== 'missing_species', 'Generated quest giver should not keep an unregistered species id');

  App.species.push({ id: 'modfolk', name: 'Modfolk', icon: 'M', desc: 'Mod registered person' });
  App.SPECIES_CANON.modfolk = {
    sapience: 'person',
    bodyPlan: 'humanoid',
    traits: ['person', 'modded'],
    baselineInteraction: 'sapient',
    interactionEligibility: { social: true, sensitiveSocial: true, feed: true, feast: true, recruit: true }
  };
  const modObjective = { type: 'defeat', species: 'modfolk', required: 1, progress: 0, complete: false };
  assertEqual(App.questSpeciesLabel('modfolk'), 'Modfolk', 'Mod-registered species should provide quest display labels');
  assertEqual(App._questObjectiveLabel(modObjective), 'Defeat Modfolk', 'Mod-registered species objectives should generate localized display-name labels');
  assertEqual(App._questObjectiveMatches('defeat', { target: { species: 'modfolk' } }, modObjective), true, 'Mod-registered species should match exact species objective ids');
  assertEqual(App._questObjectiveMatches('defeat', { target: { species: 'wolf' } }, modObjective), false, 'Mod species objective should not fuzzy-match other species');
  App.species.push({ id: 'modfolk_variant', name: 'Modfolk Variant', icon: 'M', questFamilies: ['modfolk'], desc: 'Mod registered person' });
  assertEqual(App._questObjectiveMatches('defeat', { target: { species: 'modfolk_variant' } }, modObjective), false, 'Mod metadata should not override exact species objective ids');
});

test('Quest turn-in can defer rewards until claimed from quest log', () => {
  const { App, elements } = loadAppForCombat();
  App.player = makeUnit('You', { xp: 0, xpToNext: 100, gold: 0 });
  App.party = [App.player];
  App.inventory = [];
  App.quests = [{
    id: 'deferred_wolf_hunt',
    title: 'Deferred Wolf Hunt',
    status: 'active',
    turnInRequired: true,
    giverName: 'Guide',
    giverLocation: { x: 3, y: -1, label: 'Guide Camp' },
    objectives: [{ type: 'defeat', species: 'wolf', label: 'Defeat wolf', required: 1, progress: 0, complete: false }],
    reward: { xp: 10, gold: 7, items: ['Old Coin'] }
  }];
  const wolf = makeUnit('Wolf', { id: 'wolf-1', species: 'wolf', disposition: App.DISPOSITION.ENEMY });
  App._makeCorpse(wolf, 'fight');
  assertEqual(App.quests[0].status, 'completed', 'Deferred quest should complete objectives');
  assertEqual(App.quests[0].rewardClaimed, false, 'Deferred quest should not mark reward claimed before turn-in');
  assertEqual(App.player.gold, 0, 'Deferred quest should not grant gold immediately');
  assertEqual(App.player.xp, 0, 'Deferred quest should not grant XP immediately');
  App.showQuestLog();
  assertContains(elements.get('party-content').innerHTML, 'Turn In', 'Quest log should expose turn-in action for deferred rewards');
  assertContains(elements.get('party-content').innerHTML, 'Turn in with Guide Camp (3, -1)', 'Quest log should show turn-in route when giver location is known');
  assertContains(elements.get('party-content').innerHTML, 'Show Turn-In', 'Quest log should expose map focus for turn-in location');
  assertContains(elements.get('party-content').innerHTML, 'data-command-surface="quest-log-detail"', 'Quest log should render as a detail command surface');
  assertContains(elements.get('party-content').innerHTML, 'data-command-control="show-quest-turn-in-route"', 'Quest log turn-in route should expose its detail control role');
  assertContains(elements.get('party-content').innerHTML, 'data-command-control="turn-in-quest"', 'Quest log turn-in should expose its detail control role');
  assertContains(elements.get('party-content').innerHTML, 'data-command-intent="turnInQuest"', 'Quest log turn-in should expose its stable intent id');
  assertNotContains(elements.get('scene-description').innerHTML, 'Deferred Wolf Hunt', 'Quest log should not replace center presentation content');
  const focused = App.focusQuestTurnInOnMap('deferred_wolf_hunt');
  assertEqual(focused, true, 'Turn-in map focus should succeed when giver location is known');
  assertEqual(App.largeMapOffset.x, 3, 'Turn-in map focus should pan to giver x offset');
  assertEqual(App.largeMapOffset.y, -1, 'Turn-in map focus should pan to giver y offset');
  App.turnInQuest('deferred_wolf_hunt');
  assertEqual(App.player.gold, 7, 'Turn-in should grant deferred gold');
  assertEqual(App.player.xp, 10, 'Turn-in should grant deferred XP');
  assertEqual(App.inventory[0].name, 'Old Coin', 'Turn-in should grant deferred item');
  assertEqual(App.inventory[0].id, 'quest_item_deferred-wolf-hunt_old-coin_0', 'Deferred quest reward item id should be stable without timestamp entropy');
  assertEqual(App.quests[0].rewardClaimed, true, 'Turn-in should mark reward claimed');
  assertContains(App.log.map(entry => entry.text).join('\n'), 'Quest turned in: Deferred Wolf Hunt.', 'Turn-in success feedback should be logged');
  App.updateLanguage('es');
  App.turnInQuest('deferred_wolf_hunt');
  assertEqual(App.player.gold, 7, 'Duplicate turn-in should not grant gold twice');
  assertContains(App.log[App.log.length - 1].text, 'Deferred Wolf Hunt ya fue entregada.', 'Duplicate turn-in feedback should localize');
  App.quests.push({ id: 'not_ready_quest', title: 'Not Ready', status: 'active', objectives: [], rewards: {} });
  App.turnInQuest('not_ready_quest');
  assertContains(App.log[App.log.length - 1].text, 'Esa mision aun no esta lista para entregar.', 'Not-ready turn-in feedback should localize');
});

