    id: 'terrain_route',
    title: 'Terrain Route',
    status: 'active',
    objectives: [{
      type: 'travel',
      label: 'Cross the marsh',
      checkpoints: [{ label: 'Marsh Crossing', x: 3, y: 1 }]
    }],
    reward: {}
