test('Combat log filter and search preferences persist', () => {
  const { App, storage } = loadAppForCombat();
  App.setLogFilter('loot');
  App.setLogSearch('coin');
  const saved = JSON.parse(storage.get('yaw-log-view'));
  assertEqual(saved.filter, 'loot', 'Log filter should persist');
  assertEqual(saved.search, 'coin', 'Log search should persist');
  assertEqual(saved.collapsed, false, 'Default collapsed state should persist');
  assertEqual(saved.expanded, false, 'Default expanded state should persist');
  App.logFilter = 'all';
  App.logSearch = '';
  App.loadLogViewPreferences();
  assertEqual(App.logFilter, 'loot', 'Stored log filter should reload');
  assertEqual(App.logSearch, 'coin', 'Stored log search should reload');
  storage.delete('yaw-log-view');
  storage.set('fff-log-view', JSON.stringify({
    filter: 'invalid',
    search: 7,
    collapsed: 'true',
    expanded: true,
    injected: 'bad'
  }));
  App.loadLogViewPreferences();
  assertEqual(App.logFilter, 'all', 'Invalid stored filter should fall back to all');
  assertEqual(App.logSearch, '', 'Invalid stored search should fall back to empty');
  assertEqual(App.logCollapsed, false, 'String truthy collapsed state should not collapse the log');
  assertEqual(App.logExpanded, true, 'Real expanded state should survive when collapsed is invalid');
  let normalized = JSON.parse(storage.get('yaw-log-view'));
  assertEqual(normalized.injected, undefined, 'Normalized log view preferences should drop unknown keys');
  assertEqual(normalized.expanded, true, 'Normalized log view preferences should persist sanitized expanded state');

  storage.set('yaw-log-view', '{bad json');
  App.loadLogViewPreferences();
  assertEqual(App.logFilter, 'all', 'Malformed log preferences should reset the filter');
  assertEqual(App.logSearch, '', 'Malformed log preferences should reset search');
  normalized = JSON.parse(storage.get('yaw-log-view'));
  assertEqual(normalized.filter, 'all', 'Malformed log preferences should be overwritten with defaults');

  App.logFilter = 'unsafe';
  App.logSearch = 'x'.repeat(150);
  App.logCollapsed = true;
  App.logExpanded = true;
  App.saveLogViewPreferences();
  normalized = JSON.parse(storage.get('yaw-log-view'));
  assertEqual(normalized.filter, 'all', 'Saving log preferences should sanitize invalid filters');
  assertEqual(normalized.search.length, 120, 'Saving log preferences should clamp search text length');
  assertEqual(normalized.collapsed, true, 'Saving log preferences should preserve real collapsed state');
  assertEqual(normalized.expanded, false, 'Saving log preferences should keep collapsed and expanded exclusive');
});

test('Combat log expand and minimize states persist and stay exclusive', () => {
  const { App, elements, storage } = loadAppForCombat();
  App.log = [{ text: 'Latest field event', type: 'discovery' }];
  App.renderLog();
  const root = elements.get('app');
  const collapseBtn = elements.get('log-toggle-collapse');
  const expandBtn = elements.get('log-toggle-expand');
  App.toggleLogCollapsed();
  assertEqual(App.logCollapsed, true, 'Log should enter collapsed state');
  assertEqual(App.logExpanded, false, 'Collapsed log should clear expanded state');
  assertEqual(root.classList.contains('log-collapsed'), true, 'Collapsed log should apply root class');
  assertEqual(root.classList.contains('log-expanded'), false, 'Collapsed log should remove expanded class');
  assertEqual(collapseBtn.getAttribute('aria-pressed'), 'true', 'Collapsed control should expose pressed state');
  assertEqual(elements.get('log-collapsed-summary').textContent, 'Latest field event', 'Collapsed summary should show latest log entry');
  let saved = JSON.parse(storage.get('yaw-log-view'));
  assertEqual(saved.collapsed, true, 'Collapsed state should persist');
  assertEqual(saved.expanded, false, 'Collapsed state should persist as exclusive');
  App.toggleLogExpanded();
  assertEqual(App.logCollapsed, false, 'Expanded log should clear collapsed state');
  assertEqual(App.logExpanded, true, 'Log should enter expanded state');
  assertEqual(root.classList.contains('log-collapsed'), false, 'Expanded log should remove collapsed class');
  assertEqual(root.classList.contains('log-expanded'), true, 'Expanded log should apply root class');
  assertEqual(expandBtn.getAttribute('aria-pressed'), 'true', 'Expanded control should expose pressed state');
  saved = JSON.parse(storage.get('yaw-log-view'));
  assertEqual(saved.collapsed, false, 'Expanded state should persist as exclusive');
  assertEqual(saved.expanded, true, 'Expanded state should persist');
  App.toggleLogExpanded();
  assertEqual(App.logExpanded, false, 'Expanded toggle should restore normal layout');
  assertEqual(root.classList.contains('log-expanded'), false, 'Restored log should remove expanded class');
});

test('Toast API caps dedupes dismisses and stays separate from activity log', () => {
  const { App, elements } = loadAppForCombat();
  const first = App.showToast({ text: 'Quest ready', type: 'quest', importance: 'major', dedupeKey: 'quest:ready' });
  assertEqual(App.toasts.length, 1, 'Toast API should add a toast');
  assertContains(elements.get('toast-stack').innerHTML, 'Quest ready', 'Toast stack should render toast text');
  assertContains(elements.get('toast-stack').innerHTML, 'data-command-control="dismiss-toast"', 'Toast should expose dismiss command');
  assertContains(elements.get('toast-stack').innerHTML, 'Dismiss notification', 'Toast dismiss label should render through localization');
  assertContains(elements.get('toast-stack').innerHTML, 'role="status" aria-atomic="true"', 'Routine toast should announce as a status update');
  assertEqual(App.log.length, 0, 'Toast API should not create Activity Log entries');

  App.showToast({ text: 'Quest ready again', type: 'quest', importance: 'major', dedupeKey: 'quest:ready' });
  assertEqual(App.toasts.length, 1, 'Matching dedupe key should replace an existing toast');
  assertNotContains(elements.get('toast-stack').innerHTML, 'Quest ready</span>', 'Old duplicate toast text should be replaced');
  assertContains(elements.get('toast-stack').innerHTML, 'Quest ready again', 'Replacement toast should render');

  App.showToast({ text: 'Loot found', type: 'loot', importance: 'major', dedupeKey: 'loot:1' });
  App.showToast({ text: 'Danger nearby', type: 'danger', importance: 'major', dedupeKey: 'danger:1' });
  assertEqual(App.toasts.length, 2, 'Toast stack should cap visible toasts at two');
  assertNotContains(elements.get('toast-stack').innerHTML, 'Quest ready again', 'Oldest toast should be removed when cap is exceeded');
  assertContains(elements.get('toast-stack').innerHTML, 'role="alert" aria-atomic="true"', 'Danger toast should announce assertively');

  App.dismissToast(App.toasts[0].id);
  assertEqual(App.toasts.length, 1, 'Dismiss should remove a toast by id');
  App.clearToasts();
  assertEqual(App.toasts.length, 0, 'clearToasts should remove visible toasts');
  assertEqual(elements.get('toast-stack').hidden, true, 'Empty toast stack should be hidden');

  App.updateLanguage('es');
  App.showToast({ text: 'Aviso', type: 'system', importance: 'major', dedupeKey: 'system:aviso' });
  assertContains(elements.get('toast-stack').innerHTML, 'Descartar notificacion', 'Toast dismiss label should update with language');
});

test('Toast auto-dismiss pauses on hover and resets on tap', () => {
  const realNow = Date.now;
  let now = 1000;
  let nextTimer = 1;
  const timers = [];
  const timerWindow = {
    setTimeout(callback, delay) {
      const timer = { id: nextTimer++, callback, delay, cleared: false };
      timers.push(timer);
      return timer.id;
    },
    clearTimeout(id) {
      const timer = timers.find(entry => entry.id === id);
      if (timer) timer.cleared = true;
    }
  };
  Date.now = () => now;
  try {
    const { App } = loadAppForCombat(() => 0.5, { window: timerWindow });
    const toast = App.showToast({ text: 'Routine', type: 'system', importance: 'normal', dedupeKey: 'timer:routine' });

    assertEqual(toast.persistent, false, 'Routine toast should auto-dismiss');
    assertEqual(timers[0].delay, 6000, 'Routine toast should use the default expiration duration');

    now += 1500;
    const remaining = App.pauseToast(toast.id);
    assertEqual(remaining, 4500, 'Hover/focus pause should preserve remaining toast time');
    assertEqual(timers[0].cleared, true, 'Pause should clear the active expiration timer');

    App.resumeToast(toast.id);
    assertEqual(timers[1].delay, 4500, 'Resume should continue with the preserved remaining time');

    now += 500;
    App.resetToastTimer(toast.id);
    assertEqual(timers[1].cleared, true, 'Tap reset should clear the previous resumed timer');
    assertEqual(timers[2].delay, 6000, 'Tap reset should refill the toast expiration duration');

    timers[2].callback();
    assertEqual(App.toasts.length, 0, 'Expiration timer should dismiss the toast');

    const major = App.showToast({ text: 'Major', type: 'quest', importance: 'major', dedupeKey: 'timer:major' });
    assertEqual(major.persistent, false, 'Major toasts should still self-expire unless explicitly persistent');
    assertEqual(timers[3].delay, 10000, 'Major toasts should use a longer expiration duration');

    const pinned = App.showToast({ text: 'Pinned', type: 'system', persistent: true, dedupeKey: 'timer:pinned' });
    assertEqual(pinned.persistent, true, 'Explicitly persistent toasts should stay pinned');
    assertEqual(timers.length, 4, 'Persistent toasts should not schedule expiration timers');
  } finally {
    Date.now = realNow;
  }
});

