test('Persisted app settings normalize remaining fields before use and save', () => {
  const { App, storage } = loadAppForCombat(() => 0.5, {
    storage: {
      'yaw-settings': JSON.stringify({
        fatalVore: 'true',
        statAbsorption: false,
        highContrast: true,
        reducedMotion: 'yes',
        fontSize: 99,
        partyPlayFightMode: 'unsafe',
        injected: true
      }),
      'yaw-content-prefs': JSON.stringify({ maxTier: 2, explicitDescriptions: true, voreEnabled: true, language: 'en' })
    }
  });

  const originalLog = console.log;
  console.log = () => {};
  try {
    App.init();
  } finally {
    console.log = originalLog;
  }
  assertEqual(App.settings.fatalVore, false, 'String truthy values should not enable boolean settings on startup');
  assertEqual(App.settings.statAbsorption, false, 'Stored false should remain false for known boolean settings');
  assertEqual(App.settings.highContrast, true, 'Stored boolean true should remain true for known settings');
  assertEqual(App.settings.reducedMotion, false, 'String truthy accessibility values should not enable settings');
  assertEqual(App.settings.fontSize, 20, 'Stored font size should clamp on startup');
  assertEqual(App.settings.partyPlayFightMode, 'nonlethal', 'Unknown play-fight mode should reset to the safe default');
  assertEqual(App.settings.injected, undefined, 'Unknown stored setting keys should be dropped from runtime state');

  const normalized = JSON.parse(storage.get('yaw-settings'));
  assertEqual(normalized.injected, undefined, 'Unknown stored setting keys should be dropped from persisted state');
  assertEqual(normalized.fatalVore, false, 'Normalized settings should persist sanitized booleans');
  assertEqual(normalized.fontSize, 20, 'Normalized settings should persist clamped font size');

  App.settings = {
    cockVoreEnabled: true,
    unbirthEnabled: true,
    forcedFeeding: 'true',
    highContrast: 'true',
    fontSize: 12.6,
    partyPlayFightMode: 'lethal',
    injected: 'bad'
  };
  App.saveSettings();
  const saved = JSON.parse(storage.get('yaw-settings'));
  assertEqual(saved.cockVoreEnabled, true, 'Real boolean true settings should persist');
  assertEqual(saved.forcedFeeding, false, 'String truthy values should not persist as enabled booleans');
  assertEqual(saved.highContrast, false, 'String truthy accessibility settings should not persist as enabled');
  assertEqual(saved.fontSize, 13, 'Saved font size should round and clamp');
  assertEqual(saved.partyPlayFightMode, 'lethal', 'Known play-fight mode should persist');
  assertEqual(saved.injected, undefined, 'Unknown settings should not persist');
});

test('Overlays trap focus and restore the opener on close', async () => {
  const { App, elements, document, listeners } = loadAppForCombat();
  const opener = makeElement();
  opener.offsetParent = {};
  document.activeElement = opener;
  App.showScreen('settings');
  assert(App._focusTrap, 'Settings overlay should activate a focus trap');
  assert(listeners.has('keydown'), 'Focus trap should register keydown handling');
  let prevented = false;
  listeners.get('keydown')({ key: 'Escape', preventDefault() { prevented = true; } });
  assertEqual(prevented, true, 'Escape should be consumed by the overlay focus trap');
  assertEqual(elements.get('screen-settings').style.display, 'none', 'Escape should close the overlay');
  await new Promise(resolve => setTimeout(resolve, 0));
  assertEqual(opener.focused, true, 'Closing overlay should restore focus to opener');
});

test('Mobile context menus dismiss on outside pointer only', () => {
  const { App, body, elements, document } = loadAppForCombat();
  const opener = makeElement();
  document.activeElement = opener;
  App.player = makeUnit('You');
  App.party = [App.player, makeUnit('Ally', { id: 'ally-context-menu' })];
  App.showMobilePartyContext(1);
  assertContains(body.innerHTML, 'aria-labelledby="mobile-context-menu-title"', 'Mobile context dialog should reference its visible title');
  assertContains(body.innerHTML, 'id="mobile-context-menu-title"', 'Mobile context dialog title should be addressable');
  const menu = elements.get('mobile-context-menu');
  menu.removed = undefined;
  const inside = makeElement();
  inside.parentNode = menu;
  assert(App._mobileContextOutsideHandler, 'Mobile context menu should register outside pointer dismissal');
  App._mobileContextOutsideHandler({ target: inside });
  assertEqual(menu.removed, undefined, 'Pointer inside the menu should not dismiss it');
  App._mobileContextOutsideHandler({ target: makeElement() });
  assertEqual(menu.removed, true, 'Pointer outside the menu should dismiss it');
  assertEqual(App._mobileContextOutsideHandler, null, 'Closing the menu should clear outside pointer dismissal');
  assertEqual(opener.focused, true, 'Outside dismissal should restore focus to the opener');
});

