  const deleteSlot = loadAppForCombat(() => 0.5, { confirm: false });
  deleteSlot.App.updateLanguage('es');
  const deleteAttempts = [];
  deleteSlot.App._dbDelete = async (_store, key) => { deleteAttempts.push(key); };
