test('Releasing the last swallowed enemy restores combat mode', () => {
  const { App } = loadAppForCombat(() => 0.5);
  const actor = makeUnit('You', {
    id: 'release-combat-holder',
    Feas: 80,
    size: 8,
    appetite: 8,
    stomach: [
      makeUnit('Returned Enemy', {
        id: 'released-last-enemy',
        disposition: App.DISPOSITION.ENEMY,
        CPun: 6,
        MPun: 40,
        size: 2,
        inStomach: true,
        releaseEligible: true,
        progress: 0,
        vitalRemaining: 6,
        vitalMax: 40
      })
    ]
  });
  App.player = actor;
  App.party = [actor];
  App.creatures = [];
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map([['0,0', { ...App.getBaseTile(0, 0), explored: true, biome: 'grove', creatures: [], items: [] }]]);
  App.tileDeltas = new Map();
  App.combatState = { active: false, round: 1, currentTurn: 0, processing: false, xpEarned: 0, turnQueue: [], syncActions: [] };
  App.mode = App.GAME_MODE.NORMAL;
  App.processTurn = function() {};
  let nextTurnCalled = false;
  App.nextTurn = function() { nextTurnCalled = true; };

  const released = App.releaseContained('party', 0, 'stomach', 0);
  const restoredEnemy = App.creatures.find(creature => creature.id === 'released-last-enemy');

  assertEqual(released, true, 'Release command should resolve for intact swallowed enemy');
  assert(restoredEnemy, 'Released enemy should return to active creatures');
  assertEqual(App.combatState.active, true, 'Releasing a living enemy after last-enemy containment should restart combat');
  assertEqual(App.mode, App.GAME_MODE.COMBAT, 'Releasing a living enemy should restore combat mode');
  assert(App.combatState.turnQueue.some(entry => entry.unit === restoredEnemy), 'Restarted combat queue should include the released enemy');
  assert(App.worldMap.get('0,0').creatures.some(creature => creature.id === 'released-last-enemy'), 'Released enemy should persist on the current tile');
  assertEqual(nextTurnCalled, false, 'Release-driven combat restart should not advance a stale inactive turn');
});

