test('Container inventory splits active containment from consumed history', () => {
  const { App, elements } = loadAppForCombat(() => 0);
  const actor = makeUnit('You', {
    id: 'container-split-holder',
    stomach: [
      makeUnit('Active Prey', { id: 'active-prey', CPun: 20, MPun: 100, size: 1, inStomach: true, releaseEligible: true }),
      makeUnit('Consumed Prey', { id: 'consumed-prey', CPun: 0, MPun: 100, size: 1, inStomach: true, state: 'terminal', digestionState: 'terminal', releaseEligible: false, vitalRemaining: 0, vitalMax: 10 })
    ]
  });
  App.player = actor;
  App.party = [actor];

  App.showInventory();
  App.setHoldingsTab('containers');
  const holdings = holdingsHtml(elements);
  const activeIndex = holdings.indexOf('Active Prey');
  const consumedTitleIndex = holdings.indexOf('Consumed');
  const consumedIndex = holdings.indexOf('Consumed Prey');

  assert(activeIndex >= 0, 'Active contained creature should render in the active container list');
  assert(consumedTitleIndex >= 0, 'Consumed section title should render when terminal records exist');
  assert(consumedIndex > consumedTitleIndex, 'Consumed creature should render under the Consumed section');
  assert(activeIndex < consumedTitleIndex, 'Active contained creature should remain before the Consumed section');
  assertContains(holdings, "App.releaseContained('party',0,'stomach',0)", 'Active contained creature should keep Release control by original container index');
  assertContains(holdings, "App.digestContained('party',0,'stomach',0)", 'Active contained creature should keep Digest control by original container index');
  assertNotContains(holdings, "App.releaseContained('party',0,'stomach',1)", 'Consumed creature should not expose Release by its container index');
  assertNotContains(holdings, "App.digestContained('party',0,'stomach',1)", 'Consumed creature should not expose Digest by its container index');
  assertEqual(App._containerUsed(actor, 'stomach'), 1, 'Only active contained creatures should occupy Belly capacity');
});

