test('Desktop play surface renders adjacent movement cells', () => {
  const { App, elements } = loadAppForCombat();
  const ids = ['nw', 'n', 'ne', 'w', 'center', 'e', 'sw', 's', 'se'];
  elements.set('desktop-play-surface', makeElement());
  ids.forEach(id => elements.set(`desktop-play-cell-${id}`, makeElement()));
  elements.get('desktop-play-cell-center').className = 'desktop-play-cell center';
  App.location = { x: 0, y: 0 };
  App.worldMap = new Map();
  App.exploredTiles = new Set(['0,0']);
  App.renderMap();

  const north = elements.get('desktop-play-cell-n');
  assertContains(north.innerHTML, 'desktop-play-cell-icon', 'Desktop north cell should render a visible tile icon');
  assertContains(north.innerHTML, 'desktop-play-cell-label', 'Desktop north cell should render a compact tile label');
  assertContains(north.innerHTML, 'North:', 'Desktop north cell should label its movement direction');
  assertEqual(north.getAttribute('onclick'), 'App.move(0,-1)', 'Desktop north cell should move north');
  assertEqual(north.getAttribute('onkeydown'), "if(event.key==='Enter'||event.key===' '){event.preventDefault();App.move(0,-1)}", 'Desktop north cell should support keyboard movement');
  assertEqual(north.getAttribute('role'), 'button', 'Desktop north cell should expose button semantics while movement is available');
  assertEqual(north.getAttribute('tabindex'), '0', 'Desktop north cell should be keyboard reachable while movement is available');
  assertEqual(north.getAttribute('data-command-surface'), 'stage-traversal', 'Desktop north cell should identify the movement command surface');
  assertEqual(north.getAttribute('data-stage-surface'), 'traversal-cell', 'Desktop north cell should identify as a traversal stage cell');
  assertEqual(north.getAttribute('data-stage-layer'), 'tile', 'Desktop north cell should identify the tile stage layer');
  assertEqual(north.getAttribute('data-stage-cell'), '0,-1', 'Desktop north cell should identify its stable stage cell coordinates');
  const center = elements.get('desktop-play-cell-center');
  assertContains(center.className, 'center', 'Desktop play surface should preserve the center tile');
  assert(center.getAttribute('data-tileset-key'), 'Desktop center tile should expose tileset metadata');
  assertEqual(center.getAttribute('data-stage-surface'), 'current-tile', 'Desktop center tile should identify as the current stage tile');
  assertEqual(center.getAttribute('data-stage-layer'), 'tile', 'Desktop center tile should identify the tile stage layer');
  assertEqual(center.getAttribute('data-stage-cell'), 'center', 'Desktop center tile should identify its stable stage cell');
  assertEqual(center.getAttribute('data-command-surface'), null, 'Desktop center tile should not own normal command controls');

  App.combatState.active = true;
  App.mode = App.GAME_MODE.COMBAT;
  App.player = makeUnit('You', { id: 'player-1', CPun: 80, MPun: 100, CPle: 50, MPle: 100 });
  App.party = [App.player];
  App.activeActor = App.player;
  App.creatures = [makeUnit('Ratfolk', { id: 'rat-stage', disposition: App.DISPOSITION.ENEMY, CPun: 70, MPun: 100, CPle: 20, MPle: 100 })];
  App.renderMap();
  assertEqual(elements.get('desktop-play-surface').classList.contains('combat-active'), true, 'Desktop play surface should expose combat layout state');
  assertEqual(elements.get('desktop-play-surface').getAttribute('data-surface-mode'), 'combat', 'Desktop play surface should identify combat mode');
  const combatStageHtml = elements.get('scene-description').innerHTML;
  assertContains(combatStageHtml, 'desktop-battle-stack', 'Combat desktop center should own the stacked battle rows');
  assertContains(combatStageHtml, 'desktop-battle-lane', 'Combat desktop center stack should include battle lanes');
  assertContains(combatStageHtml, 'micro-tactical-card', 'Combat desktop battle lanes should use micro tactical cards');
  assertContains(combatStageHtml, 'data-command-control="focus-target"', 'Combat desktop party micro cards should retain compact target marks');
  assertContains(combatStageHtml, 'data-command-control="mark-combat-target"', 'Combat desktop enemy micro cards should retain compact combat marks');
  const combatCardRoots = combatStageHtml.match(/<div class="[^"]*micro-tactical-card[^"]*"[^>]*>/g) || [];
  assert(combatCardRoots.every(tag => !tag.includes('onclick=') && !tag.includes('onkeydown=')), 'Combat desktop micro card bodies should remain passive while their mark buttons stay interactive');
  assertNotContains(combatStageHtml, 'class="desktop-battle-unit ', 'Combat desktop battle lanes should not render bulky bespoke combatant cards');
  App.selectTarget('fight');
  const targetingStageHtml = elements.get('scene-description').innerHTML;
  assertContains(targetingStageHtml, "App.executeQuickCombatIntentOnTarget('fight','rat-stage')", 'A targetable combat micro card should execute the pending one-to-one intent from its card body');
  assertContains(targetingStageHtml, 'onkeydown="if(event.target===this', 'A targetable combat micro card should expose keyboard-equivalent quick execution');
  assertContains(north.className, 'combat-stage-hidden', 'Combat desktop north cell should be hidden once enemy lane moves into the center stack');
  assertNotContains(north.className, 'moveable', 'Combat desktop north cell should not present as moveable');
  assertEqual(north.getAttribute('role'), null, 'Combat desktop north cell should not expose button semantics');
  assertEqual(north.getAttribute('tabindex'), '-1', 'Combat desktop north cell should leave keyboard focus for combat controls');
  assertEqual(north.getAttribute('onclick'), null, 'Combat desktop north cell should not dispatch movement clicks');
  assertEqual(north.getAttribute('onkeydown'), null, 'Combat desktop north cell should not dispatch movement keys');
  assertEqual(north.getAttribute('data-command-surface'), null, 'Combat desktop north cell should not advertise a traversal command surface');
  assertEqual(north.getAttribute('data-command-control'), null, 'Combat desktop north cell should not advertise movement commands');
  assertEqual(north.getAttribute('data-command-direction'), null, 'Combat desktop north cell should not advertise a movement direction');
  assertEqual(north.onclick, null, 'Combat desktop north cell should clear its click handler');
  assertEqual(north.getAttribute('data-stage-surface'), 'battle-hidden', 'Combat desktop north cell should identify as hidden combat stage chrome');
  assertEqual(center.getAttribute('data-stage-surface'), 'battle-context', 'Desktop center tile should become the combat turn context in combat');
  assertEqual(elements.get('desktop-play-cell-s').getAttribute('data-stage-surface'), 'battle-hidden', 'Combat desktop south cell should identify as hidden combat stage chrome');
});

test('Desktop traversal hotkeys dispatch through the stage movement command', () => {
  const { App, listeners } = loadAppForCombat();
  const moves = [];
  App.player = makeUnit('You', { id: 'player-1' });
  App.party = [App.player];
  App.screen = 'game';
  App.combatState.active = false;
  App.mode = App.GAME_MODE.NORMAL;
  App.move = (dx, dy) => moves.push([dx, dy]);
  App.initAppMenu();
  assert(listeners.has('keydown'), 'App menu initialization should install the shared keydown handler');

  const keyEvent = (event) => ({
    preventDefault() { this.prevented = true; },
    target: { tagName: 'BODY' },
    ...event
  });
  const east = keyEvent({ key: 'ArrowRight' });
  listeners.get('keydown')(east);
  assertEqual(JSON.stringify(moves.pop()), JSON.stringify([1, 0]), 'ArrowRight should move east through App.move');
  assertEqual(east.prevented, true, 'Handled traversal hotkey should prevent page scrolling');

  const north = keyEvent({ code: 'KeyW', key: 'w' });
  listeners.get('keydown')(north);
  assertEqual(JSON.stringify(moves.pop()), JSON.stringify([0, -1]), 'W should move north through App.move');

  const southeast = keyEvent({ code: 'Numpad3', key: '3' });
  listeners.get('keydown')(southeast);
  assertEqual(southeast.prevented, undefined, 'Numpad3 should remain available to the browser when diagonal travel is disabled');
  assertEqual(moves.length, 0, 'Numpad3 should not dispatch diagonal travel');

  const northwest = keyEvent({ key: 'Home' });
  assertEqual(App._handleTraversalHotkey(northwest), false, 'Home should not be accepted as a traversal hotkey');
  assertEqual(moves.length, 0, 'Home should not dispatch diagonal travel');
});

test('Desktop traversal hotkeys ignore editing overlay and non-exploration states', () => {
  const overlay = makeElement();
  const { App } = loadAppForCombat(() => 0.5, {
    querySelector(selector) {
      return selector.includes('#app-confirm-dialog') ? overlay : null;
    }
  });
  const moves = [];
  App.player = makeUnit('You', { id: 'player-1' });
  App.party = [App.player];
  App.screen = 'game';
  App.combatState.active = false;
  App.mode = App.GAME_MODE.NORMAL;
  App.move = (dx, dy) => moves.push([dx, dy]);

  assertEqual(App._handleTraversalHotkey({
    key: 'ArrowRight',
    target: { tagName: 'INPUT' },
    preventDefault() { this.prevented = true; }
  }), false, 'Traversal hotkeys should not move while typing in an input');
  assertEqual(moves.length, 0, 'Input keypress should not dispatch movement');

  assertEqual(App._handleTraversalHotkey({
    key: 'ArrowRight',
    target: { tagName: 'BODY' },
    preventDefault() { this.prevented = true; }
  }), false, 'Traversal hotkeys should not move while a blocking dialog is open');
  assertEqual(moves.length, 0, 'Dialog keypress should not dispatch movement');

  App.screen = 'settings';
  assertEqual(App._handleTraversalHotkey({
    key: 'ArrowRight',
    target: { tagName: 'BODY' },
    preventDefault() { this.prevented = true; }
  }), false, 'Traversal hotkeys should not move outside the game screen');
  assertEqual(moves.length, 0, 'Settings keypress should not dispatch movement');

  App.screen = 'game';
  App.combatState.active = true;
  assertEqual(App._handleTraversalHotkey({
    key: 'ArrowRight',
    target: { tagName: 'BODY' },
    preventDefault() { this.prevented = true; }
  }), false, 'Traversal hotkeys should not move while combat owns the command surface');
  assertEqual(moves.length, 0, 'Combat keypress should not dispatch traversal movement');
});

